WordHunterWoW_QuestEN = WordHunterWoW_QuestEN or {}
WordHunterWoW_QuestEN[53453] = { title = "To Stomp or Not To Stomp", description = "Like grandpapaook always say: if a wikket gonna huff the swoof from a dookerhole then plug the dookerhole.\n\nThese Da'kani wikkets huffing the green smoke from their dookerholes in the ground. Makes 'em smart and mean. Smart not so bad, mean is bad.\n\nGo into Gorilla Gorge and plug those dookerholes!", objectives = "" }
WordHunterWoW_QuestEN[53454] = { title = "WANTED: Quartermaster Ssylis", description = "Some pirates took off with a supply crate that landed further away from this site then intended.\n\nI don't think there was anything valuable in there, but now the pirates know we're here.\n\nThe leader was one of those big lizard men. The worker that kills him will get double pay for the week!", objectives = "" }
WordHunterWoW_QuestEN[53455] = { title = "WANTED: The Crimson Cutthroats", description = "For numerous and sinister crimes against the Lord Admiral: smuggling, forgery, sailing under false colors, looting, poaching, brigandage, sacking, pillaging, vandalism, impersonating Kul Tiran Naval officers, arson, kidnapping, torture, piracy, perjury, theft and ransacking multiple mead shipments.\n\nA reward is placed on the heads of The Crimson Cutthroats to be paid in full upon proof of their demise.", objectives = "" }
WordHunterWoW_QuestEN[53456] = { title = "WANTED: The Rime Huntress", description = "Attention Interested Parties! A Moneymaking Opportunity Awaits!!!!!\n\nThere's a big wolf hunting people in the pass. She's taken a liking to the taste of goblin. Nobody got time for being eaten by a wolf, so take out the Rime Huntress and I'll pay you for your trouble.\n\n- Suzie Boltwrench", objectives = "" }
WordHunterWoW_QuestEN[53457] = { title = "Quartermaster's Bounty", description = "To defeat the enemy, you will need to keep your equipment in peak condition. If you have been unable to acquire more powerful arms, I can requisition from the quartermaster on your behalf.", objectives = "" }
WordHunterWoW_QuestEN[53458] = { title = "WANTED: Rindlewoe", description = "A monstrous beast of wood and flesh has been terrorizing the nearby river territories. Knowing more about how the creature fights may yield interesting data!\n\nPlease report any and all findings to Suzie Boltwrench in Krazzlefrazz.", objectives = "" }
WordHunterWoW_QuestEN[53459] = { title = "WANTED: Sister Lilias", description = "The Krazzlefrazz Peacekeepers are looking for an able-bodied warrior to eliminate a threat in nearby Corlain.\n\nA witch by the name of Sister Lilias is wanted for the torture and killing of many of our people. Her end would prove a boon to the Horde.\n\nPresent her head to claim your just reward.", objectives = "" }
WordHunterWoW_QuestEN[53461] = { title = "Precious Metals", description = "Hey you! I got a business proposition for ya.The locals here seem to have a thing for silver, and we hit the jackpot with a mine just west of here. \n\nUnfortunately, it's got a bit of a spider problem...\n\nNow, the miners we sent down there are probably goners by now, but there's still some silver left down there. If you can go and fetch it for me, we'll mark it up and make a fortune!\n\nWhat do you say?", objectives = "" }
WordHunterWoW_QuestEN[53462] = { title = "All Wrapped Up", description = "I'm not the only one trapped here in this mine. Grimelock left all of the other miners to the spiders, too.\n\nThere might be some of them still alive out there. Could you help? I'd appreciate it if not all of my friends died.", objectives = "" }
WordHunterWoW_QuestEN[53463] = { title = "An Eight-Legged Curse", description = "That jerk Grimelock sent us down here to the mines, only to pack up and leave us behind when these spiders showed up! Now I'm stuck here with about a million legs and eyes in all directions.\n\nYou look like the tough sort. Can you clear a path for me? I'll make it worth your while.", objectives = "" }
WordHunterWoW_QuestEN[53464] = { title = "The Village of Glenbrook", description = "<The book is a register of the inhabitants of Glenbrook.\n\nAll but a few of the names are crossed out.>", objectives = "" }
WordHunterWoW_QuestEN[53465] = { title = "Tea Party", description = "<You hear footsteps behind you.>", objectives = "" }
WordHunterWoW_QuestEN[53466] = { title = "Vision of Time", description = "You wish to hear how the Mag'har orcs joined the Horde? It may be one of the strangest ways we gained an ally!\n\nIt all began with a plan from Eitrigg. He had a fragment of the Vision of Time that Garrosh Hellscream used to travel to Draenor.\n\nChief Telemancer Oculeth believed there would be a way to go back to Draenor and get the Mag'har orcs to join the Horde.\n\nThis tale begins with a visit to Oculeth in Zuldazar...", objectives = "" }
WordHunterWoW_QuestEN[53467] = { title = "Caverns of Time", description = "Were the shard of the Vision of Time not depleted, I could use it to send you on your way. But my specialty is teleportation, not chronomancy.\n\nTime magic was the province of our former leader, Grand Magistrix Elisande. Much of her knowledge died with her.\n\nIt is said Elisande had mastered incantations known only to the bronze dragons. Perhaps they would be willing to aid your cause.", objectives = "" }
WordHunterWoW_QuestEN[53476] = { title = "The Great Sea Scrolls", description = "<Dust falls from the scroll case as you retrieve it, revealing an ornate etching. The artwork, rendered with obvious care and skill, depicts a scene from a tortollan pilgrimage.\n\nThe container has spaces for twelve rolled scrolls, only one of which is occupied. A complete set would likely be quite valuable to a tortollan collector.>", objectives = "" }
WordHunterWoW_QuestEN[53500] = { title = "Stranger in a Strange Land", description = "Welcome to Stormwind, {race}. I invite you to explore our fair city. Say, you look like someone who enjoys caves and such! We have many dark corners in Stormwind to explore.\n\nAh, but that can wait, a bronze dragon has asked to talk to you. She is sitting under the nearby tree, on an hourglass of all things!\n\nAfter that, an emissary of yours is waiting to welcome you to the city. Sounds like a busy day for you!\n\nHave a pleasant stay, {name}!", objectives = "" }
WordHunterWoW_QuestEN[53502] = { title = "Stranger in a Strange Land", description = "Hi. I'm Ambassador Blackguard.\n\nI am honored to welcome you to Orgrimmar, {race}.\n\n<He smiles unconvincingly.>\n\nAs a lifetime of adventure unfolds before you, be assured that... uh...\n\nYou know what? I've been saying this same greeting all day. Enough's enough.\n\nTalk to Chromie on top of the hourglass, then talk to your emissary. Run along.", objectives = "" }
WordHunterWoW_QuestEN[53550] = { title = "A Change in Leadership", description = "In my experience people do not like to be driven from their homes.\n\nWhile normally we would crush them with the might of the Horde, we do not have time to carry out a lengthy campaign against these creatures.\n\nThey will look to their leaders for hope, inspiration, and guidance. They will find none.\n\nYou are the instrument of my will, {name}. Make them submit to it.", objectives = "" }
WordHunterWoW_QuestEN[53551] = { title = "Elves in the Machine", description = "The Horde have already set up camp here. But we can still strike back.\n\nTheir war machines are terrible to behold, but they are still machines. And machines do not work well when you go in and hack up a bunch of their inner workings.\n\nIf we can sabotage but a few of them, that could mean dozens of lives saved.\n\nLet us make the most of this opportunity.", objectives = "" }
WordHunterWoW_QuestEN[53554] = { title = "BFA 120 E", description = "", objectives = "" }
WordHunterWoW_QuestEN[53563] = { title = "BFA 111-119 E", description = "", objectives = "" }
WordHunterWoW_QuestEN[53566] = { title = "Dark Iron Dwarves", description = "I can't thank ye enough, {name}. Without yer help, Ironfoe would be lost tae us and the Black Anvil could've ne'er been made whole.\n\nBut even more than that, ye've proven to every Dark Iron in the mountain what it means tae be part o' somethin' bigger. Tae be part o' the Alliance.\n\nThe time has come tae let King Anduin know that my people stand with him.", objectives = "" }
WordHunterWoW_QuestEN[53583] = { title = "Adapting Our Tactics", description = "For our best chance to win this war, we must continue to learn and adapt new strategies. There are opportunities for advancement all around us, but they require dedication and perseverance.\n\nI've collected a list of potential research opportunities for you to review. Any one of these might feel small on its own, but together they might just be all the advantage we need.\nLet me know which ones you would like us to pursue.", objectives = "" }
WordHunterWoW_QuestEN[53602] = { title = "Adapting Our Tactics", description = "This war will not be won with strength and might alone. Take in your surroundings while you fight and turn it into an advantage against the enemy.\n\nI have a list of modifications for you to choose from. Any one of these might feel small on its own, but together they might just be all the advantage we need.\n\nLet me know what you would like us to pursue.", objectives = "" }
WordHunterWoW_QuestEN[53604] = { title = "Clearing Them Out", description = "They have amassed an army before us, {name}. But it is no matter. The Horde war machine will not be stopped.\n\nGo into The Master's Glaive and dispatch their warriors. Their sentinels. Any who would raise a blade against my soldiers. \n\nClear out the petty rabble that seeks to delay the inevitable.", objectives = "" }
WordHunterWoW_QuestEN[53605] = { title = "A Glaive Misunderstanding", description = "The kaldorei have brought their siege weaponry to the field. They are currently using it to oppose mine.\n\nWe need these demolishers to reach Teldrassil if we hope to stand any chance of capturing it. Go and destroy their glaive throwers as swiftly as you are able.\n\nThey think they will stop my advance here. They are mistaken. Show them the gravity of their error, {name}.", objectives = "" }
WordHunterWoW_QuestEN[53606] = { title = "Aggressive Inspiration", description = "Nothing rallies the Horde more than their banner standing in the ruin of an enemy stronghold.\n\nGo to Blackwood Den, take the territory there, raise the Horde banners and let none question our dominance over this land.", objectives = "" }
WordHunterWoW_QuestEN[53608] = { title = "Fueling the Horde War Machine", description = "You heard the warchief! We got Azerite shooting outta those ruins over there and night elves tryin' to snag it.\n\nGet to those ruins and collect some of the stuff. This whole attack is done for if the night elves get their hands on that Azerite!", objectives = "" }
WordHunterWoW_QuestEN[53609] = { title = "A Very Clear Message", description = "The Alliance got to the Azerite here before us, the place is crawling with night elves!\n\nKill as many of them as you can see, we gotta make sure none of them deliver even an ounce of Azerite to the Alliance!", objectives = "" }
WordHunterWoW_QuestEN[53610] = { title = "Driving Them Out", description = "This is it, {name}. \n\nLor'danel is all that stands in our way before we capture Darnassus and reclaim Kalimdor. \n\nRout the defenders. We cannot risk allowing a single enemy to escape until we have secured control over the World Tree.\n\nI want this place in order by the time the Warchief arrives.", objectives = "" }
WordHunterWoW_QuestEN[53616] = { title = "Knives of the Forsaken", description = "Tread carefully. All is not as it seems. The butchers who did this still skulk within Astranaar.\n\nIf you find them, give them what they deserve, {name}.", objectives = "" }
WordHunterWoW_QuestEN[53617] = { title = "Mercy for the Mad", description = "The ruin wrought by the Horde is driving the children of the forest mad.\n\nChief among them are Blackwood furbolgs. They have given into the madness and are a threat to everyone. If left to their madness they could strike us from behind while our forces engage the Horde. \n\nIt pains me to ask this, but please, when you are in the Twilight Vale, put these creatures out of their misery before they endanger anyone else.", objectives = "" }
WordHunterWoW_QuestEN[53619] = { title = "Azerite Denial", description = "This substance, Azerite, is hurting Onu... and the Horde seem eager to collect it for themselves.\n\nWe must not let that happen. Collect as much Azerite as you can find. Ensure the Horde do not retrieve it.", objectives = "" }
WordHunterWoW_QuestEN[53621] = { title = "No Horde Allowed", description = "The Horde forces in this area are trying to collect as much Azerite as possible. No doubt they intend to weaponize it.\n\nSlay any Horde forces you can find. They must not be allowed to get their hands on this Azerite!", objectives = "" }
WordHunterWoW_QuestEN[53622] = { title = "Defending Lor'danel", description = "The Horde have invaded from the North! You must protect Lor'danel, {name}. \n\nHelp our forces push back this attack!\n\nI will try to intercept the Warchief. This is our final chance to stop her. Report to Commander Summermoon in my absence.", objectives = "" }
WordHunterWoW_QuestEN[53627] = { title = "A Gift of Azerite", description = "I think we got a handle on things here. You gotta bring all this Azerite back to Zarvik Blastwix at the main camp!\n\nHe's gonna know just how to use this stuff to really take down the Alliance.", objectives = "" }
WordHunterWoW_QuestEN[53641] = { title = "LFGDungeons - BFA - Stromgarde (Arathi)", description = "", objectives = "" }
WordHunterWoW_QuestEN[53665] = { title = "Ready for Battle", description = "Greetings, {name}.\n\nOur recruits are eager to join you on the battlefield.", objectives = "" }
WordHunterWoW_QuestEN[53666] = { title = "Armor Up!", description = "Ah, {name}. Word spreads quickly around here.\n\nUnfortunately, with all these orders coming in I can't afford to talk right now.\n\nIf you're interested in learning more about the armory Fennick can help you with that. He's just outside.", objectives = "" }
WordHunterWoW_QuestEN[53667] = { title = "Welcome to the Workshop", description = "You must be the new guy around here. Name's Margie. And that over there, that's Pixy.\n\nWe run a tight crew here at the workshop. So, if you ever need anything, you know where to find us.\n\nNow, I suggest you head on over and check in with Pixy. She can show you what we have to offer.", objectives = "" }
WordHunterWoW_QuestEN[53668] = { title = "Flightgineer's Network", description = "Now that we control High Perch the skies are ours!\n\nI've laid out a few plans for expanding our routes in this here note. If you'd be so kind as to deliver it to our commander, I'm sure they'll be pleased with our progress.\n\nLet me know when you're ready and l'll send ya on your way.", objectives = "" }
WordHunterWoW_QuestEN[53669] = { title = "The Altar's Power", description = "Looks like construction on the Altar of Storms is complete.\n\nI'm sure Meredith would be more than happy to show you what mysterious powers lie within.", objectives = "" }
WordHunterWoW_QuestEN[53670] = { title = "Beasts of Newstead", description = "Nothing penetrates an enemy's front line like a fierce rider and a well-trained beast. Now that we control Newstead, one of our riders in particular has focused his efforts on training us a few kodos.\n\nGo, check in with Tanauk and find out what these beasts are capable of.", objectives = "" }
WordHunterWoW_QuestEN[53671] = { title = "The Circle's Power", description = "With the Circle of Elements under our control there are opportunities to harness the powers of the elements.\n\nKraga understands these powers quite well. I suggest speaking with her.", objectives = "" }
WordHunterWoW_QuestEN[53672] = { title = "Ready for Battle", description = "Welcome to the warfront, {name}.\n\nOur recruits are eager to join you on the battlefield.\n\nA good place to start would be Ralston. I'm sure he's got a few who could learn much fighting by your side.", objectives = "" }
WordHunterWoW_QuestEN[53673] = { title = "Armor Up!", description = "What've we got 'ere? A fresh, young lad lookin' ta help better prepare our allies fer battle? Well then, Jonathan's always lookin' for a bit o' help ta keep our armory orders in full swing.\n\nI'd offer ta walk ya over, but I've got me hands full here. Ye can find him just over yonder.", objectives = "" }
WordHunterWoW_QuestEN[53674] = { title = "The Altar's Power", description = "With contributions in full swing it's no surprise the Altar of Kings was built with such haste.\n\nI suggest wandering over that way. You might be surprised to see what the Altar has to offer.", objectives = "" }
WordHunterWoW_QuestEN[53675] = { title = "Welcome to the Workshop", description = "Welcome to the workshop!\n\nI told Grumble I thought it best for me ta protect him from unnecessary distractions, but I think it may benefit all of us if ye get a peek at what we're doin' 'round here.\n\nWhy don't ye head on over and see what we have ta offer.", objectives = "" }
WordHunterWoW_QuestEN[53676] = { title = "The Circle's Power", description = "The Circle of Elements presents us with an opportunity to harness great power. One of our allies, Justine, has great knowledge into what this might mean for our efforts.\n\nSeek her out. It's time you discovered the power of the elements.", objectives = "" }
WordHunterWoW_QuestEN[53677] = { title = "Beasts of Newstead", description = "Control of Newstead has allowed our forces to advance. It's also provided Vindicator Banra ample room to continue training his elekk for battle.\n\nI suggest you speak with him to learn more about what these magnificent beasts are capable of.", objectives = "" }
WordHunterWoW_QuestEN[53678] = { title = "Establishing a Connection", description = "Now that we control High Perch the skies are ours!\n\nI've drafted plans for a flight network that provides our allies safe passage. Please, take these notes and deliver them to our commander at once.\n\nI'm happy to provide you with a gryphon that will deliver you to the base when you are ready.", objectives = "" }
WordHunterWoW_QuestEN[53701] = { title = "A Drust Cause", description = "Horde armies are pushing into the heart of Drustvar. Hold the line and drive them back to the holes they crawled out of. Kul Tiras is ours!", objectives = "" }
WordHunterWoW_QuestEN[53711] = { title = "A Sound Defense", description = "Horde forces are attacking Tiragarde Sound. Make them regret every footstep upon our soil!", objectives = "" }
WordHunterWoW_QuestEN[53719] = { title = "Allegiance of the Zandalari", description = "It is decided, {name}.\n\nDe Zandalari will join de Horde.\n\nOur path together has been a long and difficult one. We have lost much together. De Horde has sacrificed for de Zandalari, and vice versa. I can do nothing to honor that commitment except pledge our loyalty.\n\nCollect your Warchief and send them to my throne. I will extend de offer myself.", objectives = "" }
WordHunterWoW_QuestEN[53720] = { title = "Allegiance of Kul Tiras", description = "It is time for her maiden voyage, {name}.\n\nThis aptly named vessel will carry us and her crew across the vast sea to Stormwind Harbor. There we will meet Anduin and I will seal the pact we made so many moons ago.\n\nKul Tiras will stand with the Alliance so long as I am Lord Admiral.\n\nThank you for your assistance in this endeavor.", objectives = "" }
WordHunterWoW_QuestEN[53721] = { title = "Heritage of the Zandalari", description = "You have faced many challenges in your time among de Horde. You carried de pride of de Zandalari on your shoulders and triumphed!\n\nReturn to me. I wish to recognize de example you have set for us all.", objectives = "" }
WordHunterWoW_QuestEN[53722] = { title = "Heritage of the Kul Tiran", description = "Gossip in Boralus has oft reached my ears of your exceptional conduct, {name}.\n\nMeet me before the keep. I wish to commend your efforts on behalf of Kul Tiras.", objectives = "" }
WordHunterWoW_QuestEN[53725] = { title = "A People Shattered", description = "While the monument here was intended to honor the fallen members of the Shattered Sun, it quickly took on a second meaning for the sin'dorei.\n\nIt was not far from here that we lost one of our greatest heroes: Anasterian Sunstrider, the last king of Quel'Thalas. He led our final effort against the Scourge and personally crossed blades with Arthas himself. As we remember the sacrifices it took to reclaim this land, we also remember the sacrifices made in its defense.", objectives = "" }
WordHunterWoW_QuestEN[53734] = { title = "Walk Among Ghosts", description = "Every year, we ask a champion of our people to perform an act of remembrance in honor of those who fell to the Scourge. Lady Liadrin has performed this ritual, as have I, among others. This year, I am honored to give the task to you.\n\n<The Regent Lord hands you an ornate lantern.>\n\nThis lantern carries a flame born of the Sunwell. I would ask that you bring it to locations that were significant to the fall of the Sunwell and of Quel'Thalas, and to light the memories we cannot forget.", objectives = "" }
WordHunterWoW_QuestEN[53735] = { title = "The First to Fall", description = "Arthas cut through the land itself to get to the Sunwell. The Dead Scar is a constant reminder of that desecration. Where it starts is where our first line of defense attempted to hold the Scourge at bay. It is where the first blood was spilled.\n\nIt was a slaughter.\n\nTake the lantern to the base of the Dead Scar, and use its light to reveal the memories of what happened there.", objectives = "" }
WordHunterWoW_QuestEN[53736] = { title = "Lament of the Highborne", description = "The next memory...\n\nForgive me. For many of our people, it was when we realized death was coming for us.\n\nA memorial to a particular defender lies to the west, in the place of her home. The light there has no doubt attracted some of the area's lingering souls. Clear them out, and then relight the flame.", objectives = "" }
WordHunterWoW_QuestEN[53737] = { title = "The Day Hope Died", description = "The Ranger-General fell just east of Fairbreeze Village, where she was holding the line to protect the civilians as they retreated to Silvermoon. If it wasn't for her, our people would number even less than we do now.\n\nShine the lantern upon the battlefield, and witness how her forces ultimately broke under Arthas's personal assault.", objectives = "" }
WordHunterWoW_QuestEN[53738] = { title = "Defense of Quel'Danas", description = "With our best defenders defeated and the line broken, Arthas made quick work of Silvermoon's remaining forces and tore through the city.\n\nThis is where we part ways. I must return to Silvermoon before Halduron starts sending rangers to search for me.\n\nThe dragonhawk master in Fairbreeze Village has orders to fly you to Quel'Danas. Someone much more familiar with the events on the island will meet you there.", objectives = "" }
WordHunterWoW_QuestEN[53760] = { title = "Unintended Consequences", description = "<Xal'atath speaks once more.>\n\nThe servants of N'Zoth prepare for their master's return. They intend to conjure a scouring storm to wash away all unbelievers.\n\nThe particular ritual they will invoke requires three ancient artifacts. One of void, one of storm, and one of ocean.\n\nEven now, I hear the void relic calling to me. It is being empowered... or corrupted, I am not sure which. I see it upon a cliff, overlooking a vast sea.\n\nCome, {class}. We can find a much better use for such a prize.", objectives = "" }
WordHunterWoW_QuestEN[53761] = { title = "The Pirate's Treasure", description = "I sense another relic. A trident thought lost to the depths. It calls to me, {name}. Do you hear it too?\n\nIts song takes form. I see a harbor to the east. An ambitious pirate, greedy and proud. Completely unaware of the power hidden within her hoard of gold.\n\nThe would-be-captain's hubris will not permit her to simply hand over her prize. I fear she must be taught a rather harsh lesson.\n\nBut that is your specialty, is it not?", objectives = "" }
WordHunterWoW_QuestEN[53762] = { title = "The Tempest Crown", description = "<Xal'atath breathes in deeply and smiles.>\n\nMy strength grows. I can see it clearly now... the third relic we seek. The crown known as Tempest Caller.\n\nHow fitting that after the fall of Atal'Gral, the gluttonous Toatana would be the one to find the artifact. He was always scuttling about the depths, seeking treasures for his collection.\n\nToatana's greed has left him trapped within a cave he can never leave. The crown awaits us there.", objectives = "" }
WordHunterWoW_QuestEN[53763] = { title = "Twist the Knife", description = "The relics are ours... as it was meant to be.\n\nThere is but one more step needed for the great truths to be revealed.\n\nThe naga sought to summon their storm from a place that echoes with ancient power. Though this site has had countless names over the ages, you mortals know it as the Precipice of Oblivion.\n\nI will go on ahead and begin preparations. Join me there.", objectives = "" }
WordHunterWoW_QuestEN[53765] = { title = "His Eye Upon You", description = "Something dark has taken root within you, {name}. The tendrils of N'Zoth are burrowing into your mind and soul, eager to consume everything you are.\n\nI can perform a rite of cleansing, but only in a place that resonates with the very power that grips you. \n\nMeet me near the Crucible of Storms. The ritual will be perilous and painful, but it is your only chance to be free.\n\nThe Old God has eyes everywhere. I do not wish you to become one of them.", objectives = "" }
WordHunterWoW_QuestEN[53766] = { title = "His Eye Upon You", description = "<Talanji seems to regard you with concern.>\n\nDark mojo has fallen upon you, {name}. I can sense de tendrils of N'Zoth delving deep into your mind.\n\nDis evil must be purged... before it claims your very soul!\n\nGo to de Altar of Akunda in de Terrace of de Chosen. Seek out Nailok, one of de priests of Akunda. He is your best chance to be cleansed of de wicked curse dat grips you.", objectives = "" }
WordHunterWoW_QuestEN[53774] = { title = "Wisdom of the Warchief", description = "Champion. For a brief moment after the battle with G'huun, the spirit of our old warchief, Vol'jin, appeared in view of all in Zuldazar.\n\nI had a hundred questions to ask my old friend, but his spirit faded before I could muster my voice.\n\nI have asked Talanji to perform her seance once more, so that I might speak with the spirit of Vol'jin.\n\nWill you collect the Glaive of Vol'jin from its resting place at the base of the pyramid and then join us at Zanchul?", objectives = "" }
WordHunterWoW_QuestEN[53775] = { title = "Shades of Disruption", description = "Vol'jin's spirit is a slippery one. I have asked Master Gadrin and Spiritwalker Ebonhorn to aid us in calling him forth.\n\nDis ritual will not be easy, and I ask you to be on your guard should anything other than Vol'jin appear.", objectives = "" }
WordHunterWoW_QuestEN[53776] = { title = "To the Broken Shore", description = "Da Broken Shore be where I fell in battle. We were overrun, demons everywhere. Sylvanas was doing what she could, but Thrall was down and I had fallen. It was horror.\n\nAnd now I need ya to take me back dere. Take me glaive to da battlefield, call to me, and I will come. Perhaps if I be in da spot where me blood was spilled, we might shine some light on dis mystery.", objectives = "" }
WordHunterWoW_QuestEN[53777] = { title = "Where He Died", description = "Dis time, I need to bring ya to my side.\n\nWe gonna walk da shadows between life and death, see if we can't uncover some clues.\n\nBe careful, {name}, and be armed. Not everything on dis side wants us to find answers.\n\nPrepare yourself, den speak with me when ya be ready.", objectives = "" }
WordHunterWoW_QuestEN[53778] = { title = "Where He Fell", description = "Dis be da spot, mon. Dis be where da Legion led our forces into a trap and drove a blade into me belly.\n\nSylvanas pulled me from da ruin of da battlefield. She saved da Horde dat day. Come, let us walk around dis place and see what we can learn from da echoes of da past.", objectives = "" }
WordHunterWoW_QuestEN[53779] = { title = "The Lies of a Loa", description = "Hidden memories, spirits attackin' us for investigating, and a long road of bodies in da wake of me makin' Sylvanas warchief.\n\nI be thinkin' it time ya speak with Ol' Bwonsamdi. Odd as it sounds, dis don't seem like his style. Dat don't mean he not be behind it.\n\nYa best work with Talanji. From what little I been seein', da death loa got a soft spot for her highness. You can confront Bwonsamdi at his necropolis in Nazmir. Just... be respectful.", objectives = "" }
WordHunterWoW_QuestEN[53780] = { title = "Jailor of the Damned", description = "I be havin' many rivals when it comes to claimin' souls. But it takes some serious mojo to do to Vol'jin what ya describe. Dat kind of power smells of old magic.\n\nIcecrown. It be more dan a pretty throne. It be an anchor dat holds dis world to da next, ya might say.\n\nI gonna open a death gate, and ya can go through and ask da Lich King if he be treadin' on Ol' Bwonsamdi's ground.", objectives = "" }
WordHunterWoW_QuestEN[53781] = { title = "Eyir", description = "Not many got da stones or da mojo to take what be mine. Ol' Bwonsamdi always be gettin' his share.\n\nDa way Talanji be tellin' it, Vol'jin's spirit may be gettin' help from some other power. And dere be few who love to mess with souls like Eyir. A meddlin' one she be, with her wings and her valor.\n\nYa best be seein' her in person. She be found in her vault at Skold-Ashil. And ya best not mention me name, or she might be sendin' ya back to me faster dan any death gate.", objectives = "" }
WordHunterWoW_QuestEN[53782] = { title = "Mysteries of Death", description = "Hmph. Well, da Lich King and dat bossy val'kyr not be me only rivals. But dey were da ones most likely ta be behind all dis. Someone be playin' with very ancient mojo.\n\nTell Vol'jin's spirit dat da answers he be lookin' for not be found in da world of da living. He gonna need to go beyond da veil ta learn what needs knowin'.\n\nDere be some places on dat side only he can go.", objectives = "" }
WordHunterWoW_QuestEN[53783] = { title = "In the Dunes", description = "This schematic you found is encrypted. My tools are no good on it, not without risking the integrity of the data.\n\nHowever, I do know a guy who can definitely crack this cookie: Mr. Dataguru Gryzix.\n\nIf I remember correctly, he's been vacationing on a beach in Vol'dun since the war broke out. Something about not getting the recognition he deserves. \n\nAnyways, I am sure you can convince him to help you.", objectives = "" }
WordHunterWoW_QuestEN[53787] = { title = "Modular Construction", description = "The Abandoned Junkheap is home to some seriously deadly gnomish constructs. These constructs contain Mecha-Cores which could come in handy for crafting the Ub3r-Spanner. Legend has it that it could forge creations unlike anything we've ever seen!\n\nYou look like the adventurous type, {name}. Can you go scrap up some mechs?\n\nDon't forget your Arclight Spanner!", objectives = "" }
WordHunterWoW_QuestEN[53791] = { title = "The Pride of the Sin'dorei", description = "{name}, Lor'themar Theron has requested your presence in Silvermoon.\n\nHe's asking for your assistance with a ceremony of great importance.", objectives = "" }
WordHunterWoW_QuestEN[53802] = { title = "Sethrak Persuasion", description = "Let me see the schematic...\n\nYeah, yeah, alright. I can help you.\n\nI am going to need a few things to power my decoder.\n\nI need a way to channel electricity from the air around us. What better than to steal...I mean borrow some lightning rods from the sethrak that have been trying to steal my tech for weeks now!\n\nI'm sure you'll have to do some \"convincing\", but you seem like a pretty convincing {race}.", objectives = "" }
WordHunterWoW_QuestEN[53805] = { title = "A Friend in Needle", description = "You can see me?\n\nOh, thank goodness! I thought I was lost in the folds of time...again!\n\nBut for one to see through the folds of time's fabric... you must be a very talented tailor, indeed.\n\nWould you bring me some cloth, then, tailor? I believe I'll be able to place just when I am with your help and right myself.", objectives = "" }
WordHunterWoW_QuestEN[53806] = { title = "Heavy is the Head", description = "Okay, I am going to need one more thing from you.\n\nThe sethrak leader, Warlord Surgios, has been a real pain for me.\n\nHe stole my mind enhancer. I can't do my work without it.  It will make me be able to think much more clearly, and make less...deadly mistakes.", objectives = "" }
WordHunterWoW_QuestEN[53807] = { title = "A Stitch in Time", description = "Hm...I don't know that I've ever been to this time, before.\n\nI suppose I should explain myself. My name is Delormi, and I'm the last remaining member of the Synchronous Tailors.\n\nWe make sure the fabric of time stays, well, mended. But I've found a number of new tears cropping up.\n\nIn fact, I believe that's why I've arrived here in this time. Perhaps you could assist me in tracking them down and repairing them?", objectives = "" }
WordHunterWoW_QuestEN[53810] = { title = "The Severed Thread", description = "Do you see that? There's a corpse just ahead.\n\nTo think the caverns have been so badly overrun...\n\nWe should look at the bodies. Maybe there will be something of use to us.", objectives = "" }
WordHunterWoW_QuestEN[53811] = { title = "Children's Week", description = "Thank you for coming by to celebrate Children's Week, {class}. You are going to make one little boy very happy!\n\nTake this whistle. With it, you will be able to call for the child you have agreed to take care of this week. It will serve no use after Children's Week ends, as is custom.\n\nWhen you are ready, use the whistle and meet your new ward! I know he is ecstatic to meet you.", objectives = "" }
WordHunterWoW_QuestEN[53813] = { title = "Rolling Up the Sleeves", description = "The Caverns of Time? Strange... I spent many timelines in this very place.\n\nWhat's special about here-- now?\n\nWe'll have to discern as much later on. It looks like we aren't the only ones who've been affected by these rifts...\n\nLet's do the Bronze Dragonflight a favor and clear out these anomalies.", objectives = "" }
WordHunterWoW_QuestEN[53815] = { title = "Whatever Happened to Saffy Flivvers?", description = "When Azerite was discovered, my friend Saffy was sent to investigate what it could do. There was an attack and we all thought she'd died. Then it turns out she was forced to work in some kind of goblin think tank in Tanaris! But before we could get her out, the whole place exploded.\n\nNow, my bosses have written her off as dead. But she wasn't dead the first time so I'm not sure she is now. I've been told not to go looking for her, but you could take a look.\n\nFind Saffy, or what's left of her?", objectives = "" }
WordHunterWoW_QuestEN[53816] = { title = "Some Reassembly Required", description = "<The word \"Feathers\" has been etched onto the broken mechanical creature -- the sort of thing the person you are looking for might have created. Collecting the pieces and recreating the mechanical construct will surely give you a clue as to their fate. \n\nThe area is crawling with Venture Co. scavengers and goons. Their pockets are probably filled with mechanical bits you could use to fix Feathers.>", objectives = "" }
WordHunterWoW_QuestEN[53817] = { title = "Whatever Happened to Grizzek Fizzwrench?", description = "When this whole Azerite mess began I had a goblin named Grizzek Fizzwrench do some research for me. He was bad for business and had to be removed from the picture. I thought it was a done deal, only now I'm hearing maybe he's not so dead.\n\nI need you to hunt this guy down and see what happened. If he's alive, eliminate him and I'll add the standard mercenary fee to your reward.", objectives = "" }
WordHunterWoW_QuestEN[53818] = { title = "Re-parrot", description = "<Though very damaged, and filled with insects, you can tell Feathers seems to have some sort of recall program. \n\nFixing the mechanical bird and following it back to the source may bring you to the person you seek.\n\nYou were able to put the thing back together. How hard could debugging a mechanical parrot be?>", objectives = "" }
WordHunterWoW_QuestEN[53819] = { title = "Return to the Nest", description = "<You decide to activate the recall subroutine. Perhaps the parrot will lead you to the person you are looking for.>", objectives = "" }
WordHunterWoW_QuestEN[53820] = { title = "She's in a Happier Place", description = "Aww, Kelsey...she's been such a good friend. I meant to let her know I was alive eventually, but I got distracted.\n\nAzerite, the war, the near-death experience... We've been really busy. Being presumed dead has some advantages, though. We've done a lot of research and we just need a better lab-\n\nOkay. New plan.  Tell Kelsey we'll be in touch, but only Kelsey. Tell everyone else I'm dead - for now. If you keep quiet about Grizzek, you- you can have Feathers.\n\nDo we have a deal?", objectives = "" }
WordHunterWoW_QuestEN[53821] = { title = "He's Dead, Jastor", description = "Hey, uh, so I got a good thing goin' on here, and I really don't want Gallywix to know I'm alive.\n\nI'll make you a deal. You spin some story about how you only found tiny pieces of me spread across Tanaris and that I am totally dead, and... And you can keep the bird.\n\nDeal?", objectives = "" }
WordHunterWoW_QuestEN[53823] = { title = "A Queen's Entourage", description = "Princess Talanji was very clear in her orders.\n\nYou, {name}, are to join her at de steps of Zanchul. She wishes to have you at her side while she undergoes de rite of queens and kings. I hope you can comprehend what an honor that is.\n\nDe queen-to-be will explain what it is you are to do.\n\nNow go, and Pa'ku's winds make you swift.", objectives = "" }
WordHunterWoW_QuestEN[53824] = { title = "The Rite of Kings and Queens", description = "Now that you are here, we can begin this sacred rite.\n\nTake your place beside Talanji, {name}. She has chosen you for an important task. I will explain while we make our way to Zanchul.", objectives = "" }
WordHunterWoW_QuestEN[53825] = { title = "The New Zanchuli Council", description = "These are sobering developments {name}.\n\nI wish to speak to my priests about what has transpired. I would like you to continue into de depths of Zanchul and up de steps into de Council Chambers. There you will find de new council I have assembled.\n\nGreet them, and make note of my choices. I hope you will find them adequate.", objectives = "" }
WordHunterWoW_QuestEN[53826] = { title = "The Instigator Among Us", description = "This situation can be swiftly dealt with if we take out de one that incited this violence.\n\nI heard reports of an enforcer rousing de vagrants and drudges against de shopkeepers and guards in de Zocalo.\n\nOne of my own would not do this without cause. See if you can determine de reason for this sudden change.\n\nI am told her name is Malzon. I hope for her sake that she surrenders.", objectives = "" }
WordHunterWoW_QuestEN[53827] = { title = "The Council Has Spoken", description = "Now that you see who I have chosen for my council, it is time to receive their blessing.\n\nIt is a symbolic demonstration of support, but I believe there is power in words as well as deeds. When they declare themselves to me, de eyes of de loa are also upon them.\n\nI hope they like what they see, {name}. I know I do.", objectives = "" }
WordHunterWoW_QuestEN[53828] = { title = "Gaze of the Loa", description = "My council has given their blessing and we have dealt with an enemy. All that remains is to face de judgment of my loa.\n\nI do not know what this part will be like. My father never spoke of it, at least not to me.\n\nWalk with me. I will explain what is expected of you through this final trial.", objectives = "" }
WordHunterWoW_QuestEN[53830] = { title = "Queen of the Zandalari", description = "De loa have seen fit to grant me de crown. My council accepts me. My priests have given their blessing. My people have expressed their displeasure, but I am determined to right those wrongs.\n\nIt is time to accept de responsibility of leadership. I will address them and speak on our future. I would be honored if you would take a place at my side while I do so.", objectives = "" }
WordHunterWoW_QuestEN[53831] = { title = "A Royal Occasion", description = "You wish to hear how the Zandalari joined the Horde? My people have had a... difficult history with the Zandalari.\n\nHowever, I believe we dealt with the Zandalari of the past. The now Queen Talanji is much different from her father.\n\nI'm rambling, my apologies. Our tale begins after the Alliance sacked the city of Zuldazar and killed King Rastakhan.\n\nThe Horde had been invited by the then Princess Talanji to witness her coronation in Zuldazar...", objectives = "" }
WordHunterWoW_QuestEN[53833] = { title = "Vengeful Venture", description = "<You pick up the note and deduce that the Venture Co. are the killers of Dataguru Gryzix. You search his corpse, and find that his decoder and the Ub3r-Spanner schematic have been stolen.\n\nYou need to retrieve his decoder and the schematic and bring them back to Shuga Blastcaps to have any hope of crafting the Ub3r-Spanner.\n\nThat mech you have following you should prove itself useful.>", objectives = "" }
WordHunterWoW_QuestEN[53835] = { title = "Something Valuable, Perhaps?", description = "<The tablet is too worn to be read. While some of the characters are legible, reading the tablet will be impossible without assistance.\n\nYou can discern only a single word: Aegrim.>", objectives = "" }
WordHunterWoW_QuestEN[53836] = { title = "Ancient Armor, Ancient Mystery", description = "By my beard! Do you know what this is?! It's an ancient tablet that describes how to forge the Bulwark of the Mountain King!\n\nThe last one to wear that armor was Aegrim Bronzebeard, my ancestor and thane of the Bronzebeard clan.\n\nTalk to Advisor Belgrum. He'll know more about Aegrim's past, and might be able to shine some light on the legends of his armor.", objectives = "" }
WordHunterWoW_QuestEN[53837] = { title = "Watch Yer Back", description = "Aegrim, you say? Bulwark of the Mountain King? Well, if we are going to start anywhere, it has to be Aegrim's study. The entrance lies below us in the depths of Old Ironforge.\n\nThe only trouble is the troggs in our way. How about you take the lead?", objectives = "" }
WordHunterWoW_QuestEN[53838] = { title = "Keep Yer Feet On The Ground", description = "{name}! The Explorers League is setting up a new exhibit in the Hall of Explorer.\n\nA team of dwarves went in search of new artifacts to display in it.\n\nThey headed off to Gol'Bolar Quarry in Dun Morogh, but haven't returned. Would you mind checking in on them?", objectives = "" }
WordHunterWoW_QuestEN[53839] = { title = "Aegrim's Study", description = "This leads to Aegrim's study. I still have some scrolls to sort, so I will leave you to search the study at your leisure.\n\nI'm sure Brann would be most interested in any of your findings.", objectives = "" }
WordHunterWoW_QuestEN[53840] = { title = "Interest Yah In A Pint?", description = "The armor may be shattered, but there's still hope. With the fragments you found, we might be able to forge it anew.\n\nThis is far outside my area of expertise, but there may be someone who can help. We should speak with Grumnus Steelshaper. He retired to Thelsamar in Loch Modan.\n\nGo on ahead, I'll meet you there.", objectives = "" }
WordHunterWoW_QuestEN[53841] = { title = "Shards of the Past", description = "<The armor that once was here has mysteriously shattered. Pieces of the ancient armor are scattered around the room.>", objectives = "" }
WordHunterWoW_QuestEN[53842] = { title = "Earthen Blessing", description = "Ignis will help with smelting the metal, but the heat from the forge will cook you in yer boots!\n\nOur ancestors, the dwarves who forged Aegrim's armor, could sustain their stoneform for far longer than we can today. That's how they could forge the bulwark in the first place.\n\nLuckily, my friend Bouldercrag can help us with that. He'll need some materials for the ritual.", objectives = "" }
WordHunterWoW_QuestEN[53844] = { title = "Recruiting the Furnace Master", description = "Grumnus says we're going to need some help smelting this metal. I just happen to know someone who's perfect for the job.\n\nWe're heading to Ulduar!\n\nYears ago, we fought against a construct named Ignis the Furnace Master. I've heard tell that the titan keepers brought him back, and Ulduar's furnace is alive once more.", objectives = "" }
WordHunterWoW_QuestEN[53845] = { title = "Forging the Armor", description = "It's time to begin. Bouldercrag, Ignis, and I are here to assist you.\n\nYou'll be the first dwarf to forge the Bulwark of the Mountain King in generations. This ol' blacksmith is honored to be able to witness this.\n\nAre ye ready?", objectives = "" }
WordHunterWoW_QuestEN[53846] = { title = "Legacy of the Bronzebeard", description = "You must present this armor to Muradin at once! This is an historic day for the dwarven people.\n\nThis isn't just a suit of armor, it's a symbol of our heritage.", objectives = "" }
WordHunterWoW_QuestEN[53847] = { title = "On Whispered Winds", description = "{name},\n\nI have need of you.\n\nMaiev and Shandris are en route to Stormwind to petition King Wrynn for aid in retaking Darkshore.\n\nYou have proven a loyal ally to my people in times past. I ask that you join their audience with the king and lend your voice to our cause.\n\nI suspect we shall meet again soon.\n\n-Tyrande", objectives = "" }
WordHunterWoW_QuestEN[53848] = { title = "Tooling Around Vol'dun", description = "Okay, {name}. We got almost everything we need. Almost.\n\nYou see, I lost my toolbox. I must have dropped it while running from the sethrak a couple days ago. Can ya fetch it for me? I'm not a very good engineer without my tools!\n\nAnd take a mech with ya. I've spied some mysterious dwarven and troll figures lurking around...  better not be the Venture Co. One whiff of the schematic being here and we got trouble.\n\nYou'll need the mind enhancer for it to follow you. Just put it on and you'll be good to go!", objectives = "" }
WordHunterWoW_QuestEN[53849] = { title = "Waning Hope", description = "The kaldorei have been steadfast members of the Alliance since the end of the Third War. We have fought on distant shores and even on different worlds without protest.\n\nIt is curious that in our moment of need, their resources are stretched too thin to lend so much as a single blade.\n\nWrynn has already denied Tyrande aid. Witness it for yourself.", objectives = "" }
WordHunterWoW_QuestEN[53850] = { title = "Our War Continues", description = "The work to stop the Alliance is far from over, {name}. But thanks to you, we have the methods necessary to break them.\n\nThe Abyssal Scepter has been delivered to King Rastakhan, earning us more of his favor.\n\nThere is a matter of greater importance that I would speak to you about... but not here.\n\nMeet me aboard the Banshee's Wail within Zuldazar.", objectives = "" }
WordHunterWoW_QuestEN[53851] = { title = "Our War Continues", description = "The work to stop the Alliance is far from over, {name}. \n\nKing Rastakhan now possesses the Abyssal Scepter that you recovered from the Kul Tirans. He has placed it... in his treasury. \n\nThe Dark Lady wishes to speak with you regarding the corpse you found at the bottom of the ocean. Derek Proudmoore.", objectives = "" }
WordHunterWoW_QuestEN[53852] = { title = "Azerite Denied", description = "The Kul Tirans and Alliance are amassing a vast amount of their Azerite and Azerite weapons within Tiragarde Sound.\n\nThey have a new supply of the resource, thanks to the Kul Tirans' conquest over Lady Ashvane and her company.\n\nWe must strike at their supplies of Azerite and destroy these weapons, or else we will be behind in this war.\n\nYou and Zelling will travel to Tiragarde Sound and meet with Rexxar. Lead the assault on their Azerite supply.\n\nAnd do not return until you are victorious.", objectives = "" }
WordHunterWoW_QuestEN[53853] = { title = "The Setting Sun", description = "Remember the Sunwell.\n\nWe ride into battle with those words for a reason. We lost so much that day...\n\nI lost so much that day.\n\nShine the lantern on the southern side of the island, where the Dead Scar meets the sea. There you will see how the fall of the Sunwell began. And with it, the last act of the High Elves.", objectives = "" }
WordHunterWoW_QuestEN[53856] = { title = "The Fury of the Horde", description = "The Norwington Estate has a large cache of Azerite, along with the Alliance's latest Azerite weapons.\n\nWe need to steal these weapons and all of their Azerite. Every weapon stolen is a Horde life saved.\n\nWhen you are ready to strike, let me know. I shall signal our warriors to begin the assault.\n\nThe Alliance and Kul Tirans will see the true might of the Horde!", objectives = "" }
WordHunterWoW_QuestEN[53858] = { title = "Step Into Her Shoes", description = "Another one of those rifts. Normally I'd repair it, but given the circumstances I wish to see where it leads.\n\nIt isn't often I commune with versions of myself from other threads of time. But one particular self has been a dear friend for some time.\n\nI feel myself growing weaker. If she perishes...\n\nWe don't have much time. We need to enter this rift now.", objectives = "" }
WordHunterWoW_QuestEN[53859] = { title = "The Mountain Folk", description = "All Kul Tirans are really tough, but the Roughnecks are the roughest and toughest of them all!\n\nThey can wrestle gryphons with their bare hands! They can knock down a yeti with a single punch!\n\nI wanna meet a Roughneck and prove that I can be really strong like them! Can you take me to their camp? I've heard it's up in the mountains by Anglepoint.", objectives = "" }
WordHunterWoW_QuestEN[53861] = { title = "Yo Ho, Yo Ho!", description = "The orphan matron is always telling us what to do! Study your books, practice your words, behave in public...\n\nWhat if I want to be a pirate when I grow up? A scourge of the high seas! Finding buried treasure, dueling my enemies on the mast, wearing cool hats!\n\nPirates never come into Boralus, so I've only ever heard stories. I wanna meet a real one! Can you take me to Freehold? I'll practice my pirate voice on the way.\n\nYARRRRR!", objectives = "" }
WordHunterWoW_QuestEN[53862] = { title = "The Squid Shrine", description = "Sometimes tidesages come to the orphanage and tell us about the sea and how they can talk to it.\n\nI wanna talk to water!\n\nWe've gone on field trips to their monastery here in Boralus, but I heard their home in Stormsong is much more impressive. Can you take me to go see it? I heard there's a great view from the Brineworks!", objectives = "" }
WordHunterWoW_QuestEN[53863] = { title = "Bird Friends", description = "My best friend at the orphanage is named Billy. He's just a kid like me, though. I heard that some people in Drustvar have FALCONS as their best friend.\n\nHow cool is that?!\n\nCan we go meet a falconer? Pretty please? I want to have a bird friend too.\n\nI hear there's a big statue in Arom's Stand of some dead guy who was friends with birds. Maybe we can find a falconer there!", objectives = "" }
WordHunterWoW_QuestEN[53864] = { title = "Shapeshifters!", description = "Being a human is alright and all, but what if I could be a BEAR?\n\nDruids can be bears. And cats! And who knows what else!\n\nI've heard rumors of druids in the mountains of Drustvar. It would be so cool to meet one. I wanna see them turn into animals! Maybe they can teach me, too!", objectives = "" }
WordHunterWoW_QuestEN[53865] = { title = "Return to the Orphanage", description = "This has been the best Children's Week ever!\n\nI was scared to grow up, but now I'm really excited! There are so many cool things I can be!\n\nBut how can I choose?\n\nI think it's time for you to take me back to the orphanage, {name}. I'll think about what I want to be when I grow up on the way.", objectives = "" }
WordHunterWoW_QuestEN[53866] = { title = "If The Shoe Fits...", description = "That thing is killing her...it's killing *me*!\n\nWe need to stop it!\n\nPlease, I need your help to save my self!", objectives = "" }
WordHunterWoW_QuestEN[53868] = { title = "Saving Nine", description = "I saw her in there, destroying another part of my timeline.\n\nWith every thread she severs, I lose myself more and more...\n\nPerhaps I will perish, but I won't let her ruin the fabric of time.\n\nI need you to join me one last time. \n\nI can only end this with your support.", objectives = "" }
WordHunterWoW_QuestEN[53869] = { title = "Killing Time", description = "Now, {name}, stand with me.\n\nI am weak. So many threads have been severed.\n\nI'll use what power I have left to mend the rift.\n\nPlease...make sure the fabric of time is safe from her.", objectives = "" }
WordHunterWoW_QuestEN[53870] = { title = "Guests at Grommash Hold", description = "{name}, I've received word that a vulpera caravan has arrived at Grommash Hold. They wish to address the Horde and have requested your presence.\n\nI'm afraid it is not the best time for guests, so please see them as soon as you are able.", objectives = "" }
WordHunterWoW_QuestEN[53879] = { title = "Cleaning Out the Estate", description = "We must keep moving forward. Our goal is to weaken the Alliance, destroy their weapons, and steal their Azerite.\n\nThe three of us will carve a path of destruction through our enemies. Let us go!", objectives = "" }
WordHunterWoW_QuestEN[53880] = { title = "Machines of War and Azerite", description = "The Norwington Estate... I remember taking walks here with my wife and children.\n\nSorry, this isn't the time for remembering an old life.\n\nThe Alliance have Azerite bombs and rifles scattered throughout the estate. I believe our goal is to recover them.\n\nIf only the Alliance hadn't chosen to use the estate as a testing ground... this was meant to be a place of peace.", objectives = "" }
WordHunterWoW_QuestEN[53881] = { title = "Cut from the Same Cloth", description = "My Infinite self was right. I can no longer mend time.\n\nToo many of my threads have been purged. I can feel no others.\n\nI'm alone now. And my thread is gone. But not you.\n\nTake this recipe. You've proven yourself a talented tailor in your own time, and a savior in so many more.\n\nThe fabric of time needs your hands to mend it. I trust you with that responsibility.\n\nTalk to me when you're ready. I'll take you back to when this all began.", objectives = "" }
WordHunterWoW_QuestEN[53882] = { title = "Writing on the Wall", description = "Long has the southern wall separated Quel'Thalas from the once great kingdom of Lordaeron. We did not believe that anyone could breach it. That overconfidence was our undoing. \n\nWhen the Scourge arrived, the gate was not conquered by force. It was willingly opened by a traitor.\n\nThough caught unaware, every Farstrider, soldier, and magister in the area rushed to the defense of our homeland. Very few of them returned home. The gates now stand as a memorial in their name.", objectives = "" }
WordHunterWoW_QuestEN[53883] = { title = "Shores of Zuldazar", description = "Alliance forces are attacking Zuldazar. Make them regret every step taken on our soil!", objectives = "" }
WordHunterWoW_QuestEN[53885] = { title = "Isolated Victory", description = "Alliance forces are pushing deeper into Vol'dun. We can not allow this aggression to go unchecked!", objectives = "" }
WordHunterWoW_QuestEN[53887] = { title = "War Marches On", description = "I hope the Horde will think twice about attacking Kul Tiras in the future, but given the actions of its leadership, it is a faint hope at best. Still, what matters most is my people are safe now.\n\nThe fleet and marines should be here soon to help the Outriggers clear out what remains of the Horde forces. Please return to High Commander Wyrmbane and let him know I will join everyone as soon as I am able.\n\nThank you for your swift actions today, {name}.", objectives = "" }
WordHunterWoW_QuestEN[53888] = { title = "To Anglepoint", description = "An attack on Anglepoint Wharf can only mean one thing: the Horde seeks to destroy the seagate there. \n\nThis is my home. These are my people. I cannot turn my attention to our operations in Zandalar until we've routed the Horde.\n\nThe military will take a little time to mobilize, but in the meantime you and I can face these monsters. If we can't stop them, we can slow them down.\n\nWar has come to my shores once more. I will not stand aside.", objectives = "" }
WordHunterWoW_QuestEN[53889] = { title = "A Declaration of Intent", description = "Our caravan is ready to explore the world beyond the sands, but Nisha's blade can't be our only defense against the dangers we know await us. \n\nThis is why we've come. \n\nTo declare our intent to join the Horde.", objectives = "" }
WordHunterWoW_QuestEN[53890] = { title = "New Allies, New Problems", description = "Baine certainly has his hands full. Taking on new allies means taking on new problems. \n\nLet us find out what troubles those within the Horde and see what we can do to help. \n\nPerhaps when Baine isn't so overwhelmed, he'll be able see our true value.", objectives = "" }
WordHunterWoW_QuestEN[53891] = { title = "No Problem Too Small", description = "These problems might seem small, but they will eat away at the Horde over time if they remain unaddressed. \n\nWe must offer our help. \n\nThe vulpera are skilled at solving problems, no matter their size.\n\nI will investigate the outpost. Nisha and Meerah will see to the others.\n\nMeet me in the Twilight Highlands when you're ready.", objectives = "" }
WordHunterWoW_QuestEN[53892] = { title = "Where Are the Workers?", description = "Look at this axe, {name}. There's still sweat on the hilt. The workers were here not too long ago. \n\nLet's see if Sasha can track their scent.", objectives = "" }
WordHunterWoW_QuestEN[53893] = { title = "A Little Goodwill", description = "It sounds like the peons are feeling undervalued. They do important work for the Horde, but their diligence is often overlooked. A little goodwill would go a long way. \n\nLet's plan a feast in their honor. We'll need quite a bit of meat to sate their enormous appetites, luckily, I have a totem that can help with that.   \n\nYou acquire the ingredients, and I will make a meal guaranteed to boost morale.", objectives = "" }
WordHunterWoW_QuestEN[53894] = { title = "Worthwhile Repairs", description = "The peons are right. These tools are inexcusable. \n\nHow can they be expected to complete a job without the proper tools for their trade?\n\nI can make the needed repairs, but I'll need some ore first.", objectives = "" }
WordHunterWoW_QuestEN[53895] = { title = "Peon Promotions!", description = "I agree with the plight of the peons. They should be rewarded for the work they do.\n\nIt's unlikely that the Horde will agree to increase their wages, but there's no reason they can't be given a promotion. \n\nAny title other than peon would help build some confidence.", objectives = "" }
WordHunterWoW_QuestEN[53896] = { title = "Stand Fast", description = "The Horde will pay for what it has done, but first I have to attend to the people here. \n\n{name}, I need to hold a portal open so the injured can evacuate to Boralus.\n\nKeep the Horde's forces off me while the wounded get to safety. We can deal with them once the civilians are safe.", objectives = "" }
WordHunterWoW_QuestEN[53897] = { title = "A Party in Your Honor", description = "I think I have everything needed to make tonight a success. \n\nWe just need to make sure the peons show up.\n\nTell their leader that the Horde is throwing a party in their honor. \n\nI'm sure they won't decline a night of free food and drink.", objectives = "" }
WordHunterWoW_QuestEN[53898] = { title = "Strength and Honor", description = "Those peons certainly look happy, don't they? I have no doubt they'll return to work in the morning. \n\nHowever, if their leader goes unchallenged, there will always be risk of revolt. \n\nYou need to face him to battle. \n\nShow him the true strength of the Horde, but also the honor that comes with showing mercy.", objectives = "" }
WordHunterWoW_QuestEN[53899] = { title = "On the Outskirts", description = "If things are settled for the Commander, you should check in on Nisha. \n\nI'm sure she could use your help.", objectives = "" }
WordHunterWoW_QuestEN[53900] = { title = "We'll Use Their Weapons", description = "We're going to need special weapons to take down Tidecaller Nezara. Good thing it looks like the naga have plenty. \n\nWe'll use their weapons against them. You and I know a thing or two about that. \n\nGrab an assortment. We'll need more than one.", objectives = "" }
WordHunterWoW_QuestEN[53901] = { title = "Explosions Always Work", description = "The area surrounding Tidecaller Nezara is heavily guarded, so I'll need you to create a distraction. \n\nTake these explosives. Plant them on the naga's harpoon launchers. Once they've been detonated, the blast should be more than enough to send the guards running!", objectives = "" }
WordHunterWoW_QuestEN[53902] = { title = "Taking Out the Tidecaller", description = "Nezara's shield might be down, but that doesn't mean she's defenseless. \n\nThere's a brute by her side that may cause trouble. I'll take a stab at him so you can take down the Tidecaller.", objectives = "" }
WordHunterWoW_QuestEN[53903] = { title = "Meet with Meerah", description = "It appears we're making good progress.\n\nWould you meet up with Meerah?\n\nI want to be sure she's found her way to the vintner in Suramar.", objectives = "" }
WordHunterWoW_QuestEN[53904] = { title = "The Vintner's Assistants", description = "Vintner Iltheux oversees all arcwine production for the Horde. \n\nHe's used to making wine himself, but the Horde sent in help to speed up the process. \n\nIt's had the opposite effect. \n\nWe need to get to the bottom of this. \n\nHow about you tour the vineyards and see how things are running? I have a few more questions for the vintner.", objectives = "" }
WordHunterWoW_QuestEN[53905] = { title = "Playing to Their Strengths", description = "Iltheux isn't properly utilizing the help he's been given.\n\nLet's fix that.\n\nAssign new roles to the workers, ones more suited to their strengths.\n\nIf you need suggestions, I'm happy to help.", objectives = "" }
WordHunterWoW_QuestEN[53906] = { title = "Fermented for the Horde", description = "Vintner Iltheux's recipe doesn't need much improvement. \n\nSome unique ingredients and slight modifications to the winemaking process is all that's needed. \n\nI'm thinking adding fermented firebloom should do the trick. Then, filter it though a special cloth made from silkwing fibers. \n\nThere are plenty of silkwings roaming the vineyard, and I have no doubt that Boss Mida can acquire the flowers, for a price.", objectives = "" }
WordHunterWoW_QuestEN[53907] = { title = "Sip and Savor", description = "I think we're making wine, {name}!\n\nLet's see if the vintner approves of our vintage. \n\nTake a sample to Iltheux and see what he thinks.", objectives = "" }
WordHunterWoW_QuestEN[53908] = { title = "Awaiting Our Arrival", description = "Let's head back to Orgrimmar.\n\nI'm sure Kiro's expecting us. \n\nWe really shouldn't make him wait.", objectives = "" }
WordHunterWoW_QuestEN[53909] = { title = "Besieged Allies", description = "Seawalls can be rebuilt, but lives are lost for good. We need to secure the rest of the people here first.\n\nThe Outriggers have been known as some of the fiercest hunters in these waters. Find their leader, Rosaline Madison, and enlist her aid in liberating Anglepoint. Together, clear the north shore of the Horde, save anyone in danger, and rally the dock workers.\n\nYou handle the north shore, {name}. I will handle the south. We'll meet in the middle and crush the Horde between us.", objectives = "" }
WordHunterWoW_QuestEN[53910] = { title = "Repel the Horde!", description = "The Horde has overrun Anglepoint, killing my people and destroying their livelihoods. Its raiders have come to Kul Tiras with killing on their minds. I cannot allow that to happen.\n\nSlay any Horde Axe Throwers or Berserkers you see on the north shore. I will do the same on the south. Together we will stop this invasion.", objectives = "" }
WordHunterWoW_QuestEN[53912] = { title = "The Hunt Never Ends", description = "We have our victory, but we must move quickly to take the remaining Azerite from the estate.\n\nOur forces should already be moving the Azerite from the manor into our gyrocopter support.\n\nLet us move and ensure we get every ounce of Azerite away from the Alliance.", objectives = "" }
WordHunterWoW_QuestEN[53913] = { title = "With Honor", description = "The Alliance and Kul Tiran forces are in disarray. I can hear the Azerite tank powering up.\n\nLieutenant Cole intends to fight us... now that his forces are destroyed.\n\nLet me know when you are ready to fight. The three of us shall destroy this tank while our warriors watch on!", objectives = "" }
WordHunterWoW_QuestEN[53914] = { title = "Murder at the Brawl'gar Arena", description = "The Brawl'gar quartermaster lies dead in front of you. He was murdered in broad daylight!\n\nHe must have been assassinated while someone was fighting in the arena. Maybe even during one of your fights.\n\nPerhaps there are some clues nearby as to who might have killed him.", objectives = "" }
WordHunterWoW_QuestEN[53915] = { title = "Put Up Your Dukes", description = "You know what?\n\n<The commander puts his notebook away.>\n\nI COULD use a good {class} on my investigations team. We've had some personnel issues lately and, frankly, I can use all the help I can get.\n\nBut first: why don't you go hop into the arena for a few fights so I can get a good look at your skills?", objectives = "" }
WordHunterWoW_QuestEN[53916] = { title = "Outrigger Outfitters", description = "My people met the Horde head on when they arrived, but we've been scattered over the wharf. The Horde has been relentless. We haven't been able to form a solid resistance force using just our fists as weapons.\n\nBut now the Lord Admiral is here with the champion of the Alliance. That's just the spark we need to rise up and kick these sorry mongrels out of our lands. If you can get my men some weapons, they'll join the fight!\n\nFind those weapons and meet me back here. I'm working on a plan.", objectives = "" }
WordHunterWoW_QuestEN[53917] = { title = "Undercover Agent: Sharisanda", description = "Pit Boss Buxdoggle is one of our primary suspects in this case. Buxdoggle is an infamously aggressive speculator, and has a list of debts a mile long.\n\nHe may be in need of money, which is consistent with the evidence you found earlier.\n\nSharisanda has taken point on the case. I'd like you to assist her. I think you'll work well together.", objectives = "" }
WordHunterWoW_QuestEN[53918] = { title = "The Financial Participation Incentive", description = "I see Buxdoggle running some sort of game over dere. Getting people to guess de fight's winner in exchange for Brawler's Gold.\n\nSee if you can figure out how his game works. If you win enough money from him, he might start talking...", objectives = "" }
WordHunterWoW_QuestEN[53919] = { title = "Shots Fired", description = "Horde invaders keep sailing in through the seagate, but we have a nasty surprise for them!\n\nThe Outriggers are good at fighting monsters of any sort, the Horde included. We'll keep them off you while you take out their boats.\n\nSend 'em to the bottom of the harbor!\n\nFor Kul Tiras! For the Lord Admiral!", objectives = "" }
WordHunterWoW_QuestEN[53920] = { title = "A Favor for Your Ol' Pal Buxdoggle", description = "Hey, listen, I was thinkin' about somethin'...\n\nYou know how you won all that money from me? Well, funny story, that may have been slightly more money than I actually have, and now some very powerful people want to break my elbows and my knees.\n\nI can't pay 'em! I'm broke! Heh heh!\n\nAll I need to get out of this hole is for you to lose your next fight. Flop like a fish. Please.", objectives = "" }
WordHunterWoW_QuestEN[53921] = { title = "The Pit Boss's Debts", description = "I'm not too proud to commit a few acts of violence to set a wrong right. And you know what's wrong? I'm out of money!\n\nOnly one person's won more gold from me than you have, and his name's Lord Sylysthrel. Real skeezy guy. I think he was cheating.\n\nSure would be nice if I could get that gold back...", objectives = "" }
WordHunterWoW_QuestEN[53922] = { title = "Evidence Packet: Pit Boss Buxdoggle", description = "I heard everything. That goblin sure does talk loudly about his crimes and debts, doesn't he?\n\nIt sounds like we have enough to bring him in for questioning. I've put together a packet of evidence for Commander Ravenhide to review.\n\nGood job out dere.", objectives = "" }
WordHunterWoW_QuestEN[53923] = { title = "Undercover Agent: Stone Guard Mollivox", description = "I believe you've met one of my other agents: Stone Guard Mollivox. She's investigating our second suspect: Shadowmaster Skrizzik.\n\nYou'll find Mollivox near the arena's entrance.", objectives = "" }
WordHunterWoW_QuestEN[53924] = { title = "Soul Splinters", description = "<Skrizzik mumbles to himself.>\n\nOh dear, oh dear... it's getting hungry again. Where am I going to find enough souls to feed it? Ohh... if only I could get my hands on some of those brawler's purses...\n\n<He notices you.>\n\nOh! Hello there! Pay no attention to the mindless babbling of an innocent warlock. Nothing suspicious going on here!", objectives = "" }
WordHunterWoW_QuestEN[53925] = { title = "Super Soul Splinters", description = "<Skrizzik mutters to himself again:>\n\nWill these be big enough, though? It gets SO hungry for souls, and when it doesn't get enough, it gets angry, and we definitely don't want to trigger a void apocalypse in the middle of Orgrimmar. Oh dear, oh dear...\n\n<He notices you lingering.>\n\nOh! The {race} is still here! Heh heh. Never mind me! Nothing evil going on here!!", objectives = "" }
WordHunterWoW_QuestEN[53926] = { title = "Cause for Concern", description = "Shadowmaster Skrizzik's behavior was unusual.\n\nHis repeated mutterings about \"shadow magic\" and \"void apocalypses\" and \"ancient creatures hungering for the souls of the living\" certainly warrant further investigation.\n\nYou should report back to Stone Guard Mollivox.", objectives = "" }
WordHunterWoW_QuestEN[53927] = { title = "The Precious 13-Tooth Gogglegear", description = "We're going to have to invent something. Something capable of seeing into alternate dimensions. Something explosive that you strap directly onto your eyes.\n\nThat's right, I'm talking about goggles.\n\nI already have all the goggle parts except for one: a 13-tooth gear. They're nearly impossible to find, but I KNOW that the G.G. Engineering boys have one, and Card Trader Ami has their challenge card.", objectives = "" }
WordHunterWoW_QuestEN[53928] = { title = "The Mollivox Goggle Experiment", description = "Okay, before we start, I've got a few rules:\n\nFirst, these goggles will only work at close range. We're looking for something INSIDE the arena, so you'll have to be inside the arena to use them.\n\nSecond rule: if you feel something starting to explode, try to blink real hard.\n\nLastly, remember, we're looking for an evil shadow monster. You don't need to kill it, we just need you to see it so we can report it as evidence.\n\nAlright, go get in that arena and try them out!", objectives = "" }
WordHunterWoW_QuestEN[53929] = { title = "Evidence Packet: Shadowmaster Skrizzik", description = "Sounds like we've found our perp, {name}. This guy's sketchy, desperate, and his shadow magic is consistent with that shadowy scroll you found earlier.\n\nBring this packet to Arlu, and we can bring him in. Good work out there!", objectives = "" }
WordHunterWoW_QuestEN[53930] = { title = "Undercover Agent: Nugg Lumbo", description = "I've got one more suspect I'm investigating: Libbiara Blightrunner. She's a wealthy blood elf death knight socialite who spends most of her time spectating the arena from the zeppelin up above.\n\nI've got my best agent on the case: Nugg Lumbo. Check in with him to see how his report is coming along.", objectives = "" }
WordHunterWoW_QuestEN[53931] = { title = "Flaunt It If You Got It", description = "Sigh... so dull...\n\nOh, it's you! {name}, was it? I've seen a few of your fights. They're slightly less tedious than the standard humdrum bloodsport this arena has been producing lately.\n\nLet's spice things up a bit. Maybe buy some expensive drinks for ourselves? Buy a round of the cheap stuff for the riffraff below? Maybe even toss a few amberseed buns off the boat?", objectives = "" }
WordHunterWoW_QuestEN[53932] = { title = "Evidence Packet: Libbiara Blightrunner", description = "Nugg got what Nugg need. Give stupid blood elf one drink and she start getting all self-incriminatey.\n\nYou bring packet to Commander. Nugg gonna buy some expensive snacks.", objectives = "" }
WordHunterWoW_QuestEN[53933] = { title = "The Brawl'gar Trial", description = "I've issued three warrants. Nugg, Mollivox, and Sharisanda are apprehending the suspects as we speak.\n\nIt's time to go to court.\n\nYou may be called on to testify. Just answer as honestly as you can, and let the wheels of justice do the rest.", objectives = "" }
WordHunterWoW_QuestEN[53934] = { title = "A Clue from Area 52", description = "We've received a letter from Area 52, the goblin outpost in Netherstorm. The author claims to know details about what they call \"the situation in Brawl'gar\".\n\nThey don't say more than that.\n\nI'm tied to my paperwork here. Go check out this lead and see if anything turns up.", objectives = "" }
WordHunterWoW_QuestEN[53935] = { title = "Solving the Mystery", description = "<Bazzelflange produces a challenge card from her pocket.>\n\nI grabbed this challenge card from my attackers while we were fighting each other! I'm sure that you can use it to challenge my attacker to some sort of ultimate showdown!", objectives = "" }
WordHunterWoW_QuestEN[53936] = { title = "Stopping the Sappers", description = "The ice should keep the Horde out while we handle the sapper teams gathered on the beach.\n\nI'm going to keep those Horde galleons busy. I need you to handle whoever is in charge and bring all the Azerite bombs you find back to me.\n\nThen we'll handle disposing of their weapons.", objectives = "" }
WordHunterWoW_QuestEN[53937] = { title = "The Ub3r-Spanner", description = "It's a shame that Gryzix had to die. Those Venture Co. make all of us enterprising types look bad!\n\nAt least we can still decode the Ub3r-Spanner schematic. Here, hand me that schematic and his decoder and I'll get this whipped up in just a second.", objectives = "" }
WordHunterWoW_QuestEN[53938] = { title = "A Friend in Needle", description = "You can see me?\n\nOh, thank goodness! I thought I was lost in the folds of time...again!\n\nBut for one to see through the folds of time's fabric... you must be a very talented tailor, indeed.\n\nWould you bring me some cloth, then, tailor? I believe I'll be able to place just when I am with your help and right myself.", objectives = "" }
WordHunterWoW_QuestEN[53939] = { title = "Breaching Boralus", description = "Finally! There's no place on Kul Tiras with a stronger Alliance presence. We must be bold and unrelenting if we're going to drive them out here.\n\nLok-tar ogar!", objectives = "" }
WordHunterWoW_QuestEN[53940] = { title = "A Stitch in Time", description = "Hm...I don't know that I've ever been to this time, before.\n\nI suppose I should explain myself. My name is Delormi, and I'm the last remaining member of the Synchronous Tailors.\n\nWe make sure the fabric of time stays, well, mended. But I've found a number of new tears cropping up.\n\nIn fact, I believe that's why I've arrived here in this time. Perhaps you could assist me in tracking them down and repairing them?", objectives = "" }
WordHunterWoW_QuestEN[53941] = { title = "A Mech for a Goblin", description = "Gallywix has a plan to deal with the Alliance and has requested your help. It involves the Azerite you reclaimed.\n\nSpeak with him down at Bilgewater Bonanza, and do whatever you can to help him... when it comes to the interest of the Horde.\n\nOh, and make sure Gallywix stays alive. The Alliance already tried to kill him.", objectives = "" }
WordHunterWoW_QuestEN[53942] = { title = "The Right Mech for the Job", description = "Okay, {name}, we're good to go. The G.M.O.D has plenty of Azerite to cause some trouble!\n\nWe gotta head to my, er, OUR base in Drustvar. Mekkatorque, that freakin' king of the gnomes, is attacking our Azerite supply!\n\nAfter we take care of the base, we're gonna take care of him! You get what I'm sayin'?", objectives = "" }
WordHunterWoW_QuestEN[53943] = { title = "Modular Construction", description = "The Abandoned Junkheap is home to some seriously deadly gnomish constructs. These constructs contain Mecha-Cores which could come in handy for crafting the Ub3r-Spanner. Legend has it that it could forge creations unlike anything we've ever seen!\n\nYou look like the adventurous type, {name}. Can you go scrap up some mechs?\n\nDon't forget your Arclight Spanner!", objectives = "" }
WordHunterWoW_QuestEN[53947] = { title = "In the Dunes", description = "This schematic you found is encrypted. My tools are no good on it, not without risking the integrity of the data.\n\nHowever, I do know a guy who can definitely crack this cookie: Mr. Dataguru Gryzix.\n\nIf I remember correctly, he's been vacationing on a beach in Vol'dun since the war broke out. Something about not getting the recognition he deserves. \n\nAnyways, I am sure you can convince him to help you.", objectives = "" }
WordHunterWoW_QuestEN[53948] = { title = "Vengeful Venture", description = "<You pick up the note and deduce that the Venture Co. are the killers of Dataguru Gryzix. You search his corpse, and find that his decoder and the Ub3r-Spanner schematic have been stolen.\n\nYou need to retrieve his decoder and the schematic and bring them back to Layla Evenkeel to have any hope of crafting the Ub3r-Spanner.\n\nThat mech you have following you should prove itself useful.>", objectives = "" }
WordHunterWoW_QuestEN[53949] = { title = "The Ub3r-Spanner", description = "It's a shame that Gryzix had to die. Those Venture Co. make all of us enterprising types look bad!\n\nAt least we can still decode the Ub3r-Spanner schematic. Here, hand me that recipe and his decoder and I'll get this whipped up in just a second.", objectives = "" }
WordHunterWoW_QuestEN[53952] = { title = "Simply Dying of Boredom", description = "Up until now, I've been dying of boredom up here. I think maybe we need some new blood here in the arena. Boss Bazzelflange can be so stingy with her invitations, can't she?\n\nI've had one of my servants write up a few slightly-counterfeit invitations to hand out. Maybe you could help me get them distributed? There's always plenty of tough-looking characters hanging out in front of the auction house near Grommash Hold...", objectives = "" }
WordHunterWoW_QuestEN[53953] = { title = "Brawl'gar Awaits!", description = "Tired of standing around in the boring old Valley of Strength? Come on over to the Brawl'gar Arena, and fight for the amusement of others!\n\nYou might win, or you might get killed, but either way, you're going to have a great time.\n\nGrab an invitation and bring it to Skuglor, near the front door. Brawl'gar awaits!", objectives = "" }
WordHunterWoW_QuestEN[53955] = { title = "Warfront: The Battle for Darkshore", description = "Darkshore belongs to the Horde! We must hold that ground to maintain our dominance over Kalimdor.\n\nPrepare yourselves. Battle awaits!", objectives = "" }
WordHunterWoW_QuestEN[53957] = { title = "Darkshore Recruits", description = "We've got a few recruits that can help us take back Darkshore!\n\nBut first, we need our Ancient of War to be back up to good health. To help him, contribute resources to him and he'll perk right up!\n\nOnce the Ancient of War is restored, talk to Jarod Shadowsong and recruit a troop. I'm sure they could learn a lot from fighting alongside you.", objectives = "" }
WordHunterWoW_QuestEN[53959] = { title = "Armor for Armies", description = "We need to make sure our soldiers have the best equipment possible in the battle against the Horde. \n\nOnce the Hunter's Hall is constructed, speak with Cordressa Briarbow about how to improve the weapons and armor of our troops.", objectives = "" }
WordHunterWoW_QuestEN[53960] = { title = "The Altar of Elders", description = "Now that contributions are in full swing, the Altar of Elders has been rebuilt.\n\nGo, speak with Moon Priestess Lasara to see what the Altar has to offer.", objectives = "" }
WordHunterWoW_QuestEN[53961] = { title = "Glaiveworks For Me", description = "We've all been on edge since Teldrassil, but Erion took it hard. He jumped at the chance to help out.\n\nWhy don't you talk to him and see what he's got going at the Glaiveworks?", objectives = "" }
WordHunterWoW_QuestEN[53962] = { title = "Cut from the Same Cloth", description = "My Infinite self was right--I can no longer mend time.\n\nToo many of my threads have been purged. I can feel no others.\n\nI'm alone now. And my thread is gone. But not you.\n\nTake this recipe. You've proven yourself a talented tailor in your own time, and a savior in so many more.\n\nThe fabric of time needs your hands to mend it. I trust you with that responsibility.\n\nTalk to me when you're ready. I'll take you back to when this all began.", objectives = "" }
WordHunterWoW_QuestEN[53965] = { title = "Children's Week", description = "Thank you for offering your help with Children's Week, {name}. We have a little girl who is excited to explore Zandalar!\n\nTake dis whistle. With it, you will be able to call de child you have agreed to take care of dis week. It will serve no use after Children's Week ends.\n\nWhen you are ready, use de whistle and meet your new ward! She is a feisty one.", objectives = "" }
WordHunterWoW_QuestEN[53966] = { title = "Loa of Winds", description = "I heard dat Pa'ku lives somewhere in Zuldazar. Her priests tell stories about her when dey come to de Hall of Castes.\n\nShe's a pretty popular loa. I mean, she's in charge of de sky AND de sea! Dat's a lot of blue, and blue is my favorite color!\n\nMaybe I could be one of her followers?", objectives = "" }
WordHunterWoW_QuestEN[53967] = { title = "The Frogmarsh", description = "De caretakers are always telling us stories in de Hall of Castes. Sometimes dey warn us about danger, sometimes dey're about de loa... dere's usually a point to dem.\n\nOne time, dey told us about Krag'wa, and how blood trolls killed his followers, and how he hasn't been seen since.\n\nBut I heard dat he's back! He's in Nazmir again, and he's plotting his revenge against de blood trolls.\n\nCan we go see him?", objectives = "" }
WordHunterWoW_QuestEN[53968] = { title = "The Shifting Pack", description = "Dere's one loa I'm extra interested in seeing: Gonk! I've heard de priests say dat he's de most welcoming of de loa. He even lets his followers worship other loa as well!\n\nBut de best thing about him is dat he and his followers can change into many forms. I want to do dat!\n\nWill you take me to meet him?", objectives = "" }
WordHunterWoW_QuestEN[53969] = { title = "Hunting for Gold", description = "I know dis trip is supposed to focus on de loa...\n\nBut I want to see de island of gold!\n\nI heard stories of undead pirates and an island covered in gold coins and treasure! Can we go see it?! \n\nPleeeease?", objectives = "" }
WordHunterWoW_QuestEN[53970] = { title = "The Sethrak Queen", description = "De caretakers are always talking about how de sethrak attack caravans... but dey say dat de sethrak and de Zandalari used to be friends!\n\nI heard dat dere are some sethrak who still want to be friends, and dat dey have a loa who wants peace more dan anything!\n\nCan you take me to meet de sethrak and deir loa? I want to meet dem for myself!", objectives = "" }
WordHunterWoW_QuestEN[53971] = { title = "Return to the Hall of Castes", description = "I can't believe I got to visit so many places. I've never even left Zuldazar before!\n\nI may be casteless, but now dat I've met so many loa, maybe I can follow one and have a future off of de streets.\n\nBut for now, we should go back to de Hall of Castes. De caretakers must be waiting for me.", objectives = "" }
WordHunterWoW_QuestEN[53973] = { title = "Ride Out to Meet Them", description = "We must defend our warriors from the Alliance army while we recover this Azerite.\n\nTake the Azerite weapons you stole and load them onto one of these gyrocopters.\n\nMisha and I will ride out and fight the reinforcements from the ground, while you provide air support.\n\nWe need to hold them off until our warriors can retreat with the Azerite.", objectives = "" }
WordHunterWoW_QuestEN[53974] = { title = "Druids of Gloomtide", description = "The latent power at Gloomtide Strand presents us with an opportunity to harness great power. One of our allies, Edgard, has great knowledge into what this might mean for our efforts.\n\nSeek him out and discover the power of nature.", objectives = "" }
WordHunterWoW_QuestEN[53975] = { title = "Flying at Night", description = "Now that we control Ashwood Depot, it will be much more convenient to travel about the battlefield.\n\nI've drafted plans for a flight network. It's a rather brilliant plan, if I do say so myself. You don't seem busy. Take my notes and deliver them to our commander at once.\n\nSpeak to Fidelio and he will provide you with a hippogryph.", objectives = "" }
WordHunterWoW_QuestEN[53976] = { title = "Iron in Hand", description = "This won't work at all! We need to gather iron if we want to make any kind of headway against the Horde.\n\nGo down to the ruins at Lornesta and grab that iron. We need it!", objectives = "" }
WordHunterWoW_QuestEN[53977] = { title = "The War Chest", description = "Welcome to the warfront, {name}! We finally get to see some action. \n\nAny resources we've collected will go to the War Chest. Once enough has been gathered there, you can grab it!\n\nWhy don't you pay it a visit and see what you get?", objectives = "" }
WordHunterWoW_QuestEN[53978] = { title = "Gunpowder Plots", description = "Since the Lord Admiral iced all of their zeppelins, the Horde are rowing in through the seagate.\n\nThe nice, narrow seagate entrance that makes for a great choke point.\n\nI'll have my people haul over a cannon and some ammunition. If you collect some gunpowder, we'll set up behind the gate where they won't expect the attack.\n\nWe'll blast the Horde to the bottom of the harbor!", objectives = "" }
WordHunterWoW_QuestEN[53981] = { title = "The Day is Won", description = "The majority of our warriors survived and we have the Alliance's Azerite and weapons.\n\nBe proud of yourself, {name}. You fought with honor today.\n\nGo and inform Nathanos of our victory here. The Azerite should reach them shortly.", objectives = "" }
WordHunterWoW_QuestEN[53986] = { title = "The Calm Before", description = "A word, {name}.\n\nThere was a raid on the Norwington Estate, where we were testing some new designs of Azerite systems. Lady Jaina asked SI:7 to look into the matter. I have the report here.\n\nI know the Proudmoore family wants a moment together before they're pulled apart again, but the war is still ongoing.\n\nYou have been a friend to her family. Take the report to Jaina. I believe they went to pay respects at the family memorial.", objectives = "" }
WordHunterWoW_QuestEN[53987] = { title = "Wonders of Goblin Technology", description = "Our base has been attacked by all kinds of mechs. Tigers, gorillas, you name it, the Alliance is throwin' it at us.\n\nWe know now that someone is controllin' all of these things, but we don't know from where or how.\n\nWe need you and Gallywix to get out there and blow up those machines before they tear us apart!", objectives = "" }
WordHunterWoW_QuestEN[53988] = { title = "Shores of Fate", description = "So be it. You are more trustworthy an ally than any army Wrynn would have sent.\n\nWe will reclaim Darkshore together, but first we must find Tyrande. Without her at the front, our forces will crumble against the Horde.\n\nShe left for the Zoram Strand with a small force not long ago. If we move now, we may be able to find her before the Horde does.", objectives = "" }
WordHunterWoW_QuestEN[53989] = { title = "Hope", description = "No... it is not possible. She would not have died like this!\n\nSearch for signs of her departure along the strand. Personal effects. Weapons. Anything!\n\nTyrande is still out there, {name}. We must not lose hope.", objectives = "" }
WordHunterWoW_QuestEN[53990] = { title = "In Darkest Night", description = "{name}, I will not mince words. Tyrande foolishly risks her life with the ritual she intends to perform. If she falls, our entire war effort will fall with her.\n\nWe must set off for Darkshore and come to her aid. Only then can we march forward and reclaim our homeland.\n\nWe have lost Teldrassil. Fool or not, our people cannot afford to lose Tyrande as well.", objectives = "" }
WordHunterWoW_QuestEN[53992] = { title = "Warfront: The Battle for Darkshore", description = "We will not tolerate further Horde aggression in our territories.\n\nThe night elves will not stand alone this day. Darkshore will be theirs once more.\n\nFor the Alliance!", objectives = "" }
WordHunterWoW_QuestEN[53993] = { title = "A Voice on the Wind", description = "<A distant, mysterious voice fills your mind.>\n\nMy enchantments are not lost...\n\nFind me...\n\nDrustvar...\n\nFallhaven...", objectives = "" }
WordHunterWoW_QuestEN[53995] = { title = "The Tauren Tanner", description = "Hey, rich mon.\n\nOne of ya Tauren stopped by and asked who was de best leatherworker I knew who doesn't mind gettin' their hands dirty.\n\nI give 'im ya name, and he asked for an introduction. Said dat he would be in de Bazaar, by de docks.\n\nHe did not say what he needed ma best student for, but de way he was actin' makes me think it is somedin' big.\n\nHead on down to de docks and find dis Tauren. Show 'im what I taught ya.\n\nAnd focus! Needn't be havin' ya make me look bad!", objectives = "" }
WordHunterWoW_QuestEN[53996] = { title = "Pick Up Sticks", description = "In order for my enchantment to work, we'll need wood from these forests.\n\nWhen I was alive, I would wander these woods and tend to the trees. While those trees are long gone, perhaps their grandseeds have heard their stories and would be willing to help me.\n\nBut don't cut down any of the trees! Please! There are loggers that cut and hew without care for the wilds. Take their hard work so that they will think twice before felling another tree.\n\nBring me as much wood as you can muster.", objectives = "" }
WordHunterWoW_QuestEN[53997] = { title = "The Sixth Sense", description = "For my plan to work, we need to break the spell on my body that is anchoring my spirit to this place.\n\nHowever, my mortal remains are buried deep within this forest. There are wards within it that are designed to trap spirits who are still attached to the material world. Once my remains are cleansed, I will be able to move freely through the woods.\n\nUntil then, I'll need you to disenchant the wards we come across.\n\nSpeak to me when you are ready, and I will lead you to my grave.", objectives = "" }
WordHunterWoW_QuestEN[53998] = { title = "Exhumed", description = "As I've said, I'm unable to interact with the material world.\n\nI am able to dominate a creature to control its body, but I find it deplorable. In essence, it is enslaving the poor creature.\n\nWhat I want is a body of my own. If you build and animate a golem, it would be devoid of intelligence. A shell. One that I could inhabit without issue.\n\nDoing so will require that my soul is not anchored to anything else in this world, so I need you to remove the spell binding my spirit to my physical remains.", objectives = "" }
WordHunterWoW_QuestEN[53999] = { title = "The Threads That Bind", description = "Our destination is near Gol Koval, but there is something else you could pick up along the way.\n\nI don't want to ask because I hate them, but you cannot dispute the resilience of that horrible webbing that they manage to get everywhere.\n\n<Sef grimaces at the thought.>\n\nThere are spiders to the southeast. As a guardian of nature, I don't want to say kill them, but if you could... 'obtain' some fresh silk from their bodies, we could use it to bind the limbs of the golem together.", objectives = "" }
WordHunterWoW_QuestEN[54000] = { title = "The Beat Goes On", description = "We have most of the materials we need, but we require one final item. A heart.\n\nDon't worry. I don't mean one of flesh, but of stone; to bind the materials of the body into a single form.\n\nFind a smooth stone, and enchant it to hold a life force. It will require some reagents, but I would expect a powerful enchanter such as yourself to have some on hand or know where to find them.\n\nOnce that's done, it will need to be powered. The souls animating the elementals and undead here should do the trick.", objectives = "" }
WordHunterWoW_QuestEN[54001] = { title = "We're Going In", description = "This used to be a Drust shrine. There is a series of sigils that, once invoked, will allow us to teleport to my old sanctum.\n\n<Sef looks around somewhat confused and clears her throat.>\n\nIt has been centuries since I've been here, I'm having a bit of trouble remembering the order in which the sigils need to be activated to open the portal.\n\nI hope you're feeling adventurous. Oh, and be cautious. I enchanted the runes to keep would be intruders out by force.", objectives = "" }
WordHunterWoW_QuestEN[54002] = { title = "Putting It All Together", description = "Hmm... Everything seems untouched.\n\nWe can begin construction of my new body over here. Afterwards, I'll teach you how to make my enchanting rod.\n\n<Sef smiles at you, beaming with joy.>", objectives = "" }
WordHunterWoW_QuestEN[54004] = { title = "Test Case #1; Mech vs. Mekkatorque", description = "Alright, we got PLENTY of Azerite in this baby to blow up Mekkatorque and his airship.\n\nThat radioactive freak is gonna pay for sendin' his toys to attack one of MY, er, OUR bases!\n\nHop in, {name}. We got a gnome to blow up.", objectives = "" }
WordHunterWoW_QuestEN[54005] = { title = "What the Drust Knew", description = "Ahoy, {name}!\n\nIf you have a moment, I could use your assistance. I've recently received a large shipment of Drust relics that I've been processing.\n\nMost of them have been nothing out of the ordinary, but there is this one that is special. Just holding it makes my hair stand on end. \n\nWith you being my best pupil, I was thinking that it would be fun if we disenchanted it together, to see how it was made.\n\nWhat do you say?", objectives = "" }
WordHunterWoW_QuestEN[54006] = { title = "A New Hope", description = "Darkshore belongs to our people once more, in no small part due to your efforts. And, while I disagree with her methods, we would not have succeeded without Tyrande as well.\n\nDifferences aside, she is our leader--and an incarnation of the Night Warrior herself.\n\nShe is about to begin. You may stand here beside me.", objectives = "" }
WordHunterWoW_QuestEN[54007] = { title = "Insurance Policy", description = "Mekkatorque called us idiots, can you believe that? Well, if I'm an idiot, then why did I buy an insurance policy on my mech, huh?\n\nI bet that radioactive dimwit doesn't have an insurance policy on HIS mech!\n\nWe're gonna be outta here in no time. I just gotta give a quick call for roadside assistance to come out and fix this thing up.\n\nI need you to go hit the button for roadside assistance on my mech.\n\nJust, uh, don't hit the wrong one.", objectives = "" }
WordHunterWoW_QuestEN[54008] = { title = "Insurance Renewal", description = "You know, all I wanna do is blow up Mekkatorque and whatever airship he's ridin' in. Of course it ain't gonna be easy!\n\nI need you to go rescue my roadside assistance so they can fix this mech! They're probably in the Alliance camp near here.\n\nMeanwhile, I'm gonna cook us up a plan. We're gonna give Mekkatorque a real nice surprise!\n\nAnd by real nice surprise, I mean we're gonna blow him up. Oh, and also his airship.", objectives = "" }
WordHunterWoW_QuestEN[54009] = { title = "Killing on the Side", description = "Those annoying Alliance nearby are definitely takin' orders from Mekkatorque.\n\nThat means they gotta die! And any of their Kul Tiran friends, too. They gotta know the Horde is number one.\n\nAnd that you don't kidnap someone's roadside assistance!", objectives = "" }
WordHunterWoW_QuestEN[54012] = { title = "Fortunate Souls", description = "{name}, I am glad to see that you survived the wreck. Many were not as fortunate...\n\nI am capable of stalling the enemy here for now, but this position is not defensible long term.\n\nWe need to find somewhere safe for our forces.\n\nOnce we have taken measure of the wounded we will push on. In the meantime, find as many survivors as you can.\n\nNazjatar will claim no more Horde lives today!", objectives = "" }
WordHunterWoW_QuestEN[54015] = { title = "In Deep", description = "I can keep this barrier up here for a time after our departure, but we cannot remain here.\n\nThese soldiers will not be safe for long.\n\nWe must go deeper into this place to seek a more defensible position.", objectives = "" }
WordHunterWoW_QuestEN[54018] = { title = "Descent", description = "What has transpired! That is to say, what has transpired?! Yes, that is the appropriate response, is it not?\n\nI find our circumstances enthralling! Yet, tragic.\n\nI prattle on... Yes, Lor'themar asked me to send you to him at once. He is in need of your expertise, {name}.\n\nI'll lower you down the falls safely. Good luck!", objectives = "" }
WordHunterWoW_QuestEN[54021] = { title = "The First Arcanist", description = "Our situation is dire, {name}.\n\nThe Horde fleet was decimated by the attack on Dazar'alor. This naga trap has claimed much of what we had left.\n\nSurvivors report seeing the naga taking captives. Thalyssra has gone on ahead to see what she can do to help them. \n\nI will finish up here while you aid the First Arcanist's efforts. My rangers will provide what little aid they can.", objectives = "" }
WordHunterWoW_QuestEN[54022] = { title = "Mekkatorque's Battle Plans", description = "<You find part of plans that indicate where Mekkatorque will be in Tiragarde Sound, along with his airship.\n\nIf you could find the other half of these plans, you would be able to launch an ambush against the gnomish king.>", objectives = "" }
WordHunterWoW_QuestEN[54026] = { title = "Job's Done", description = "I'll stick around here a bit longer to ensure the peons get back to work. \n\nYou should return to Orgrimmar and let Commander Dresh know that he does not need to fret about the outpost any longer.", objectives = "" }
WordHunterWoW_QuestEN[54027] = { title = "Threat Contained", description = "That should keep those naga down!\n\nYou can have the honor of telling Bladeguard Sonji that the threat to Zuldazar's coast has been contained.", objectives = "" }
WordHunterWoW_QuestEN[54028] = { title = "Mech versus Airship", description = "We're all set to go, thanks to them battle plans ya found. Looks like Mekko ain't gonna be at his airship right now.\n\nHere's the plan. We're gonna go seriously mess up his ship, then Mekko is gonna swing by to try to save his friends.\n\nBut instead, he's gonna find you and me standin' on the deck of his burnin' ship, waitin' to take him out!\n\nGet in to the mech, {name}, we're blowin' up an airship and a gnome!", objectives = "" }
WordHunterWoW_QuestEN[54031] = { title = "Gaze of the Loa: Krag'wa", description = "Hello again, small one.\n\nI see Talanji has chosen a worthy witness. I must test Talanji's willingness to sacrifice for her people. I will weigh her commitment to defending the weak. Many great rulers have failed this challenge and still gone on to make powerful monarchs.\n\nBut the most beloved, those that find themselves surrounded by loyal followers, always understand the value of devotion to their people.\n\nYou will help me with this trial. Speak to me when you are ready to begin.", objectives = "" }
WordHunterWoW_QuestEN[54032] = { title = "Gaze of the Loa: Pa'ku", description = "Two more loa have declared their intent to test Talanji. The next is Pa'ku. She awaits you both at the top of these steps.\n\nI need not warn you about her tempestuous nature, nor her love for watching others fall from great heights.\n\nGood luck, {name}.", objectives = "" }
WordHunterWoW_QuestEN[54033] = { title = "Gaze of the Loa: Gonk", description = "The Lord of the Pack has requested to be the next to speak to Talanji. He is just up the steps on the next terrace.\n\nI do not think he will require quite as much of you as I did, but I believe his words will be relevant to your purposes here.\n\n<Krag'wa winks one massive eye.>\n\nDo not think we are not aware of your intentions, {name}.", objectives = "" }
WordHunterWoW_QuestEN[54034] = { title = "Gaze of the Loa: Bwonsamdi", description = "<Pa'ku's levity subsides.>\n\nOrdinarily the final trial would be given by Rezan. But the loa of kings is no more.\n\nIt seems ol' Rastakhan picked a new favorite to take his place.\n\n<Pa'ku sneers.>\n\nEnjoy that. Bwonsamdi waits for you in the temple.", objectives = "" }
WordHunterWoW_QuestEN[54036] = { title = "A Particular Process", description = "As you might have noticed, Vintner Iltheux is very particular about his wine making process, but his ancient recipe was crafted with only the Nightborne in mind. \n\nWe need something different to please the diverse palates of the Horde!\n\nTalk to Nomi and see what he has in mind to spice things up.", objectives = "" }
WordHunterWoW_QuestEN[54041] = { title = "No Survivors", description = "Do you see the encampment on the beach below?\n\nThe Horde followed Tyrande here.\n\nNo doubt some of them have remained here in the shadows in case she returned.\n\nKill them.", objectives = "" }
WordHunterWoW_QuestEN[54042] = { title = "Trouble in Darkshore", description = "We have received some disturbing reports from Darkshore.\n\nWhat was once a secure stronghold for the Horde is now beset by an unnatural darkness. The moon has turned completely black.\n\nThe outposts there have yet to be reinforced with our main force and we are suddenly outnumbered. Nathanos wants you to meet him in Darkshore and find out what happened.", objectives = "" }
WordHunterWoW_QuestEN[54043] = { title = "Dark Ranger Round-Up", description = "These night elf ambushes have left us undermanned. We need reinforcements if we are to hold Darkshore.\n\nBrynja, one of the Dark Lady's val'kyr, can provide us with those reinforcements. Slay the night elves and command her to raise them into our service. Should any prove unwilling... deal with them.\n\nDid I not make myself clear? Go. The Dark Lady has plans for these dark rangers.", objectives = "" }
WordHunterWoW_QuestEN[54044] = { title = "Black Moon Rising", description = "Darkshore has never been known for being bright and sunny, but something strange has happened here. A black moon hangs over everything.\n\nNone of the scouts I sent into the forest have returned. The night elves are up to something. And I need to know what it is.\n\nTheir rank-and-file won't have the information we seek. Hunt down their lieutenants and get them to talk by any means necessary.", objectives = "" }
WordHunterWoW_QuestEN[54045] = { title = "Quit Vining!", description = "This is terrible, {name}! We got harvesters that ain't harvestin'!\n\nWe've been busting our rumps chopping down all these trees, but someone keeps tangling up our machines in the vines! I ain't going out there with those night elves stalkin' around.\n\nSee if you can get in there and free up my equipment!", objectives = "" }
WordHunterWoW_QuestEN[54046] = { title = "We're Not Out of the Woods Yet", description = "<The wisp flickers at you in a confused manner. It seems to want to follow you.\n\nPerhaps it has the information Nathanos seeks.>", objectives = "" }
WordHunterWoW_QuestEN[54047] = { title = "Where Hope Dies", description = "We must carry out the Dark Lady's orders before we are overrun by these newly-invigorated elves.\n\nThere is one night elf in particular that we seek. You may remember her from our last venture into Darkshore. Lucky for you, she is already dead... so she should prove less troublesome than the living ones you've already encountered.\n\nSignal me when you find her corpse.", objectives = "" }
WordHunterWoW_QuestEN[54048] = { title = "To Kill A Warden", description = "<The oppressive feeling of being hunted has reached a peak.\n\nYou know there is someone behind you.>", objectives = "" }
WordHunterWoW_QuestEN[54049] = { title = "The Dead of Night", description = "This is the crux of the Dark Lady's plan for Darkshore. We will raise new champions for the Forsaken and the Horde on this very spot.\n\nGuard the val'kyr. We cannot allow anything or anyone to interrupt them.", objectives = "" }
WordHunterWoW_QuestEN[54050] = { title = "Aftermath", description = "We all have our reasons for accepting the val'kyr's gift. But now is not the time for those discussions.\n\nSylvanas has been dealt a heavy blow today with the loss of Brynja. We will have no time to rest before the Alliance descends on this place.\n\nNathanos has summoned you. There is something you must see.", objectives = "" }
WordHunterWoW_QuestEN[54052] = { title = "Questfall", description = "Me apologies, matey! New to the bow! More of a sword arm, yeah?!\n\nDidn't mean ta give ya such a start! It's just that we're in a bit of a bind, me an' the crew here!\n\nCan ya give us a bit of a hand?! Some upright dogs attacked us in the dead of night! Chased us out of camp in our skivvies!\n\nMaybe ya can help?! They had some sort of big one as their boss! We've been callin' him Barkpaw on account of he was barkin' at us and had big ol' paws!", objectives = "" }
WordHunterWoW_QuestEN[54058] = { title = "Unintended Consequences", description = "<Xal'atath speaks once more.>\n\nThe servants of N'Zoth prepare for their master's return. They intend to conjure a scouring storm to wash away all unbelievers.\n\nThe particular ritual they will invoke requires three ancient artifacts. One of void, one of storm, and one of ocean.\n\nEven now, I hear the void relic calling to me. It is being empowered... or corrupted, I am not sure which. I see it upon a cliff, overlooking a vast sea.\n\nCome, priest. We can find a much better use for such a prize.", objectives = "" }
WordHunterWoW_QuestEN[54059] = { title = "The Night Warrior", description = "It appears these night elves won't give up the information easily... but perhaps that wisp you captured will.\n\nSee if you can get it to reveal what happened here. I don't care how you do it.\n\nFather Norlath will handle the wisp from there.", objectives = "" }
WordHunterWoW_QuestEN[54082] = { title = "More Power", description = "Welcome back, dear test subject.\n\nMy dear sister has kindly asked me to administer today's experiment, which falls below our typical standards of legality...\n\nYou may, as always, choose not to participate and we will acquire sufficient replacement test subjects.\n\nOur new project requires more energy than our generator can manage. We must supercharge it with a jolt of power from the outside.\n\nBondo's Yard has the best power line in Mechagon, so we shall siphon what we need from those rapscallions.", objectives = "" }
WordHunterWoW_QuestEN[54083] = { title = "Grease The Wheels", description = "Kerchunk said you guys was working on getting that mechaspider running again. Well I'm not gonna let you have all the fun!\n\nThat rusty old thing's gonna need a lot of grease to get moving again. So I jury-rigged a special Grease Trap to help you gather grease from the slimes nearby.", objectives = "" }
WordHunterWoW_QuestEN[54084] = { title = "[DNT] Test Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[54085] = { title = "Accessories Sold Separately", description = "", objectives = "" }
WordHunterWoW_QuestEN[54086] = { title = "Right Bot for the Job", description = "We don't waste anything around here. Every defeated bot gets a second chance! \n\nIf I'm going to fix this mechaspider, I'm going to need a few extra wrenchbots working with me. \n\nUse my Bot Re-Energizer on three dead Repeating Wrenchbots and bring them to me, and I'll put them to work.", objectives = "" }
WordHunterWoW_QuestEN[54087] = { title = "You Must be This Height", description = "The moment is here {name}. \n\nFor such a historic moment I feel a gnome, such as myself, should be the one to activate the device.\n\nLet me know when you think we should begin.", objectives = "" }
WordHunterWoW_QuestEN[54088] = { title = "The Legend of Mechagon", description = "I came as soon as I heard!  A mysterious vault has been discovered in Tiragarde. \n\nCenturies ago, the last king of the gnomes, King Mechagon, led his followers in search of a mythical land of technology. He left no clue as to where he was headed, and over time his legend faded into history. This vault could be the first step to discovering King Mechagon's true fate! \n\nI must examine it firsthand. Meet me there, Champion. I could use your assistance.", objectives = "" }
WordHunterWoW_QuestEN[54090] = { title = "Toys For Destruction", description = "Ricket sent word that she was here in Mechagon, so I came right away to help with the uh... research.\n\nI had the peons scour the island for any technology they could find. With da stuff we got here, we gonna make some amazing weapons to fight King Mechagon. Then afterwards, we get rich selling 'em!\n\nHelp me wrangle everyone's ideas into one perfect weapon!", objectives = "" }
WordHunterWoW_QuestEN[54094] = { title = "A Goblin's Definition of Success", description = "I'm all set here, I'm just gonna play around with the mech, I think I got a good idea how it works thanks to ya.\n\nNathanos \"prince of all that's death and destruction\" Blightcaller is gonna want you back on that boat, the Banshee's Scream or whatever it is.\n\nHe'll be happy to know we took care of business. Then again, I got no idea if he even feels happy anymore.", objectives = "" }
WordHunterWoW_QuestEN[54096] = { title = "The Fall of the Sunwell", description = "The flame of the lantern dims. Your final task is to rekindle it.\n\nIn order to do so, you must walk one remaining path. While we are fortunate to hold the Sunwell once again, we must always remember that it was yet another part of us that Arthas took away... and that our late prince was forced to find us a new way of life.\n\nEnter the Sunwell Plateau, and witness its fall.", objectives = "" }
WordHunterWoW_QuestEN[54097] = { title = "The Dark Lady Calls", description = "Champion, the Dark Lady has need of you.\n\nWe cannot speak more of this here. Make haste to Orgrimmar at once.\n\nBest not to keep her waiting.", objectives = "" }
WordHunterWoW_QuestEN[54099] = { title = "The High Overlord", description = "I have asked you here to discuss a matter of great importance to the Horde.\n\nVarok Saurfang is no longer in Stormwind.\n\nLet us discuss this turn of events.", objectives = "" }
WordHunterWoW_QuestEN[54100] = { title = "A Way Out", description = "My spies report that our High Overlord did not leave the way he entered, nor any other way we know of. No signs of him were seen at any of the known exits from the Stockades or the sewers. He simply was in his cell one moment, and gone the next.\n\nBegin your investigation around the city of Stormwind. There must be another way out that we do not know of.\n\nDark Ranger Lyana will meet you there. Her tracking skills are second to none.\n\nDo not fail me, my champion.", objectives = "" }
WordHunterWoW_QuestEN[54101] = { title = "On Track", description = "Keep your head down. We do not want to be seen out here.\n\nOur spies keep watch over Stormwind day and night, and saw no signs of Saurfang. \n\nNor did we notice any oddly-oversized carts or strange ships in the night, if that was what you were thinking.\n\nHow then, did he make his escape?\n\nLet's look around.", objectives = "" }
WordHunterWoW_QuestEN[54102] = { title = "Eastern Escape", description = "It's not unusual to see SI:7 spies lurking around the city, but something about this doesn't feel right.\n\nWe need to find where Saurfang's trail picks up. The last tracks were heading east, towards Redridge.\n\nThe path to Redridge crosses the Three Corners, one of the Alliance's more well-defended towers.\n\nI have an idea. Meet me there.", objectives = "" }
WordHunterWoW_QuestEN[54103] = { title = "Corner Crossing", description = "If Saurfang was headed in this direction, it would have been difficult for him to avoid the Three Corners watchpost. \n\nWe could simply walk in there and demand information, but I have a feeling that they would not part with it willingly.\n\nSo we will take another approach.\n\nI have procured this potion from our alchemists. It will turn us into--ugh--humans for a while.\n\nWe can then question the guards. Perhaps someone saw something.", objectives = "" }
WordHunterWoW_QuestEN[54104] = { title = "Signs of Saurfang", description = "With the guards drunk at their posts, and others out of position, Saurfang would have had little trouble passing Three Corners undetected.\n\nThe path splits just south of town. The back roads of Redridge are poorly patrolled, and are infested with gnolls and spiders. In other words, perfect for an orc trying not to be noticed.\n\nHis most likely path is Lakeridge Highway. We should continue our investigation there.", objectives = "" }
WordHunterWoW_QuestEN[54105] = { title = "Ever Eastward", description = "All signs point to our quarry heading farther east. \n\nTo what end, I am not sure. But I have my suspicions.\n\nI am going to scout the area from the air. Let's meet up at Redridge Pass.", objectives = "" }
WordHunterWoW_QuestEN[54106] = { title = "Tracking Tipoff", description = "Look there, down the hill. One of the Alliance hunters that roam the area.\n\nNo one knows these pathways like them. If our quarry passed through here, that hunter would certainly have seen the tracks. His dogs may even have caught Saurfang's scent.\n\nHere is another dose of the potion. Let us question this one while he is alone.", objectives = "" }
WordHunterWoW_QuestEN[54107] = { title = "Grim Tidings", description = "Ey mon, dat dark ranger, she be lyin' to ya!\n\nSaurfang knew dey'd be comin' for him. He sent me to watch da pass, see who his assassins be. Try to warn him if I could.\n\nShe not be reportin' back nothin'... she gonna kill him. Most likely got a whole buncha deathguards just waitin' for her signal.\n\nWe gotta stop dem! Ya wit' me?", objectives = "" }
WordHunterWoW_QuestEN[54108] = { title = "A Warrior's Death", description = "She gonna try an' take him in, and den no one ever gonna see Varok Saurfang again.\n\nDis was never a rescue mission. Dis be about power, an' control, an' Sylvanas think she be holdin' all da cards.\n\nBut she didn't count on us!\n\nLet's go!", objectives = "" }
WordHunterWoW_QuestEN[54109] = { title = "Queen's Favor", description = "I have two things to ask of you, and I do not ask them lightly.\n\nFirst, I need you to retain the favor of the warchief. She will undoubtedly have questions, and seeds of distrust may begin to grow, but she cannot lose you as an ally. Not now. She would not so willingly part with one of her greatest champions.\n\nIn order to do so, it will have to look like you faced me in combat, and lost. I trust you can take a hit.\n\nSecond, I ask you not to follow me further. I must make this journey alone.", objectives = "" }
WordHunterWoW_QuestEN[54113] = { title = "Every Little Death Helps", description = "<The whispers are faint, but grow louder as you hold the blade in your hand.>\n\nSo weak... need... blood... souls...\n\n<The voice trails off, but you can still sense the dagger urging you on.>", objectives = "" }
WordHunterWoW_QuestEN[54114] = { title = "Every Little Death Helps", description = "<The whispers are faint, but grow louder as you hold the blade in your hand.>\n\nSo weak... need... blood... souls...\n\n<The voice trails off, but you can still sense the dagger urging you on.\n\nIt is a familiar sensation.>", objectives = "" }
WordHunterWoW_QuestEN[54117] = { title = "Every Little Death Helps", description = "<The whispers are faint, but grow louder as you hold the blade in your hand.>\n\nSo weak... need... blood... souls...\n\n<The voice trails off, but you can still sense the dagger urging you on.>", objectives = "" }
WordHunterWoW_QuestEN[54118] = { title = "Every Little Death Helps", description = "<The whispers are faint, but grow louder as you hold the blade in your hand.>\n\nSo weak... need... blood... souls...\n\n<The voice trails off, but you can still sense the dagger urging you on.\n\nIt is a familiar sensation.>", objectives = "" }
WordHunterWoW_QuestEN[54120] = { title = "To Orgrimmar", description = "A darkness in me mind be keeping me from remembering what happened da day I named Sylvanas warchief.\n\nTake me glaive and travel to da pyre where I was cremated in Orgrimmar.\n\nMaster Gadrin be packin' enough juju to call me to dat place.\n\nGo, and I be seein' ya dere.", objectives = "" }
WordHunterWoW_QuestEN[54121] = { title = "Breaking Out Ashvane", description = "The Dark Lady wishes to gain another potential ally in the fight against the Alliance.\n\nLady Ashvane, head of the Ashvane Company, was one of the greatest enemies of Kul Tiras until her capture.\n\nWe are going to release her.\n\nMeet Valtrois in Tiragarde Sound. She and Rexxar are working out a plan to break Ashvane out.", objectives = "" }
WordHunterWoW_QuestEN[54123] = { title = "It Belongs in My Mech!", description = "Check this out! It's my latest creation that someone else came up with and built, Gallywix's Mech of Death!\n\nI got it fueled with all that Azerite you found, but I still need more of the stuff to give it that extra kick.\n\nI was SUPPOSED to have the stuff from our operations here, but there's some sorta Azerite goop causin' a mess!\n\nMy guy Patch made an Azerite vacuum device. I want you to suck the Azerite outta these slimes!", objectives = "" }
WordHunterWoW_QuestEN[54124] = { title = "Avoiding Lawsuits 101", description = "Yo, {name}! I leave the A.M.O.D. for two seconds to deal with old Gallywix and now I'm knee-deep in Azerite goo!\n\nListen, here's the deal. I need ya to rescue some of these goblins from these monsters.\n\nI'll be honest, I skimped on the money that covers their insurance in the event of Azerite-monster-related injuries.\n\nWhat? Who knew that these slimes would appear and attack these guys!\n\nDo me a solid and get these goblins outta there!", objectives = "" }
WordHunterWoW_QuestEN[54126] = { title = "Twist the Knife", description = "The relics are ours... as it was meant to be.\n\nThere is but one more step needed for the great truths to be revealed.\n\nThe naga sought to summon their storm from a place that echoes with ancient power. Though this site has had countless names over the ages, you mortals know it as the Precipice of Oblivion.\n\nI will go on ahead and begin preparations. Join me there.", objectives = "" }
WordHunterWoW_QuestEN[54128] = { title = "Necessary Precautions", description = "That was freakin' awesome! We decimated Mekkatorque's puny little army.\n\nWe got a location on where that little punk and his airship is. That's where he's controllin' all his FORMER mechs.\n\nHere's the plan, we're gonna fly over there, blow up that freak, then destroy his airship!\n\nNow, I ain't no idiot, {name}, I'm the smartest goblin alive. First, we gotta take what they call necessary precautions.\n\nTake this manual, I want you to make sure the G.M.O.D is ready to go!", objectives = "" }
WordHunterWoW_QuestEN[54130] = { title = "Our New Friends", description = "I heard that the Alliance is growing! More and more different kinds of people are joining all the time to fight the mean Horde.\n\nI'm not sure where the embassy is, but I heard it's somewhere here in Stormwind. Can you show me how to get there? I want to see all our new friends!", objectives = "" }
WordHunterWoW_QuestEN[54132] = { title = "Horde of Heroes", description = "The Alliance has begun a coordinated assault against our forces in Stormsong Valley. Attack the enemy forces and drive them back!", objectives = "" }
WordHunterWoW_QuestEN[54134] = { title = "Many Fine Heroes", description = "The Alliance has the upper hand in Vol'dun.  We strike now!  You will lead our forces to victory!", objectives = "" }
WordHunterWoW_QuestEN[54135] = { title = "Romp in the Swamp", description = "Alliance armies are landing on the shores of Nazmir. Drive them back to the sea. Zandalar is ours!", objectives = "" }
WordHunterWoW_QuestEN[54136] = { title = "March on the Marsh", description = "The Alliance has begun a coordinated assault against the Horde in Nazmir. Defeat the enemy forces and drive them out!", objectives = "" }
WordHunterWoW_QuestEN[54137] = { title = "In Every Dark Corner", description = "The Alliance's hold on Drustvar is weak. We will conquer it for the Horde!", objectives = "" }
WordHunterWoW_QuestEN[54138] = { title = "Ritual Rampage", description = "The Alliance has launched an assault into the very heart of the Zandalari empire. Defeat the Horde on their own soil to show them our strength!", objectives = "" }
WordHunterWoW_QuestEN[54139] = { title = "War Is Here", description = "We need to move, {name}. We've received word that the Alliance have mounted an attack through Nazmir.\n\nMake for the Great Seal. King Rastakhan and Princess Talanji are there forming a plan of attack.\n\nMake no mistake, we will crush the Alliance. They are fools to attack us through Nazmir.", objectives = "" }
WordHunterWoW_QuestEN[54140] = { title = "Ride of the Zandalari", description = "It is time de Alliance see de full fury of de Zandalari. Dey are fools to try an attack in Nazmir.\n\nWe must tell de fleet, our warriors, and our flyers dat dey must move out and go to Nazmir at once.\n\nI will go aid our forces at de Blood Gate. Here is a list of dose you must speak with to mobilize our forces.\n\nMove as fast as you can, we must stop de Alliance as quickly as possible.", objectives = "" }
WordHunterWoW_QuestEN[54141] = { title = "The Azsharan Medallion", description = "<On the naga's body you find an ornate metal disc. The writing on its surface resembles elven script, but you cannot decipher it. You suspect the words are written in the Nazja tongue.\n\nPerhaps someone with a knowledge of naga artifacts could translate the text.>", objectives = "" }
WordHunterWoW_QuestEN[54144] = { title = "Orders from Azshara", description = "<Kojo studies the medallion and grimaces.>\n\nUgh... naga.\n\nThis medallion is inscribed with orders. Looks like naga have been commanded to invade our shores and seize artifacts of great power.\n\nYou know, I recently came upon one such object. See that dagger over there? Nasty thing. Gives me the willies. I swear I hear it whispering to me.\n\nI found it on an island in Stormsong Valley, on a makeshift altar. Maybe if you take it there, you'll get an idea of how the naga intended to use it.", objectives = "" }
WordHunterWoW_QuestEN[54145] = { title = "The Loa of Death", description = "Bwonsamdi is a dangerous loa, but even I do not believe he whispered to Vol'jin on his deathbed. To appoint Sylvanas sounds, well... he is not fond of de undead. And from what I have seen of de warchief, she is no fan of death.\n\nWe must be respectful when we speak to Bwonsamdi, or dere will be consequences. Come, stay close.", objectives = "" }
WordHunterWoW_QuestEN[54146] = { title = "Strong New Allies", description = "I heard some adventurers saying that there are new members of the Horde, unlike all the rest! And the best part? They're right here in Orgrimmar!\n\nI don't know where the embassy is... but I bet you do! Can you take me? I heard there are orcs from another planet!", objectives = "" }
WordHunterWoW_QuestEN[54147] = { title = "Confront The Val'kyr", description = "Vol'jin's spirit is growing in power. I should no longer have to maintain a ritual to keep him here.\n\nDis is fortunate, since Bwonsamdi warned me dat Eyir will likely not be pleased with my presence. Apparently she and Bwonsamdi have a past de loa was unwilling to discuss.\n\nWe can proceed when you are ready.", objectives = "" }
WordHunterWoW_QuestEN[54156] = { title = "A Path of Blood", description = "De main fleet of de Alliance and Kul Tirans are off de coast in Nazmir. But we cannot ignore de forces here.\n\nDere seems to be a strange fog coming in from Nazmir. De Kul Tirans must be using some of their voodoo to weaken us.\n\nWe must carve a path of blood through dese Alliance fools. Help our forces by weakening de Alliance.", objectives = "" }
WordHunterWoW_QuestEN[54157] = { title = "No One Left Behind", description = "De warriors here tell me Rokhan made a heroic stand, holding off de Alliance and their champions before being defeated.\n\nRokhan is still here within de Blood Gate, held captive by some strange creature called a Lightforged.\n\nI must stay here and help hold de line. I need you to rescue Rokhan!", objectives = "" }
WordHunterWoW_QuestEN[54161] = { title = "What the Drust Knew", description = "Bal'a dash, {name}.\n\nIf you have a moment, I could use your assistance. I've recently received a shipment of Drust relics that were smuggled out of Kul Tiras.\n\nMost have our usual enchantments, but there is one that is unique. Just holding it makes my hair stand on end. \n\nWith you being my best pupil, I was thinking that it would be enlightening if we disenchanted it together, to see how it was made.\n\nWhat do you say?", objectives = "" }
WordHunterWoW_QuestEN[54163] = { title = "As the Dust Settles", description = "We have achieved a great victory, {name}, though at a cost.\n\nKing Wrynn is gathering the Alliance leadership in Unity Square to discuss matters. He has requested our presence as well. \n\nGo to Unity Square. I'll meet you there shortly.", objectives = "" }
WordHunterWoW_QuestEN[54164] = { title = "The King's Death", description = "King Rastakhan is dead, the Zandalari fleet has been decimated, and we have lost valuable soldiers.\n\nThe Dark Lady is on her way from Orgrimmar to assess the situation. We must figure out our next move before the Alliance strike again.\n\nI believe protocol now would be to pay respects to the fallen king. We will determine our next move afterwards.", objectives = "" }
WordHunterWoW_QuestEN[54165] = { title = "The Return of Derek Proudmoore", description = "I'll admit, I did not think the Little Lion had it in him to kill King Rastakhan. Blood has been spilled, and vengeance must be had.\n\nGive me a moment to express my condolences, then come with me. We have more to do to win this war.", objectives = "" }
WordHunterWoW_QuestEN[54169] = { title = "The Treasury Heist", description = "The Abyssal Scepter is a powerful tidesage artifact and a serious threat to the fleet. The Horde stole it, but it is being held by the Zandalari in their treasury.\n\nThe Storm's Wake has crafted a fake Scepter. Your first job is to obtain the real one without alerting suspicion.\n\nSpeak to me when you are ready to go over the plan.", objectives = "" }
WordHunterWoW_QuestEN[54171] = { title = "The Abyssal Scepter", description = "The Lord Admiral has proposed our next move. It's something we don't think the Horde will expect, but it's dangerous: We're going to steal back the Abyssal Scepter.\n\nYour name came up as someone who could see it through, if you're willing to take the chance.\n\nMeet Lady Jaina at our base in Xibala. She'll have more information for you there.", objectives = "" }
WordHunterWoW_QuestEN[54172] = { title = "The Azsharan Medallion", description = "<On the naga's body you find an ornate metal disc. The writing on its surface resembles elven script, but you cannot decipher it. You suspect the words are written in the Nazja tongue.\n\nPerhaps someone with a knowledge of naga artifacts could translate the text.>", objectives = "" }
WordHunterWoW_QuestEN[54174] = { title = "Orders from Azshara", description = "<Kojo studies the medallion and grimaces.>\n\nUgh... naga.\n\nThis medallion is inscribed with orders. Looks like naga have been commanded to invade our shores and seize artifacts of great power.\n\nYou know, I recently came upon one such object. See that dagger over there? Nasty thing. Gives me the willies. I swear I hear it whispering to me.\n\nI found it nearby at Atal'Gral, on a makeshift altar. Maybe if you take it there, you'll get an idea of how the naga intended to use it.", objectives = "" }
WordHunterWoW_QuestEN[54175] = { title = "Face Your Enemy", description = "We have decided that our best course of action would be to enter the prison disguised as Proudmoore military. Rexxar will be our prisoner.\n\nWe want to keep a low profile until we break Ashvane out.\n\nI find that I work better with reference when undertaking this type of endeavor.\n\nI have chosen some humans that interest me. I would like to examine their faces.\n\nUse the Shard of Vesara on them, and they will be... encouraged to find their way to me.", objectives = "" }
WordHunterWoW_QuestEN[54176] = { title = "Be More Uniform", description = "Head into the foundry. Proudmoore's guards have taken over there. They will provide excellent accessories for our disguises.\n\nI can recreate their faces, but without the clothing, we won't make it far.\n\nGather enough gear to cover us. \n\nWe'll need the Captain's jacket as well. \n\nThere will be less of a challenge at the gate if we outrank them.", objectives = "" }
WordHunterWoW_QuestEN[54177] = { title = "A Brilliant Distraction", description = "We plan to be cautious on entry to Tol Dagor.\n\nI imagine our exit will not be as... subtle.\n\nThat foundry to the west... I hear they made Azerite explosives there.\n\nStock up, we will need them.", objectives = "" }
WordHunterWoW_QuestEN[54178] = { title = "Catching a Ride", description = "Nathanos should have found a boat by now.\n\nLet us hasten to meet him in the harbor.\n\nIt behooves us to take care of this business quickly.\n\nThere are better ways for us to support the Horde's effort here.", objectives = "" }
WordHunterWoW_QuestEN[54179] = { title = "Through the Front Door", description = "We would like the least amount of risk during your retrieval of Priscilla Ashvane.\n\nYou will arrive on the docks during a shift change. From there, you will prepare and enter the prison. \n\nFind me in Zuldazar when you are successful.", objectives = "" }
WordHunterWoW_QuestEN[54183] = { title = "Dead Reckoning", description = "While I have some concerns, I cannot deny the bravery, heroism and sacrifices we have made. That you have made, {name}. Thank you for all the aid you have given to the Alliance.\n\nThe future of our ongoing war campaign is why I have asked everyone here. I wish to look at what we've done, so we can decide on the best way forward.", objectives = "" }
WordHunterWoW_QuestEN[54184] = { title = "Trouble in Gnomeregan", description = "Some strange spikes of electric usage have been happening in Gnomeregan recently. We need you to investigate what is going in there as soon as possible.\n\nWe've received contact from one of the chief engineers in charge of keeping things in Gnomeregan under control, and he has offered to assist us in getting inside to see what's going on.", objectives = "" }
WordHunterWoW_QuestEN[54185] = { title = "Gnomeregan's New Guardians", description = "My personally-modified Mayhem Detection Device has been giving readings off the charts for the last few days. You might be thinking that mayhem and Gnomeregan are synonymous, and to an extent they are, but these readings are beyond anything I've seen before!\n\nI'm not totally sure what's going on inside of Gnomeregan, but something is different. If you are feeling brave enough, I can teleport you deep in there and you can see for yourself.\n\nLet me know when you are ready.", objectives = "" }
WordHunterWoW_QuestEN[54186] = { title = "Pet Battle Challenge: Gnomeregan", description = "Gnomeregan's at Mayhem Level Maximum again. Those machines just don't give up, and keep coming back.\n\nI can teleport us in there again, but all of those crazy robots are back. You sure you want this? I don't.  I mean, maybe I want to watch robots smash things for some entertainment.  I'm sure you will be fine. Lets go!", objectives = "" }
WordHunterWoW_QuestEN[54191] = { title = "Changing Course", description = "Champion, the time for action is upon us. \n\nDevelopments are underway that will change the course of this war. \n\nReport to me aboard Wind's Redemption as soon as possible.", objectives = "" }
WordHunterWoW_QuestEN[54192] = { title = "Sensitive Intel", description = "I've received a report from Kelsey Steelspark. She claims to have discovered something that will aid our war effort.\n\nShe's refused to go into specifics, citing a need for secrecy with such sensitive intel.\n\nIt looks like you'll need to speak to her in person. \n\nShe's expecting you in Xibala.", objectives = "" }
WordHunterWoW_QuestEN[54193] = { title = "This is Huge!", description = "{name}, allow me to introduce Megs and Morton, the gnomes who are going to shake things up for the Alliance in a big way!\n\nThey've been perfecting a device that can take any ordinary animal and turn it into a humongous, unstoppable beast that we can then unleash on our enemies!\n\nI'll let Megs and Morton fill you in on the specifics, but I promise you, this tech is a game changer!", objectives = "" }
WordHunterWoW_QuestEN[54194] = { title = "Real Big Power", description = "We're still building a harness for the Embiggifier, but we need to test its core first. That's where the real power is!\n\nThis technology is years ahead of the Horde's, but it's so easy to use that even an orc could do it!\n\nJust point and click!", objectives = "" }
WordHunterWoW_QuestEN[54195] = { title = "A Beast with Brains", description = "For optimal results, the Embiggifier should be used on someone with substantial intellect. \n\nGood thing our partner is as smart as they come. \n\nHe and his kind have been empowered by kaja'mite, granting them exceptional intelligence! \n\nHead up to the gorge and let Grong know we're ready to begin the embiggifying!", objectives = "" }
WordHunterWoW_QuestEN[54196] = { title = "Out of Options", description = "My kind are hunted like animals.\n\nWe've tried to reach a resolution through civil discourse, but these poachers recoil from rational thought. They revel in brutality.\n\nI ask you, {name}: Who are the real animals?\n\nIt pains me to descend to their level, but I fear I've exhausted all other options.", objectives = "" }
WordHunterWoW_QuestEN[54197] = { title = "Freedom for the Da'kani", description = "Have you seen the barbaric conditions to which the Da'kani are subjected? Corralled and caged, awaiting slaughter, or worse...\n\nI cannot leave here in good faith without first seeing that my kind are liberated.", objectives = "" }
WordHunterWoW_QuestEN[54198] = { title = "Bittersweet Goodbyes", description = "You've helped me prepare my village for my departure, but now I must prepare myself. \n\nMeet me within the grotto, where I will say my farewells.", objectives = "" }
WordHunterWoW_QuestEN[54199] = { title = "The Needs of the Many", description = "Ever since the kaja'mite began bubbling around the gorge, I have been searching for meaning. Why was I burdened with intelligence? What is my purpose?\n\nI have found my answers in the Embiggifier.\n\nI was meant to help the Alliance defeat the Horde.\n\nIf I can save lives by volunteering, then my choice is clear.\n\nThe needs of the many outweigh the needs of one.\n\nI am ready, {name}.", objectives = "" }
WordHunterWoW_QuestEN[54200] = { title = "Bring the Base", description = "We'll need to collect some baseline statistics before we use the Embiggifier.\n\nGrong will be asked to perform basic tasks pertaining to speed, intelligence, and strength. \n\nThis will help us measure the increase once he's been embiggified.", objectives = "" }
WordHunterWoW_QuestEN[54201] = { title = "Fit for Grong", description = "Grong is already impressively large. In fact, I don't think our Embiggifier is going to fit around his noggin without some modification. \n\nI'll require an ample supply of ore to make the necessary adjustments, but we're in luck. The goblins nearby have already done the work of mining it; we just need to take it off their hands!\n\nSecure an ample amount of Azerite-infused ore, and we'll be back in business!", objectives = "" }
WordHunterWoW_QuestEN[54202] = { title = "Calibrate the Core", description = "The Embiggifier is nearly ready! All that's left to do is calibrate its core. \n\nThe best way to do that without catastrophic results is to use it on things that are already dead.\n\nThis should be a simple task!\n\nI have a hunch you excel at making things dead.", objectives = "" }
WordHunterWoW_QuestEN[54203] = { title = "The Embiggining", description = "I'll give you the quick rundown before we get started.\n\nThe Embiggifier is remotely controlled. \n\nSee this big red button?\n\n<Megs gestures to the device in her hand.> \n\nThis jolts the wearer with a surge of power, making them bigger.\n\nFor safety reasons, you should remain here at camp. \n\nI think that's it! Are you ready to science?", objectives = "" }
WordHunterWoW_QuestEN[54204] = { title = "Total Temple Destruction", description = "Grong is our greatest achievement, and he's ready to be unleashed!\n\nThe Horde is staging its troops at a temple to the north. \n\nMagister Umbric's portal will get you there fast. Then Grong can get to work!", objectives = "" }
WordHunterWoW_QuestEN[54205] = { title = "A Nice Nap", description = "I'm not sure how much longer those chains will hold. \n\nGrong's going to have to take a little nap until he's ready to be deployed.\n\nUse this dart. It's been double-dipped in something potent enough to take down a direhorn, so it should do the trick. \n\nGrong would want you to be the one to do it.", objectives = "" }
WordHunterWoW_QuestEN[54206] = { title = "The Sleeper Agent", description = "Your work here is done, {name}. Morton and Megs can take it from here. \n\nHead back to Boralus and let Halford know we've secured the weapon. \n\nDon't you worry one wink about Grong. Morton and Megs will make sure he's well looked after.", objectives = "" }
WordHunterWoW_QuestEN[54207] = { title = "Retaking the Outpost", description = "We can handle de rest of de Alliance. I received a report that Hexlord Raal's forces are having issues up ahead.\n\nHe claims dat dere is an even thicker fog enveloping Nazmir. De Alliance must be using some tricks to slow us down.\n\nGo to Nazmir to see what can be done to help Hexlord Raal. We must reach dat fleet and destroy de Alliance!", objectives = "" }
WordHunterWoW_QuestEN[54208] = { title = "Minesweeper", description = "The Alliance are stalling our efforts here with this irritating fog, as well as layering the entire area with traps.\n\nWe will suffer too many casualties if we try marching our army through this trap-infested area.\n\nI've heard you're good at sneaking around. Use your talents to disarm the traps in this area.\n\nI'll deal with getting the goblin's parts back from the Alliance while you disarm those traps.", objectives = "" }
WordHunterWoW_QuestEN[54210] = { title = "Chapter 4 A End", description = "I'm glad we can count on you {name}.", objectives = "" }
WordHunterWoW_QuestEN[54211] = { title = "Putting the Gob in Gob Squad", description = "Yo! We gotta get the rest of the Gob Squad back if we wanna fix the A.F.M.O.D.!\n\nSo, our mech got trashed. It was rough. The rest of the Gob Squad are hidin' out there, waiting for word when it's safe.\n\nTake this tracker. It'll tell ya when you're getting close to one of the squad. When you get real close, you should see 'em.\n\nThat'll tell any of the squad nearby that it's safe to come outta hidin' and come back here.\n\nWith the right goblins and parts, we'll be killing Alliance in no time!", objectives = "" }
WordHunterWoW_QuestEN[54212] = { title = "Re-rebuilding the A.F.M.O.D.", description = "Alright, so, we're goin' after the Alliance through this crazy fog. We gotta retake Zo'bal ruins up ahead.\n\nWe can do that real easy if we fix up our mech, A.F.M.O.D. - a flying mech of death! \n\nThe Alliance wrecked it in their initial attack and took a bunch of its parts. Get those parts back and we'll have this thing fixed in no time!", objectives = "" }
WordHunterWoW_QuestEN[54213] = { title = "It's Alive!", description = "We got the A.F.M.O.D. repaired and it works perfectly! Eh, except that it's got no power.\n\nPrincess Talanji seems like she can help us out with this. Ask her if she can give the mech a jumpstart!\n\nOnce we're set, we can use this thing to mow down the Alliance, take back Zul'jan ruins, and push forward to blow up that fleet!", objectives = "" }
WordHunterWoW_QuestEN[54224] = { title = "The Battle of Zul'jan Ruins", description = "General Rakera has pushed forward with de army. Raal and his forces are still grounded until we remove dis fog.\n\nYou must pilot de A.F.M.O.D. and help our forces retake Zul'jan ruins. Only den can we move ahead to stop de Alliance and dis fog.\n\nRokhan, and I will join you. De Alliance must see dat our victory is swift and decisive. \n\nI would have our enemies cower before us when dey meet dere ends. Such is de price for defiling our lands.", objectives = "" }
WordHunterWoW_QuestEN[54225] = { title = "Mission Report: The Great Seal", description = "Your followers have sent a report regarding the mission at The Great Seal.\n\nIt details that the mission was a success and that a Mission Command Table has been constructed.\n\nDeliver the report to Nathanos Blightcaller aboard The Banshee's Wail.", objectives = "" }
WordHunterWoW_QuestEN[54231] = { title = "Outpost Upgrade: The Great Seal", description = "The mission at The Great Seal was a success. Well done, {name}.\n\nA Mission Command Table is now ready for use.\n\nTravel to The Great Seal and see that the troops quality of work is up to our standard.", objectives = "" }
WordHunterWoW_QuestEN[54239] = { title = "Mission Report: Zul'jan Ruins", description = "Your followers have sent a report regarding the mission at Zul'jan Ruins.\n\nIt details that the mission was a success and that the power of the Loa has increased, allowing for Boons to persist longer.\n\nDeliver the report to Nathanos Blightcaller aboard The Banshee's Wail.", objectives = "" }
WordHunterWoW_QuestEN[54240] = { title = "Outpost Upgrade: Zul'jan Ruins", description = "The mission at Zul'jan Ruins was a success. Well done, {name}.\n\nThe Boons of the Loa are now more powerful and will be granted whenever you are in Zandalar.\n\nTravel to the Zul'jan Ruins and honor an altar of your choice.", objectives = "" }
WordHunterWoW_QuestEN[54244] = { title = "We Have Them Cornered", description = "General Rakera has already begun mobilizing our forces to our next target: Zalamar.\n\nOnce we destroy de Alliance dere, we can push forward to de coast and destroy de source of dis fog.\n\nDe Alliance will have nowhere to hide. We will surround their fleet and end dis war, once for all.\n\nDey will wish dey never stepped foot in Nazmir.\n\nCome. We shall ride together to Zalamar and ensure our victory!", objectives = "" }
WordHunterWoW_QuestEN[54249] = { title = "Zandalari Justice", description = "We must wipe out whatever is left of de Alliance in Zalamar. Den we can find de source of dis fog and dere fleet.\n\nRokhan will scout ahead to find dis Telaamon. He appears to be de general leading de forces here.\n\nI need you to go in and wipe out de Alliance forces within Zalamar so dat we can crush dem once and for all.\n\nFind Rokhan in Zalamar after dey have been weakened.", objectives = "" }
WordHunterWoW_QuestEN[54258] = { title = "Mission Report: Vulpera Hideaway", description = "Your followers have sent a report regarding the mission at the Vulpera Hideaway.\n\nIt details that the mission was a success and that a Caravan is now available for use.\n\nDeliver the report to Nathanos Blightcaller aboard The Banshee's Wail.", objectives = "" }
WordHunterWoW_QuestEN[54260] = { title = "Outpost Upgrade: Vulpera Hideaway", description = "The mission at Vulpera Hideaway was a success. Well done, {name}.\n\nThe Caravan Master is very thankful for our assistance and ready to return the favor.\n\nTravel to Vulpera Hideaway and speak with the Caravan Master to see what he can do for you.", objectives = "" }
WordHunterWoW_QuestEN[54262] = { title = "Mission Report: Brennadam", description = "Your followers have sent a report regarding the mission at Brennadam.\n\nIt details that they were successful in gaining access to a Harvester mount.\n\nDeliver the report to High Commander Wyrmbane aboard the Wind's Redemption.", objectives = "" }
WordHunterWoW_QuestEN[54263] = { title = "Outpost Upgrade: Brennadam", description = "The mission at Brennadam was a success. Well done, {name}.\n\nWe now have access to what's rumored to be a very fast Harvester that you are able to ride. Sounds strange to me, but what do I know?\n\nTravel to Brennadam and enquire about this upgrade.", objectives = "" }
WordHunterWoW_QuestEN[54265] = { title = "Orders from Azshara", description = "This medallion is inscribed with orders commanding the naga to invade our shores and seize artifacts of power.\n\n<Kojo studies you thoughtfully.>\n\nI've heard tales of a priest who used a horrifying dagger to fight the Burning Legion. It is said this blade... Xal'atath... whispers secrets of the deep. It might be our best chance of uncovering what the naga seek.\n\nI'm told the naga have an altar on an island in Stormsong Valley. If you take Xal'atath there, the dagger may reveal crucial information.", objectives = "" }
WordHunterWoW_QuestEN[54269] = { title = "None Shall Escape", description = "De Alliance are using de Dark Iron's mole machines to transport troops in and out of Zalamar.\n\nWe need dose machines destroyed. We are going to establish Zalamar as our forward base to attack de Alliance's main fleet.\n\nTake out dem machines, den find Rokhan within Zalamar. He be tracking down where de Alliance general be hidin'.", objectives = "" }
WordHunterWoW_QuestEN[54270] = { title = "Breaking Mirrors", description = "We have reports dat Telaamon,  de Lightforged in charge of dis attack, can create mirror images of himself to strike us down.\n\nTwo Zandalari, Witch Doctor Kejabu and Jo'chunga, have offered to go in and help fight his mirror images. \n\nI want you to ensure dey survive.\n\nEliminating dese strange images should make Telaamon weaker, allowing you and Rokhan to slay him.", objectives = "" }
WordHunterWoW_QuestEN[54271] = { title = "Telaamon's Purge", description = "Telaamon, de Lightbringer leadin' dis assault, be in Hir'eek's cave. He must be thinkin' he can take us all by himself.\n\nWhen he is dead, we be sendin' dis assault force into chaos, allowin' us ta be marchin'  on de Alliance along de shore.\n\nAnd hopefully, we can be findin' de source of de fog and destroyin' it.\n\nDa three of us be ambushin' Telaamon once ya start fightin'. He ain't gettin' outta here alive.", objectives = "" }
WordHunterWoW_QuestEN[54275] = { title = "Parting Mists", description = "It be time ta face de main Alliance fleet. Dey be on da beachhead nearby.\n\nI can be feelin' da dark voodoo from dat fog nearby. Princess Talanji be wantin' ta destroy dat mojo as soon as we can.\n\nI can be gettin' us outta dis cave real fast, den we be ridin' with da princess and Rakera ta put an end ta all dis.", objectives = "" }
WordHunterWoW_QuestEN[54276] = { title = "Trouble in Gnomeregan", description = "Our engineers have reported surges of electric usage in Gnomeregan recently. We need you to investigate what is going in there as soon as possible.\n\nWe made contact with one of the chief engineers in charge of keeping the robots in Gnomeregan under control, and he has offered to assist us in getting inside to see what's going on.", objectives = "" }
WordHunterWoW_QuestEN[54280] = { title = "Fly Out to Meet Them", description = "De Alliance scum will pay for dis! Our army is moving as fast as it can to defend our city.\n\nRide with Raal to get back to de entrance to our city. We must stop de Alliance!", objectives = "" }
WordHunterWoW_QuestEN[54282] = { title = "Battle of Dazar'alor", description = "Zandalar is already under attack! My people are fleeing and de Alliance are infesting my streets.\n\nRakera's scouts say dat Jaina Proudmoore is leading de assault.\n\nShe and her kind will pay for dis brazen assault on my people. \n\nGather your allies and push de Alliance back. We must protect my father and destroy de Alliance!", objectives = "" }
WordHunterWoW_QuestEN[54284] = { title = "Mission Report: Castaway Point", description = "Your followers have sent a report regarding the mission at Castaway Point.\n\nIt details that they were successful in gaining access to an extremely large cannon.\n\nDeliver the report to High Commander Wyrmbane aboard the Wind's Redemption.", objectives = "" }
WordHunterWoW_QuestEN[54288] = { title = "Outpost Upgrade: Castaway Point", description = "The mission at Castaway Point was a success. Well done, {name}.\n\nWe now have access to a very large cannon which promises to be a fast way to travel to Tiragarde Sound. Glad that's not how I plan to get around.\n\nTravel to Castaway Point and enquire about this upgrade.", objectives = "" }
WordHunterWoW_QuestEN[54300] = { title = "Breaking the Faith", description = "De faithful are among de most revered in Zandalari society. They are an example for others to aspire to. This is not de example we want others to follow.\n\nWe must respond in kind.\n\nPrincess Talanji wishes for us to spare them that will see reason. Do so, if you can find any willing to surrender.\n\nFor de rest, give them a swift death.", objectives = "" }
WordHunterWoW_QuestEN[54301] = { title = "Talanji's Mercy", description = "I know my priests, {name}. Such an uproar did not appear out of thin air.\n\nThere is much I have to atone for, but I am not yet ruler. I have not had de time to do what is needed for de faithful of Zandalar. That does not mean they deserve to suffer.\n\nGo into de Terrace of de Chosen and find them that refuse to fight. See that they get out safely. I will hold none of them accountable for de actions of others.", objectives = "" }
WordHunterWoW_QuestEN[54302] = { title = "The Fall of Zuldazar", description = "It's time, {name}. We have the Abyssal Scepter, along with confirmation that the bombs placed amongst the Zandalari fleet are still active.\n\nUnfortunately, even with everything at our disposal, we would still lose a frontal assault against the Zandalari empire.\n\nFor that reason, we plan to lure the forces of the Horde and the Zandalari away from the harbor.\n\nMathias Shaw is holding a meeting nearby, and he has requested your presence.", objectives = "" }
WordHunterWoW_QuestEN[54303] = { title = "The March to Nazmir", description = "Greetings, {name}. I am Blademaster Telaamon, and I have volunteered to lead this mission against the Horde.\n\nOur forces will be gathering off the coast of Nazmir. Go now and we shall all meet there.\n\nIf all goes according to plan, we will lure the Horde away from Zandalar and bring an end to this war.", objectives = "" }
WordHunterWoW_QuestEN[54306] = { title = "Mission Report: Arom's Stand", description = "Your followers have sent a report regarding the mission at Arom's Stand.\n\nIt details that they were successful in gaining access to a blessing from the Order of Embers.\n\nDeliver the report to High Commander Wyrmbane aboard the Wind's Redemption.", objectives = "" }
WordHunterWoW_QuestEN[54307] = { title = "Outpost Upgrade: Arom's Stand", description = "The mission at Arom's Stand was a success. Well done, {name}.\n\nWe now have access to a blessing from the Order of Embers.\n\nTravel to Arom's Stand and enquire about this blessing.", objectives = "" }
WordHunterWoW_QuestEN[54310] = { title = "Repurposing Their Village", description = "Myself and Shaw will provide support for Telaamon's army until our distraction is set up.\n\nFirst, we need to clear the blood trolls out of their nearby village, Zalamar, in order to move our army forward.\n\nThat's where you come in. We need you to assault the blood trolls there to weaken their forces, then our army will arrive.\n\nTelaamon will be on site to help you, meet with him once you've weakened their forces. \n\nI will be here with Shaw ensuring our forces aren't seen.", objectives = "" }
WordHunterWoW_QuestEN[54312] = { title = "Fog of War", description = "Do not mind this, I am finishing off this insect. You have bigger matters to handle.\n\nOur army is moving within Zalamar as we speak. But the Horde will know our army's true size without aid.\n\nSpeak with Brother Pike and have him perform the ritual with the Abyssal Scepter to cover Nazmir in a thick fog.\n\nHe claims the illusion will also mimic an entire fleet off the beach. Let us hope he is right.\n\nI will join you once I finish with this stain upon Azeroth.", objectives = "" }
WordHunterWoW_QuestEN[54402] = { title = "Shifting Gears", description = "{name}! The Alliance has made a new request for Gnomeregan's might.\n\nCaptain Sparknozzle wishes for your expert assistance in the matter.\n\nHe'll be waiting for you in New Tinkertown, outside of Gnomeregan.", objectives = "" }
WordHunterWoW_QuestEN[54404] = { title = "Dark Iron Machinations", description = "We have some additional support for our plan to deceive the Horde and assault the Blood Gates, but we need your help.\n\nThe Dark Iron dwarves have several mole machines waiting to erupt and supply fresh troops.\n\nI've determined several spots within Zalamar that would be perfect for them to use.\n\nTake this device and plant it in the following areas. It will send a message to the Dark Iron dwarves to erupt from there.\n\nThey will stay safely in their machines until our army arrives.", objectives = "" }
WordHunterWoW_QuestEN[54407] = { title = "Lurking in the Swamp", description = "We have Zalamar, and we've got our fog. Now, we have to take the attack to the Horde.\n\nOur goal is to take as much land in Nazmir as possible to make the Horde think our main fleet is here.\n\nThe first target is Zul'jan ruins, one of the Horde's main bases in Nazmir.\n\nWe'll have to make our way through the swamps to our attack position. Meet us there.", objectives = "" }
WordHunterWoW_QuestEN[54412] = { title = "Zul'jan Deluge", description = "Through the mists is Zul'jan ruins, a major Horde outpost in Nazmir. We need to take it over to help our forces push forward.\n\nThe Horde needs to believe a large Alliance army is here, so we're going to throw everything we've got at taking the ruins.\n\nOur army will charge forward to attack, while you join them using my water elemental.\n\nMeet me outside of the ruins when you're done, we'll need to keep pushing forward.", objectives = "" }
WordHunterWoW_QuestEN[54416] = { title = "Warfront Preparations", description = "We must make our preparations. \n\nReturn to Zandalar immediately and rally our forces. Any contributions to our cause must be made.\n\nGo. We will hold for now.", objectives = "" }
WordHunterWoW_QuestEN[54417] = { title = "Showing Our Might", description = "We are within reach of the Blood Gate in Zandalar. Once we take that, the Horde and Zandalari will believe our full invasion has begun.\n\nOur forces have already engaged the Zandalari within the Fallen Outpost. We'll need your help to push them back.\n\nI'll be focusing on finishing off what remains of the Horde and Zandalari back in Zul'jan ruins.", objectives = "" }
WordHunterWoW_QuestEN[54418] = { title = "The Mech of Death", description = "We have reports of a goblin machine causing havoc among our troops up ahead. They call it the A.M.O.D.\n\nIt is a crude machine compared to what the Lightforged have aboard the Vindicaar.\n\nTogether, you and I will bring down this machine. Go, I will await for you near the machine and engage it when you are ready.", objectives = "" }
WordHunterWoW_QuestEN[54419] = { title = "Quelling the Masses", description = "One of my own in de Rastari has seen fit to rile de drudges and guards in de Zocalo.\n\nThey threaten de stability of our empire with this foolishness. If they are angry, we can address it. But this wanton destruction will not stand.\n\nGo down into de market of de Zocalo and bring about calm however you can. Choose de method that works for you.\n\nI care only for de result: Peace, so Talanji can finally be crowned.", objectives = "" }
WordHunterWoW_QuestEN[54421] = { title = "Taming their Beasts", description = "Our goal is to assault the Blood Gate, but to be blunt, we don't have the force necessary for this.\n\nThat's why we have gnomish technology. The Zandalari have battle beasts, direhorns mounted with powerful weapons.\n\nSeveral of these beasts are resting within the Fallen Outpost. This device, the Re-Discombobulator, will give us control over these animals. \n\nTake this device and use it on these battle beasts. We'll assault the Blood Gates once we have them under our control.", objectives = "" }
WordHunterWoW_QuestEN[54424] = { title = "A Shady Character", description = "Your followers tell of a smuggler of wit and guile, who was able to charm them with stories of lands far and wide.\n\nThough it cost a fair sum to retrieve, they managed to obtain a token which when displayed to the smuggler, will allow the bearer to purchase his wares.", objectives = "" }
WordHunterWoW_QuestEN[54433] = { title = "Orders from Azshara", description = "This medallion is inscribed with orders commanding the naga to invade our shores and seize artifacts of power.\n\n<Kojo studies you thoughtfully.>\n\nI've heard tales of a priest who used a horrifying dagger to fight the Burning Legion. It is said this blade... Xal'atath... whispers secrets of the deep. It might be our best chance of uncovering what the naga seek.\n\nI recently came upon a makeshift naga altar in Atal'Gral. If you take Xal'atath there, the dagger may reveal crucial information.", objectives = "" }
WordHunterWoW_QuestEN[54436] = { title = "Wisp'd Into Shape", description = "We're off to a good start, but we're going to need more wood if we want to win this battle!\n\nThe Horde has set up a lumber mill to the north of Bashal'Aran, past Forlorn Crossing. If we take it, we can stop them from destroying the forest while also getting the wisps to help us out.\n\nIt's a two-for-one!", objectives = "" }
WordHunterWoW_QuestEN[54438] = { title = "Crucible of Storms: Relics of Shadow", description = "Your intention to stop the naga attacks was noble, {name}. But that shadowy dagger tricked you into delivering powerful relics into the hands of a great enemy.\n\nNo doubt those artifacts will be well defended. Gather your allies, {class}, and return to the Crucible of Storms.\n\nDefeat any opponents that stand in your way. Ensure the relics cannot be used against the Alliance.\n\nThe naga cannot be allowed to summon their storm... or to call forth something even worse.", objectives = "" }
WordHunterWoW_QuestEN[54439] = { title = "Crucible of Storms: Relics of Shadow", description = "Your intention to stop de naga attacks was noble, {name}. But de talking dagger tricked you into delivering powerful relics into de hands of our enemies.\n\nNo doubt dese artifacts will be well defended. Gather your allies, {class}, and return to de Crucible of Storms.\n\nDefeat any opponents dat stand in your way. Ensure dese relics cannot be used against de Horde.\n\nAnd if any shadowy weapons ask you to do favors for dem in de future... I suggest you decline.", objectives = "" }
WordHunterWoW_QuestEN[54441] = { title = "Taking the Blood Gate", description = "We have our forces spread out throughout Nazmir, but we need to do something that will force Rastakhan into action.\n\nWe must personally march into Zuldazar and take the Blood Gate. This will cause them to throw their full army at us.\n\nAs you can see, we're the only ones left that can assault the Blood Gate.\n\nShaw and Telaamon will stay behind to help the rest of the army move up. \n\nYou and I will ride the battle beast into the Blood Gate and take it by force.", objectives = "" }
WordHunterWoW_QuestEN[54447] = { title = "A Shady Character", description = "Your followers tell of a smuggler of wit and guile, who was able to charm them with stories of lands far and wide.\n\nThough it cost a fair sum to retrieve, they managed to obtain a token which when displayed to the smuggler, will allow the bearer to purchase his wares.", objectives = "" }
WordHunterWoW_QuestEN[54459] = { title = "He Who Walks in the Light", description = "Shaw reports that Zandalari scouts have been dispatched to alert of our \"full assault\". \n\nWe did it, {name}. The Horde and Zandalari will throw their armies at our forces within Nazmir.\n\nWe cannot let their sacrifice be in vain. We must get back to Boralus and let Halford know it's time to strike.\n\nCome, I'll create a portal for us to leave, once we say one final word to Telaamon.", objectives = "" }
WordHunterWoW_QuestEN[54463] = { title = "Alchemical Equations", description = "", objectives = "" }
WordHunterWoW_QuestEN[54464] = { title = "Alchemical Equations", description = "", objectives = "" }
WordHunterWoW_QuestEN[54465] = { title = "Blacksmithing Plans", description = "", objectives = "" }
WordHunterWoW_QuestEN[54466] = { title = "Blacksmithing Plans", description = "", objectives = "" }
WordHunterWoW_QuestEN[54469] = { title = "Fresh Dishes", description = "", objectives = "" }
WordHunterWoW_QuestEN[54470] = { title = "Fresh Dishes", description = "", objectives = "" }
WordHunterWoW_QuestEN[54473] = { title = "Enchanted Formulae", description = "", objectives = "" }
WordHunterWoW_QuestEN[54474] = { title = "Enchanted Formulae", description = "", objectives = "" }
WordHunterWoW_QuestEN[54475] = { title = "Engineered Blueprints", description = "", objectives = "" }
WordHunterWoW_QuestEN[54476] = { title = "Engineered Blueprints", description = "", objectives = "" }
WordHunterWoW_QuestEN[54477] = { title = "Inscribed Methods", description = "", objectives = "" }
WordHunterWoW_QuestEN[54478] = { title = "Inscribed Methods", description = "", objectives = "" }
WordHunterWoW_QuestEN[54479] = { title = "Jeweled Designs", description = "", objectives = "" }
WordHunterWoW_QuestEN[54480] = { title = "Jeweled Designs", description = "", objectives = "" }
WordHunterWoW_QuestEN[54481] = { title = "Leathered Patterns", description = "", objectives = "" }
WordHunterWoW_QuestEN[54482] = { title = "Leathered Patterns", description = "", objectives = "" }
WordHunterWoW_QuestEN[54484] = { title = "Tailored Training", description = "", objectives = "" }
WordHunterWoW_QuestEN[54485] = { title = "Battle of Dazar'alor", description = "Our naval forces are ready to sail for Zuldazar. By the time we're there, the Horde and Zandalari forces should be in Nazmir.\n\nKeeshan and Kelsey checked on the bombs placed within Zuldazar harbor. They're primed and ready to destroy the Zandalari fleet.\n\nGather any of your allies and prepare to set sail for Zuldazar. \n\nWe will strike down the Zandalari and remove the Horde's most powerful ally from this war.", objectives = "" }
WordHunterWoW_QuestEN[54494] = { title = "Expanding our Influence", description = "As we expand the War Effort on the enemy continent we are finding ideal locations to establish new outposts, and even upgrade our current ones.\n\nOnce secure, these outposts will allow us to utilize a new flight network to quickly and easily navigate the area.", objectives = "" }
WordHunterWoW_QuestEN[54495] = { title = "Expanding our Influence", description = "As we expand the War Effort on the enemy continent we are finding ideal locations to establish new outposts, and even upgrade our current ones.\n\nOnce secure, these outposts will allow us to utilize a new flight network to quickly and easily navigate the area.", objectives = "" }
WordHunterWoW_QuestEN[54510] = { title = "Mischief Managed", description = "Thank you for returning this artifact to us, {name}. Now that we have the Abyssal Scepter, the fleet can advance without fear of the seas being turned against us.\n\nPlease report our success to High Commander Wyrmbane.", objectives = "" }
WordHunterWoW_QuestEN[54518] = { title = "Zero Zeppelins", description = "The Horde zeppelins proved to be problematic for our forces here. I tried to construct something quickly, but while the weapon had power, it didn't have the range necessary to take them out.\n\nThe Lord Admiral has provided us with an expedient solution to the problem!\n\nUse this jury-rigged hand cannon on the zeppelins. A quick application of high energy and heat will cause thermal shock and critical failure!\n\nTo simplify, blow them up while they're grounded!", objectives = "" }
WordHunterWoW_QuestEN[54519] = { title = "Squad Goals", description = "My patrol squad fought off the Horde so Galeheart and I could fly free. I have to stay with the Lord Admiral, so I can't look for them on my own. With any luck, they're out there fighting and waiting for reinforcements.\n\nWell, we're here to help save them. Would you find the rest of my patrol squad for me?", objectives = "" }
WordHunterWoW_QuestEN[54559] = { title = "Free Plumeria!", description = "My poor Plumeria has been captured by an exceptionally brutal villain. He has been overseeing the spread of pestilence along the wharf.\n\nRosaline needs my mechanical expertise in fixing our weapons. Would you free my poor Plumeria and slay the vile knight tormenting her?", objectives = "" }
WordHunterWoW_QuestEN[54576] = { title = "Gnomeregan's Finest", description = "The leaders of the Alliance have agreed to fund an elite gnomish aerial task force.\n\nAnd you have been chosen to lead the test team for the Gnomish Elite Aerial Rangers. I have assembled some of the finest tinkers and soldiers from Gnomeregan, who are now under your command.\n\nThe three of them are already here in New Tinkertown. Introduce yourself and assemble them.", objectives = "" }
WordHunterWoW_QuestEN[54577] = { title = "Shadowed Halls and Dusty Cogs", description = "An elite aerial unit wouldn't be complete without the newest innovations in flying machine technology.\n\nThere's just one small problem.\n\nThe innovative new engine we built was left behind when we evacuated Gnomeregan. We need that prototype if we want these bombers to safely get off the ground!", objectives = "" }
WordHunterWoW_QuestEN[54579] = { title = "The Gnome Behind the Trogg", description = "If I just attach the core of this to the input module here... Amplify the matched frequency here...\n\n<Tinkerbow mumbles a few more things while she attaches the communication device to the console.>\n\nFlip the switch, Commander! Just make sure it's the right one. The left one is the self-destruct switch. Or was that reversed...", objectives = "" }
WordHunterWoW_QuestEN[54580] = { title = "A Tundra Conundrum", description = "While you were in Gnomeregan, we received a distress signal from Fizzcrank Airstrip in Borean Tundra. This seems like the perfect opportunity to show off what G.E.A.R. can do!\n\nI've sent the rest of your squad ahead. Meet them out there.", objectives = "" }
WordHunterWoW_QuestEN[54581] = { title = "Now With More Mechanical Fowl", description = "The gnomes here report that troggs came down from the north and started attacking everygnome and everything.\n\nSo now it's our job to fix this situation! And luckily, I have the perfect plan for it. We need to calibrate the bomber's gun, and doing so on the ground is much less risky than up in the air.\n\nGive it a go, Commander!", objectives = "" }
WordHunterWoW_QuestEN[54582] = { title = "Smarter Than Your Average Trogg", description = "<Cog Captain Winklespring's voice springs to life over your personal communication system.>\n\nOne of the recon pilots did a scouting run over the station. She reported that there seems to be a trogg on the top level that is larger and smarter than the others. He's somehow managed to get one of the Defendo-Tanks for the station working in his favor.\n\nTake him out!", objectives = "" }
WordHunterWoW_QuestEN[54610] = { title = "Paragon of the Tortollan Seekers", description = "Your allies among the Tortollan Seekers have requested your presence. They wish to reward you for your continued efforts on their behalf.", objectives = "" }
WordHunterWoW_QuestEN[54611] = { title = "Paragon of the Champions of Azeroth", description = "A grateful Magni Bronzebeard has requested your presence. He wishes to reward you for your exceptional aid.", objectives = "" }
WordHunterWoW_QuestEN[54618] = { title = "Paragon of the 7th Legion", description = "Commanders of the 7th Legion forces have requested your presence.  They wish to reward you for your exceptional efforts.", objectives = "" }
WordHunterWoW_QuestEN[54626] = { title = "Paragon of the Honorbound", description = "Commanders of the Honorbound forces have requested your presence.  They wish to reward you for your exceptional efforts.", objectives = "" }
WordHunterWoW_QuestEN[54627] = { title = "Paragon of the Order of Embers", description = "Your allies among the Order of Embers have requested your presence. They wish to reward you for your continued efforts on their behalf.", objectives = "" }
WordHunterWoW_QuestEN[54628] = { title = "Paragon of the Storm's Wake", description = "The grateful Storm's Wake forces have requested your presence. They wish to reward you for your continued efforts on their behalf.", objectives = "" }
WordHunterWoW_QuestEN[54629] = { title = "Paragon of the Proudmoore Admiralty", description = "The grateful leaders of the Proudmoore Admiralty have requested your presence. They wish to reward you for your continued aid to their house.", objectives = "" }
WordHunterWoW_QuestEN[54630] = { title = "Paragon of Talanji's Expedition", description = "Your allies among Talanji's Expedition have requested your presence. They wish to reward you for your continued efforts on their behalf.", objectives = "" }
WordHunterWoW_QuestEN[54631] = { title = "Paragon of the Voldunai", description = "Your allies among the Voldunai have requested your presence. They wish to reward you for your continued efforts on their behalf.", objectives = "" }
WordHunterWoW_QuestEN[54632] = { title = "Paragon of the Zandalari Empire", description = "The grateful leaders of the Zandalari Empire have requested your presence. They wish to reward you for your exceptional aid.", objectives = "" }
WordHunterWoW_QuestEN[54635] = { title = "Mekkatorque's Battle Plans", description = "So we almost got everythin' we need, except for where that airship went!\n\nMy insurance pals found out where they're hidin' that primo-info. \n\nGo and get me Mekkatorque's battle plans, then we can begin the REALLY fun part!", objectives = "" }
WordHunterWoW_QuestEN[54639] = { title = "A Signal in Storm Peaks", description = "It looks like the signal is being transmitted from Storm Peaks. \n\nTime to put these flying machines to work! I'll keep tracking the signal en route in order to get a cleaner read.", objectives = "" }
WordHunterWoW_QuestEN[54640] = { title = "Gnomercy!", description = "We need to give Tinkerbow some cover while she figures out our new trajectory.\n\n<The Cog Captain hands you a miniature spider tank.>\n\nIt may not look like much, but this is a fully functional spider tank. You'll just need to de-shrinkify it. Use it to distract the troggs down below by thinning their numbers.", objectives = "" }
WordHunterWoW_QuestEN[54641] = { title = "For Gnomeregan!", description = "It's time to bring down Sparkspanner, Commander.\n\nJust give me the word, and I'll turn this machine straight towards the Halls of Stone!", objectives = "" }
WordHunterWoW_QuestEN[54642] = { title = "G.E.A.R. Up", description = "That was a close one, but we managed to defeat Sparkspanner! Gnomanity and Azeroth are saved from a threat they didn't even know about.\n\nHopefully, that's the last time we'll hear from any of Thermaplugg's old goons.\n\nWe should return to Captain Sparknozzle. He will want a full report.", objectives = "" }
WordHunterWoW_QuestEN[54652] = { title = "The War Chest", description = "Welcome to the warfront, {name}. I am glad we have you fighting on our side.\n\nFirst things first: We need to collect resources in order to strengthen our hold on Bashal'Aran and bolster our troops.\n\nAny resources that we collect will go to the War Chest. Open the chest and see what you can use.", objectives = "" }
WordHunterWoW_QuestEN[54654] = { title = "An Explosive Situation", description = "We have some iron available, but we could always use more.\n\nGet down to the mine at the Ruins of Lornesta. Seize it from any enemies, and get those goblins to do their job.\n\nGiving them something suitably destructive should do the trick.", objectives = "" }
WordHunterWoW_QuestEN[54655] = { title = "Lumbering Along", description = "We will need more lumber if we're going to build up Bashal'Aran into a proper fortress.\n\nYou should find an axe in the supplies we brought in for the effort. Grab it, and see what you can do with it to help us get our base rebuilt.", objectives = "" }
WordHunterWoW_QuestEN[54656] = { title = "Darkshore Recruits", description = "We will not win unless we have the power of numbers on our side.\n\nFirst, we need the Barracks restored so Signe can do her work. Signe is one of the Dark Lady's val'kyr, and she can raise forces for us.\n\nOnce the Barracks is built, talk to Signe and recruit a troop. I'm sure they could learn a lot from fighting alongside you.", objectives = "" }
WordHunterWoW_QuestEN[54657] = { title = "Arms and Armor", description = "Keever knows troops need weapons. And armor. Armor and weapons. \n\nKeever wants Archibald to make armor and weapons for troops. You listen to Keever and talk to Archibald.", objectives = "" }
WordHunterWoW_QuestEN[54658] = { title = "The Altar of Storms", description = "The Altar of Storms has been rebuilt. It is a unique kind of altar. The goblin kind.\n\nKeever is pleased. Keever wishes to wield that kind of power.\n\nGo, listen to Keever, talk to little goblin Mizzyk and find what the Altar can do.", objectives = "" }
WordHunterWoW_QuestEN[54659] = { title = "An Alchemist for Everything", description = "When we first conquered Darkshore, we set up an Alchemy Lab on the shore at Gloomtide Strand to tap into this area's latent power.\n\nUnfortunately, things did not go so well and the Alliance have overrun the lab.\n\nWould you see them off, and then speak with Professor Blightwell to see what he can do for you?", objectives = "" }
WordHunterWoW_QuestEN[54660] = { title = "Throwing Blight", description = "We need more firepower, and the goblins are oh so obliging, aren't they. Zarvik in particular has honed his craft ever since our conquest of Darkshore.\n\nWhy don't you talk to him and see what he's got going at the Workshop?", objectives = "" }
WordHunterWoW_QuestEN[54661] = { title = "Echolocation", description = "Glad you're here! These bats have got to get up and start giving us some more air support.\n\nI've got a draft of a flight plan here in Darkshore. It's helped by the fact that our bats can see in the dark, when most of us can't.\n\nTalk to Avery and she'll make sure you get safely back to Bashal'Aran.", objectives = "" }
WordHunterWoW_QuestEN[54682] = { title = "The Missing Blade", description = "<The echo of the blade Xal'atath lingers before you. Though the consciousness that resided within the dagger is gone, the place it once occupied still resonates with power.\n\nYou sense the weapon now speaks another voice. Another purpose....\n\nYou feel compelled to warn the king that the blade may now reside in the hands of the enemy.>", objectives = "" }
WordHunterWoW_QuestEN[54683] = { title = "The Black Blade", description = "<The blade that was known as Xal'atath rests on the ground before you. Though the consciousness that resided within the dagger is gone, it still resonates with power.\n\nAlmost as if the weapon speaks with another voice. Another purpose....\n\nYou feel a compulsion to bring this artifact to the warchief.>", objectives = "" }
WordHunterWoW_QuestEN[54703] = { title = "Express Delivery", description = "The Horde appears to have misplaced some of its Azerite. It would be rude of us not to return it, don't you think?\n\nThe most efficient way is for me to teleport it back.\n\nI've enchanted the harpoons in that launcher over there. Fire them onto the Horde ships in the bay. I can use them as beacons to return the Azerite to the Horde... and send its ships on their way.", objectives = "" }
WordHunterWoW_QuestEN[54706] = { title = "Made in Kul Tiras", description = "Are you curious about how the Kul Tirans joined the Alliance? \n\nIt was assumed that Kul Tiras would rejoin the Alliance after everything that was done to stabilize their nation.\n\nLady Jaina Proudmoore wanted to cement the allegiance by building King Anduin a ship worthy of the Kul Tiran navy.\n\nShe wished for help in finding the best shipwright in Kul Tiras, Dorian Atwater. It wouldn't be easy, as Dorian was retired.\n\nIt all began with a trip to see Cyrus in Boralus Harbor...", objectives = "" }
WordHunterWoW_QuestEN[54708] = { title = "Home, Home On the Range", description = "<Cyrus peruses a map.>\n\nHmm... Along the road to Fort Daelin... to the north... somewhere in the Deadwash.\n\n<He points to a section of road on the map.>\n\nI've marked a spot on your map that seems likely. I think that will get you close enough. \n\nI'll report back to the Lord Admiral with what we've learned. Good luck, and I hope our shipwright is willing.", objectives = "" }
WordHunterWoW_QuestEN[54709] = { title = "Candy Bucket", description = "", objectives = "" }
WordHunterWoW_QuestEN[54710] = { title = "Candy Bucket", description = "", objectives = "" }
WordHunterWoW_QuestEN[54721] = { title = "I'm Too Old for This Ship", description = "If I understood this correctly, the Lord Admiral of the Kul Tiran navy wants me to come out of retirement specifically to build a ship for the king of Stormwind.\n\nCan't say I've had THAT request before.\n\n<Dorian leans back in her chair for a moment and rubs at her eyes.>\n\nI'm getting too old for this nonsense.\n\n<Dorian heaves a long sigh.>\n\nGo on out back and saddle Hurricane for me while I pack my things. We will meet you at Port Fogtide.\n\nWe're going to need a slip.", objectives = "" }
WordHunterWoW_QuestEN[54723] = { title = "Covering Our Masts", description = "When I was younger, I hid my ships out of vanity.\n\nI often went through a number of designs before I was satisfied. I didn't want anyone to see that. It might ruin the mystique, I reasoned.\n\nNow... I think it best to hide this ship from the likes of those tentacle-faced creeps. I don't think they intend to let us build unchallenged.\n\nGo into the port and place my wards around the main slip. \n\nYou'll see what they do.", objectives = "" }
WordHunterWoW_QuestEN[54725] = { title = "The Deep Ones", description = "I've spent my whole life on and around the sea. \n\nUntil very recently I feel like I've always had one foot in the water. I knew there were... things... best left untouched.\n\nNow they're here. In Stormsong Valley. Occupying the slip I need to build your ship.\n\nDo I really need to tell you what to do about it?", objectives = "" }
WordHunterWoW_QuestEN[54726] = { title = "Frame Work", description = "Now that I have a slip to work in, I'm going to need lumber.\n\nLots of lumber.\n\nThe only lumber mill that could handle this kind of volume at such short notice would be the Algerson Lumber Yard outside of Boralus.\n\nI know this because I've made this exact request of them before.\n\nI will meet you there. Algerson might need a little persuasion.", objectives = "" }
WordHunterWoW_QuestEN[54727] = { title = "Team Carry", description = "Algerson is about as useful as a legless horse. We're going to do this ourselves.\n\nThe mill is overrun with bizarre creatures. I'll handle those. You and these hearty volunteers will need to be the muscle of this operation.\n\nDon't look at me like that, {class}. It's just a little lifting.\n\nOnce we have enough lumber, Sal will meet us for a pick up. Just stay close to me and focus on not dropping my wood, yes?", objectives = "" }
WordHunterWoW_QuestEN[54728] = { title = "This Lumber is Haunted", description = "I don't much believe in ghosts, or hauntings for that matter.\n\nThat said, there is something wrong with this lumber. I can feel it in my bones. They're achier than normal.\n\nI only know of one group that would know what to do. They're reclusive, but we share a love of nature.\n\nSeek out Thornspeaker Birchgrove in Drustvar. I trust no one else with this.", objectives = "" }
WordHunterWoW_QuestEN[54729] = { title = "The Bleak Hills", description = "While you are visiting Drustvar, I need you to run another errand for me.\n\nThe Wright family owned a mine up near Corlain. Years past, they supplied all the metal ore I used to build my ships.\n\nI can't imagine they're faring too well, based on what we've seen here.\n\nFind Chelsea Wright, the foreman's daughter, and see what they need to get another ore shipment together.\n\nJust tell her Dorian sent you.", objectives = "" }
WordHunterWoW_QuestEN[54730] = { title = "Gorak Tul's Influence", description = "Long have the Thornspeakers struggled against such magics. It is a conflict as old as the Drust themselves.\n\nGorak Tul's influence, however, has vastly shifted the balance toward that of decay and death. It corrupts what would be an ordinary curse.\n\nI believe Ulfar can correct this.\n\nGo into Gol Koval. Slay our enemies, destroy their cairns, and collect their magics into this vessel.\n\nWith it, Ulfar may be able to find a way to cleanse your materials.", objectives = "" }
WordHunterWoW_QuestEN[54731] = { title = "Balance in All Things", description = "The confluence of energies around that vessel is truly disturbing. My skin crawls with the wrongness of it.\n\nWe have reached the limit of my ability to help you, {name}.\n\nGo to Ulfar, the High Thornspeaker. Arthur will carry you, if you wish it.\n\nOnly he knows enough about these ancient magics to undo the corruption that taints your materials.\n\nGo quickly. You do not want to hold that vessel longer than you must.", objectives = "" }
WordHunterWoW_QuestEN[54732] = { title = "Drop It!", description = "You must be the person Dorian sent to collect the ore.\n\nI got a message a short while ago requesting a rather large shipment, which in itself is a feat given the state of this place. I was on my way to our storehouse when that... beast!... cornered me.\n\nIt took my keys. I can't get you that shipment without them. Find out where that mongrel took them and bring them back.\n\nLet it be known I wouldn't do this for anyone else.", objectives = "" }
WordHunterWoW_QuestEN[54733] = { title = "Make it Wright", description = "<Chelsea stares in horror at the Wicker Beast.>\n\nI don't know how this happened, or why... but I know this beast. \n\n<Chelsea hastily wipes away a tear.>\n\nI've unlocked our storage chest. Thank you. Thank you so much.\n\nTell Dorian she can call upon us at any time.", objectives = "" }
WordHunterWoW_QuestEN[54734] = { title = "Summons from Dorian", description = "<The elemental has a piece of parchment whipping around madly inside its tornado.>\n\nHHsssssss.\n\n<The elemental ejects the page into your face.>\n\nHHHHSSSSSSsssshh.", objectives = "" }
WordHunterWoW_QuestEN[54735] = { title = "A Worthy Crew", description = "If Dorian really can build this ship before the day is out, we need to find a crew for the new vessel.\n\nThis crew should represent the best of Kul Tiran society, the highest naval prowess, and the faith of our people as we present this gift to Anduin.\n\nI have a captain in mind, but you'll want to speak to him yourself. I will let him decide who else he wants aboard.\n\nSeek out my brother, Tandred Proudmoore, in Boralus. He will help you fill out the ranks from there.", objectives = "" }
WordHunterWoW_QuestEN[54736] = { title = "Desecrate this Fire!", description = "", objectives = "" }
WordHunterWoW_QuestEN[54737] = { title = "Honor the Flame", description = "", objectives = "" }
WordHunterWoW_QuestEN[54739] = { title = "Desecrate this Fire!", description = "", objectives = "" }
WordHunterWoW_QuestEN[54740] = { title = "[DNT] REUSE ME", description = "", objectives = "" }
WordHunterWoW_QuestEN[54741] = { title = "Honor the Flame", description = "", objectives = "" }
WordHunterWoW_QuestEN[54742] = { title = "Desecrate this Fire!", description = "", objectives = "" }
WordHunterWoW_QuestEN[54743] = { title = "Honor the Flame", description = "", objectives = "" }
