WordHunterWoW_QuestEN[54749] = { title = "Desecrate this Fire!", description = "", objectives = "" }
WordHunterWoW_QuestEN[54750] = { title = "Honor the Flame", description = "", objectives = "" }
WordHunterWoW_QuestEN[54754] = { title = "For the Queen", description = "<You chose not to side with the traitor Saurfang and his troll lackey.\n\nNow that you know where Saurfang is, and who is with him, you should report to Sylvanas to see if she has any further orders.>", objectives = "" }
WordHunterWoW_QuestEN[54755] = { title = "Not My Table", description = "<You have decided to neither follow Zekhan to Swamp of Sorrows, nor report this event back to Sylvanas.\n\nInstead, you find yourself longing to spend a sun-soaked afternoon relaxing, and you know just the spot.\n\nSometimes, it's nice to let others take care of things.>", objectives = "" }
WordHunterWoW_QuestEN[54756] = { title = "Garbage for the Garbage God", description = "Richmon, you found a thing I been looking for for a long time. Bring it to me in the Port of Zandalar, and I will grant you my favor.", objectives = "" }
WordHunterWoW_QuestEN[54757] = { title = "The Loa of Scavengers", description = "Richmon, you bring me many shiny things. You helped some of those that no one else would. And ya dumb enough to keep comin' back to me trash piles.\n\nI like ya style.\n\nNow for da big one. Go to the steps of Dazar'alor, and find the Chronicler Ash'tari. Her chisel makes da shrines there. Tell her to build me a shrine and I will grant you my boon.\n\nUnlike the flappy Pa'ku or running Gonk, I just gonna let ya scrap your trash in my pile and I'll give ya stuff back. Anywhere my trash piles be.", objectives = "" }
WordHunterWoW_QuestEN[54759] = { title = "When Spirits Whisper", description = "Ah, {name}! I have a message for you.\n\nBaine Bloodhoof asks that you join him in Thunder Bluff at once.\n\nI suggest you hurry.", objectives = "" }
WordHunterWoW_QuestEN[54760] = { title = "The Spiritwalkers", description = "As you know, the spiritwalkers commune with our ancestors and maintain balance within the spirit realm. It is a sacred duty that links our present to our past.\n\nBut lately the spiritwalkers have been troubled by visions of chaos and turmoil. Of a rising darkness.\n\nThey tell me that the spirits have whispered your name. We are unsure why, but Spiritwalker Ussoh means to find out.\n\nSeek Ussoh on Fargaze Mesa to the south. Good luck, {name}. I believe you may need it.", objectives = "" }
WordHunterWoW_QuestEN[54761] = { title = "Spirit Guide", description = "The ancestors have whispered your name, {name}. Now it is time for you to reach out to them.\n\nHere in this sacred place, we spiritwalkers commune with those who came before us. Sit within the circle and light the incense.\n\nIf you open your heart, a spirit guide will present itself to you. Let us hope it will lead you to the answers we seek.", objectives = "" }
WordHunterWoW_QuestEN[54762] = { title = "A Small Retreat", description = "I believe your guide was delivering a warning. The unrest within the spirit realm may be even more dire than first feared.\n\nWe must cross over at once, from a place with a strong bond to the spirit realm.\n\nIn ages past, tauren made pilgrimages to Sun Rock Retreat to engage in such a ritual. It is said that long ago, An'she himself kissed the mountain where the retreat now stands.\n\nMeet me there and we will begin the crossing.", objectives = "" }
WordHunterWoW_QuestEN[54763] = { title = "Crossing Over", description = "We are ready to begin. \n\nYou will be crossing into the spirit realm. Take caution, for it can be a place of both tranquility and danger.\n\nMake contact with your spirit guide. There must be a reason it was in pain when it revealed itself to you.\n\nWhen you are ready, raise this vessel to enter the spirit realm.", objectives = "" }
WordHunterWoW_QuestEN[54764] = { title = "Storm in Bloodhoof", description = "This is worse than I feared.\n\nThe people of Bloodhoof Village are in grave danger. Even the brave young tauren who train there are woefully unprepared for the danger that is coming.\n\nDo what you can to stop this threat. I will go to Thunder Bluff to warn the High Chieftain.", objectives = "" }
WordHunterWoW_QuestEN[54765] = { title = "Thank Your Guide", description = "The balance has been restored, and Thunder Bluff is safe. Thank you.\n\nWe owe our victory to your spirit's guidance. We must honor the old ways by giving thanks to the ones who came before us.\n\nTo the southwest lies a beautiful vista where my father once took me. It would be a fitting place to reflect upon all that has transpired.\n\nPlease take this offering there to honor our ancestors.", objectives = "" }
WordHunterWoW_QuestEN[54766] = { title = "Answer the Call", description = "It is fortunate that Spiritwalker Ussoh passed along your spirit guide's warning. We were able to evacuate most of the citizens.\n\nThis cursed spirit is full of malevolence and hatred. It must be destroyed, {name}!\n\nWe attack on your command.", objectives = "" }
WordHunterWoW_QuestEN[54781] = { title = "What's For Lunch?", description = "My Shadowtrade Mercenaries will fight for Stormarion Cores, no questions asked, but they do get hungry also!\n\nFood is quite scarce here, so we need supplies!\n\nTake a mercenary out with you and find some food for them to eat. I'll make it worth your while!", objectives = "" }
WordHunterWoW_QuestEN[54787] = { title = "Masking For a Friend", description = "The Outriggers have fought some pretty tough monsters and Horde savages aren't so much different. The Blight Specialists they brought weren't especially tough, but they were the most dangerous.\n\nKill a few of them and bring back their face masks. Okri can work his mechanical wizardry and build us better masks of our own in case any Horde scum dare show their blight-spreading faces around here again.", objectives = "" }
WordHunterWoW_QuestEN[54843] = { title = "Remaining Threats", description = "Though our forces maintain a steady hold on Darkshore, this land still festers with enemies at every turn.\n\nDo what you can to keep them at bay, and you will be well rewarded.", objectives = "" }
WordHunterWoW_QuestEN[54844] = { title = "Tapping the Breach", description = "Darkshore is home to several elemental breaches which hold massive amounts of power. \n\nThe remnants of the Twilight's Hammer know this. While we were preoccupied with the Kaldorei, their elementalists have moved to exploit these locations of power, calling forth massive elementals to do their bidding.\n\nTheir actions must not go unchecked.", objectives = "" }
WordHunterWoW_QuestEN[54845] = { title = "Buzzkill", description = "Some gnome's been goin about planting these strange machines in the woods here. I don't know what they do, but I'll be dead before I let gnomish machines sully goblin territory!\n\nFind these \"buzzboxes\" and reduce them to scrap. I'll make sure you're compensated for your troubles.", objectives = "" }
WordHunterWoW_QuestEN[54850] = { title = "Operation: Troggageddon", description = "Tinkerbow has finished installing the guns on our flying machines, so it's time to give them a trial by fire. We've got confirmation that our target is in fact within the Halls of Stone.\n\nLet's start clearing out the forces out in front. We'll take the earliest opportunity to bring the fight to Sparkspanner!", objectives = "" }
WordHunterWoW_QuestEN[54851] = { title = "Blessing of the Tides", description = "Dorian certainly lives up to her reputation, {name}.\n\nThis magnificent vessel is complete and now it has a crew. Two pieces remain.\n\nFirst, we must give the ship a name.\n\nThen it falls to Brother Pike to bless this vessel. As is tradition, a tidesage's blessing fortifies the ship against storms and encourages fair weather and smooth seas. It is as much ceremonial as it is practical.\n\nOnce that is done, we will set sail for Stormwind.", objectives = "" }
WordHunterWoW_QuestEN[54871] = { title = "We Are Coming", description = "We must press our advantage before the Horde can further its hold on Darkshore.\n\nThe kaldorei stand ready to fight for our home, and the Gilneans stand alongside us.\n\nWe will show our enemies our fury. They will learn to fear us.\n\nRally any you can. We march at once.", objectives = "" }
WordHunterWoW_QuestEN[54875] = { title = "Remaining Threats", description = "We have managed to route the Horde presence in Darkshore, but several threats remain throughout the countryside.\n\nIf we wish to hold this land, they must be eliminated.", objectives = "" }
WordHunterWoW_QuestEN[54876] = { title = "Tapping the Breach", description = "We had thought the Twilight's Hammer's presence in Darkshore was snuffed out with the defeat of Deathwing. Apparently, we were mistaken.\n\nRemnants of their cult have used the conflict in Darkshore as an opportunity to re-establish their presence here. Darkshore is home to several breaches of elemental power, and it looks like they aim to use these to unleash powerful elementals to devastate the land.\n\nThis must not stand.", objectives = "" }
WordHunterWoW_QuestEN[54878] = { title = "Buzzkill", description = "Some nefarious no-goodnik is tampering with my Buzzboxes!\n\nI've been trying to get the Buzzbox network back online since we were able to drive the Horde out of Darkshore, but I'm getting no reading from boxes 456, 627, 111, and 854!  I'd be willing to bet that some stragglers from the Bilgewater Cartel are to blame!\n\nSee if you can get those Buzzboxes back online, will you? We'll need their readings if we ever want to permanently fix the corruption problem here.", objectives = "" }
WordHunterWoW_QuestEN[54913] = { title = "Spark of Genius", description = "{name}, I have wondrous news!\n\nA recent energy signature tripped several detection relays I installed after that unfortunate incident with Sargeras.\n\nI require further data to know for certain, but initial diagnostics suggest that these energies are coming from Hati! We might still be able to save him!\n\nHati's spirit is still bound to your own, so I'll need your help. Meet me at my library in the Storm Peaks right away!", objectives = "" }
WordHunterWoW_QuestEN[54915] = { title = "Telemetry Online", description = "When Titanstrike's power was expended in Silithus, Hati's essence managed to sever itself from the Thunderspark just in time to avoid destruction.\n\nThe only problem is that his essence was then scattered across Azeroth, and we don't know where.\n\nNow that we've locked onto his energy signature, we should be able to triangulate Hati's position!", objectives = "" }
WordHunterWoW_QuestEN[54916] = { title = "The Huntsman's Creed", description = "Through the glorious wonder of science, I have managed to keep the Thunderspark powered precisely for this purpose.\n\nAll you need to do is get to the Temple of Storms and absorb Hati's essence into it. Just... kind of point it in his general direction.\n\nOh, and do keep in mind that this is only one part of Hati. You may run into a few... technical difficulties before he's subdued enough for the absorption protocol.", objectives = "" }
WordHunterWoW_QuestEN[54917] = { title = "Paid in Blood", description = "If Mimiron's fancy gadgets be right, then the other half o' Hati is near the wound in Silithus.\n\nWe'll have tae move quickly. Even with part o' his essence contained, I can feel him fadin' away fast!\n\n'Tis a long trip, lad. Let's get movin'!", objectives = "" }
WordHunterWoW_QuestEN[54918] = { title = "Spark of Imagination", description = "I've diverted all non-essential power to prepare for Hati's reformation, so I cannot teleport you to Ulduar from here.\n\nBe extremely careful with the Thunderspark on your way. It is charged with highly volatile energy. One wrong bump could lead to serious complications!", objectives = "" }
WordHunterWoW_QuestEN[54919] = { title = "Bonds of Thunder", description = "While you infused Hati's essence into the Thunderspark, I have concocted a flawless plan the likes of which the scientific world has never seen!\n\nI'll spare you the technical details. Just follow my instructions and Hati will be back in one piece in no time at all!\n\n...Or we will all explode. But risks must be taken in the pursuit of knowledge and the well-being of our furry companions, wouldn't you agree?", objectives = "" }
WordHunterWoW_QuestEN[54920] = { title = "Homeward Bound", description = "The reformation procedure went positively flawlessly! Most excellent results indeed--and plenty of data to analyze!\n\nI'm not sure what it is Thorim has to show you, but I suggest you get to the Temple of Storms right away. He gets a bit destructive when he's kept waiting.\n\nTake my teleporter pad directly out of Ulduar. I'm afraid the normal route to the entrance is... inoperable at the moment.", objectives = "" }
WordHunterWoW_QuestEN[54922] = { title = "The Nuts and Bolts of It", description = "I started working on the leg gearing. Most the gearing around here is built from spare parts we find in the scrap heaps. \n\nWe're going to need a lot of spare parts to fix this thing. See what you can find.", objectives = "" }
WordHunterWoW_QuestEN[54925] = { title = "Heresy!", description = "My own prelates are among them that revolted against Talanji. This is an unspeakable heresy.\n\n I will not tolerate it! \n\n<She gestures to the prelate before her with her spear.>\n\nThis one has wisely told me who is to blame. My second, Kaj'ra.\n\nI would have heard her, had she used any other means to make her concerns known. Now she must be disposed of.\n\nYou will find her in de Terrace of de Chosen.", objectives = "" }
WordHunterWoW_QuestEN[54929] = { title = "Ready to Rumble", description = "We're going to need a new Sixteen-Servo-Actuator if we're going to fix the controls on this thing.\n\nBondo's gang at the yard probably has one, but they usually aren't too helpful.\n\nTalk to Bondo, see if you can get us one.", objectives = "" }
WordHunterWoW_QuestEN[54930] = { title = "Mechanical Liberation", description = "Since you successfully interrupted my nap, my defenses are obviously lacking to say the least. \n\nThat's because the sethrak, in addition to stealing my gadgets and gizmos, stole my mechs! Those morons don't even have the keys!\n\n<Gryzix laughs>\n\nHere, take my keys and get my mechs back.", objectives = "" }
WordHunterWoW_QuestEN[54933] = { title = "Freeing the Light", description = "Ah... you are not in league with the ogres. Please, you must aid me.\n\nI have been bound against my will by dark magic. I ask only that you free me.\n\nTake a piece of my light. Use it to dispel the shadow energies that are keeping me captive.", objectives = "" }
WordHunterWoW_QuestEN[54938] = { title = "A Brother's Help", description = "We're gonna need all the help we can get te save the planet.\n\nI've got an idea.\n\nMeet me in Nazmir, outside the Heart of Darkness. Together, we'll seek guidance from someone who may be able to help.", objectives = "" }
WordHunterWoW_QuestEN[54939] = { title = "Stubborn as a Bronzebeard", description = "It's kind o' Brann tae offer, but his flying machine would drop like a rock with me aboard. Best if it carry just the two of ye.\n\nBrann will fly ye down to Uldir. I'll find me own way and meet ye inside.", objectives = "" }
WordHunterWoW_QuestEN[54940] = { title = "Necessity is the MOTHER", description = "I may be Azeroth's speaker, but Brann's the expert on titan archaeology. If he says that MOTHER can help us save Azeroth, then I'm more than willing tae place my faith in her.\n\nCome, champion. Let's hear what guidance she has tae offer.", objectives = "" }
WordHunterWoW_QuestEN[54943] = { title = "The Dark Ranger's Pupil", description = "Thank the abyss you're here, Huntmaster {name}!\n\nI'm concerned about Dark Ranger Velonara. We have become good friends during our time together in the Trueshot Lodge, and I fear she is in peril.\n\nShe's been training an apprentice dark ranger, a lad named Prelus. Newly raised, she said. At any rate, Prelus ran off after receiving a letter from his brother, and now Velonara has gone to Tirisfal Glades to find him.\n\nI have a bad feeling about all this. Could you check on her safety?", objectives = "" }
WordHunterWoW_QuestEN[54944] = { title = "The Dark Ranger's Pupil", description = "Thank the abyss you're here, fellow hunter!\n\nI'm concerned about Dark Ranger Velonara, who frequents the Trueshot Lodge. Velonara is a good friend, and I fear she is in peril.\n\nShe's been training an apprentice dark ranger, a lad named Prelus. Newly raised, she said. At any rate, Prelus ran off after receiving a letter from his brother, and now Velonara has gone to Tirisfal Glades to find him.\n\nI have a bad feeling about all this. Would you be willing to check on her safety?", objectives = "" }
WordHunterWoW_QuestEN[54945] = { title = "Let's Get It Started", description = "I theorize this to be a communication relay. It is non-operational, but gnomish ingenuity and your strong back shall soon solve that problem!\n\nI need you to help get this device functional.", objectives = "" }
WordHunterWoW_QuestEN[54946] = { title = "Report to Gila", description = "I was quite fortunate that King Mechagon found me worthy!  \n\nI will send my assistant Gila Crosswires ahead to Boralus to gather a new team. Meet up with her and help out as you can.\n\nI will join both of you shortly.", objectives = "" }
WordHunterWoW_QuestEN[54947] = { title = "A Small Team", description = "I've determined the single attribute that is most important for a team member to survive an expedition to Mechagon.  \n\nThat attribute is...being a gnome!\n\nGather these gnomes and meet Tinkmaster Overspark and myself at the departure point.", objectives = "" }
WordHunterWoW_QuestEN[54949] = { title = "More Mouths To Feed", description = "The naga attack us relentlessly, so there is precious little time to hunt for food and supplies.\n\nYou have brought many soldiers to our camp, so we must hunt while we have the chance or we will soon run out of food.", objectives = "" }
WordHunterWoW_QuestEN[54951] = { title = "Emergency First Aid", description = "We have to patch everyone up before we can begin the search for the missing expedition.\n\nTake this first aid kit and tend to the wounded.", objectives = "" }
WordHunterWoW_QuestEN[54952] = { title = "Finding the Lost Expedition", description = "Captain Garrick went ahead to find survivors. It looks like she lit a fire.\n\nMeet her up ahead to see what she found. \n\nI'll look further within the island for survivors... and the source of the magic that attacked us.", objectives = "" }
WordHunterWoW_QuestEN[54954] = { title = "The Missing Apprentice", description = "I have been training an apprentice, a young dark ranger named Prelus. He has proven an apt pupil and a quick study. But like many of the newly raised, he feels the draw of his old life calling to him.\n\nPrelus received a letter from his brother Auron asking to meet. I advised against it, but Prelus was insistent. He is long overdue to return, and I fear for his safety.\n\nThis is the site of the rendezvous. Could you use your hunter skills to help me search for evidence of what transpired?", objectives = "" }
WordHunterWoW_QuestEN[54955] = { title = "Scarlet Recon", description = "", objectives = "" }
WordHunterWoW_QuestEN[54956] = { title = "The Grasp of Hate", description = "", objectives = "" }
WordHunterWoW_QuestEN[54957] = { title = "A Memento Given", description = "", objectives = "" }
WordHunterWoW_QuestEN[54958] = { title = "Ships in the Night", description = "Sylvanas has gone too far this time. We may be at war with the Alliance, but there are certain lines we cannot cross.\n\nI must right this situation, but I need your assistance. Derek Proudmoore is being held on the Swift Vengeance, which is moored in the harbor here for supplies. \n\nWe must take him and bring him back to his family. Are you with me?", objectives = "" }
WordHunterWoW_QuestEN[54959] = { title = "Under Lock and Keys", description = "Three keys? It seems Sylvanas didn't trust any one member of this crew to have access to Proudmoore.\n\nWe won't be able to rescue Derek Proudmoore if we can't get his cage open. \n\nWe'll need to keep an eye out for keys while we clear the ship.", objectives = "" }
WordHunterWoW_QuestEN[54960] = { title = "A Bitter Reunion", description = "We've done it! Zelling will guide the ship to Theramore, and we can put an end to this foul business once and for all.\n\nSpeak to Zelling when you are ready to leave, and we will set sail.", objectives = "" }
WordHunterWoW_QuestEN[54961] = { title = "Righting Wrongs", description = "Champion! I come with an urgent request from Baine Bloodhoof. He asks that you meet him at Plunder Harbor to help him with a... sensitive situation.\n\nYou must tell no one of this request, {class}. \n\nAncestors watch over you.", objectives = "" }
WordHunterWoW_QuestEN[54964] = { title = "A One-Way Ticket to the Heart", description = "These titan facilities never cease tae amaze me. I can only imagine how many of their secrets Brann has yet tae uncover.\n\nI just hope that one o' them holds the answer tae saving Azeroth.\n\nIt's time tae bring MOTHER tae the Chamber of Heart. Be prepared for anythin', champion. Ye can never be quite sure what will happen when ye activate a titan machine.", objectives = "" }
WordHunterWoW_QuestEN[54965] = { title = "Chopped Bots", description = "Chopping up bots is my business. Any bots you bring to my scrapper will be broken up into useful parts. It's a win for both of us!\n\nUse the Bot-Energizer to bring me dead bots, and we'll break them into spare parts.", objectives = "" }
WordHunterWoW_QuestEN[54969] = { title = "Descent", description = "We've lost the bulk of our forces already; any more and we won't have enough to make a stand.\n\nThis wreckage won't keep the naga at bay, so we must find safety elsewhere.\n\nYou will have to trust me here, {name}. Leap off the falls and you will descend safely.", objectives = "" }
WordHunterWoW_QuestEN[54972] = { title = "A Way Home", description = "We are only alive thanks to the ankoan and Azshara's desire to toy with us.\n\nWe will learn more of Okani's people in the times ahead, I am sure.\n\nFor now, we must establish a portal home. While Azshara is blocking our traditional methods of magical travel, I can sense a powerful convergence of energies nearby.\n\nI believe we can use it to open a way home.", objectives = "" }
WordHunterWoW_QuestEN[54975] = { title = "A Brief Respite", description = "We have much to do, {name}. However, we are all weary and require rest. Decisions made while fatigued are almost always the wrong ones to make.\n\nThe Ankoan have offered their home to us, yet they are barely holding on themselves. We should do what we can to support them while we think about our next move.\n\nSee what you can do to aid their hunting parties, it may be the only way we survive in this place.", objectives = "" }
WordHunterWoW_QuestEN[54976] = { title = "The Shadow of Gilneas", description = "Champion of Gilneas!\n\nI have a letter for you from Princess Tess Greymane. She requests your presence in Stormwind Keep.", objectives = "" }
WordHunterWoW_QuestEN[54977] = { title = "Into Duskwood", description = "There is a night elf I met in Teldrassil, Vassandra Stormclaw, who may be able to teach Tess without resorting to such an extreme measure. She is the one who originally helped our people with their affliction.\n\nVassandra is currently in Duskwood, assisting the residents of Raven Hill with their attempts to cure the feral worgen in the area. If anyone knows about the curse, it is her.\n\nAs a more personal request, do not let my daughter do anything too rash. She takes after her father in that way.", objectives = "" }
WordHunterWoW_QuestEN[54978] = { title = "Against Overwhelming Odds", description = "We've received numerous reports of the Horde overwhelming our forces within both Kul Tiras and Zandalar. \n\nBrute forcing the Alliance with sheer numbers is an age-old tactic of the Horde, but we can't allow them to get the upper hand.\n\nVenture forth throughout and thin their numbers the best you can. I recommend bringing reinforcements.", objectives = "" }
WordHunterWoW_QuestEN[54979] = { title = "Against Overwhelming Odds", description = "It appears we've allowed the Alliance forces to fester. If these reports are correct, they're outnumbering us in nearly every bastion we hold. \n\nArm yourself, grab a few of your most trusted allies and put them into the ground, {class}!", objectives = "" }
WordHunterWoW_QuestEN[54980] = { title = "Bane of the Nightbane", description = "Princess Greymane has informed me of the situation and I do have an idea of how to help.\n\nBut first, a favor for a favor. The residents of Duskwood have been plagued recently by a particularly ferocious member of the Nightbane pack that they call 'Bloodeyes'. Take Master Harris's sedative and bring the worgen back to me alive. She will be a perfect subject to test cures on.", objectives = "" }
WordHunterWoW_QuestEN[54981] = { title = "Cry to the Moon", description = "Duskwood has a direct connection to the Emerald Dream. Through this connection, I may be able to call forth the Ancient Goldrinn. He will be able to give the princess a taste of the curse she so dangerously chases.\n\nA rare bloom grows on the east side of the woods, gather its bloom and meet me in Twilight Grove. It will help me with this ritual.", objectives = "" }
WordHunterWoW_QuestEN[54982] = { title = "The Spirit of the Hunter", description = "The other thing I may need for this ritual are the fangs of a wolf.\n\nThere is a pack that has newly settled in around Manor Mistmantle. Bring me their fangs. I will await your return at Twilight Grove.", objectives = "" }
WordHunterWoW_QuestEN[54983] = { title = "Waking a Dreamer", description = "This should be all I need to call upon the Ancient.\n\nSome unwanted visitors may answer the call first. Protect me as I perform the ritual!", objectives = "" }
WordHunterWoW_QuestEN[54984] = { title = "Let Sleeping Wolves Lie", description = "Tess's essence now wanders a section of the Emerald Dream I have twisted into her thoughts. And I have given her my gift, but she could still use a guide.\n\nEnter the Dream through the portal behind me. It will place you near where she sleeps. See if you can help show her how rage may blind a mortal.", objectives = "" }
WordHunterWoW_QuestEN[54990] = { title = "The New Guard", description = "I need to speak with my parents again. I think my father and I have a bit to discuss.\n\nMeet me back at Stormwind Keep. I would like to thank you in a more formal manner.", objectives = "" }
WordHunterWoW_QuestEN[54992] = { title = "The Start of Something Bigger", description = "We have coordinates locked into the gyrocopters. You and Captain Winklespring will fly the lead. If we run into any trouble, Tinkmaster Overspark wants the most experienced pilots out front.\n\nBoard whenever you are ready to go.", objectives = "" }
WordHunterWoW_QuestEN[54996] = { title = "Remembrance", description = "You may remember the day Thunder Bluff was attacked. It was your efforts and your guide who saved us.\n\nNow we take time to honor our ancestors and give thanks for the path they have set for us.\n\nBring this offering to the cliffs overlooking Thunder Bluff and give thanks to your guide and all our ancestors.\n\nA simple gesture to commemorate our past. This is our way.", objectives = "" }
WordHunterWoW_QuestEN[54997] = { title = "Dead in the Water", description = "Once Proudmoore is freed, we will need to commandeer this ship to transport him to Theramore, where his sister awaits us.  \n\nZelling's magic can guide the ship there, but first we'll need to take care of the crew.", objectives = "" }
WordHunterWoW_QuestEN[54999] = { title = "Under False Colors", description = "If we wish to stay the executioner's axe, we'll need to throw Sylvanas off of our scent. I will take the ship near Chandlery Wharf, which has recently been taken by Irontide pirates. There, I will leave it under the guise of a pirate raid gone wrong.\n\nYour task will be to ensure that Sylvanas' forces find this ship.\n\nYou must report to Nathanos that you spotted a stolen Forsaken vessel in that area.  You have no connection to Derek Proudmoore, so it should raise no suspicions.", objectives = "" }
WordHunterWoW_QuestEN[55002] = { title = "Murder at the Brawlpub", description = "The Brawlpub quartermaster lies dead in front of you. He was murdered in broad daylight!\n\nHe must have been assassinated while someone was fighting in the arena. Maybe even during one of your fights.\n\nPerhaps there are some clues nearby as to who might have killed him.", objectives = "" }
WordHunterWoW_QuestEN[55003] = { title = "Put Up Your Dukes", description = "You know what?\n\n<The commander puts his notebook away.>\n\nI COULD use a good {class} on my investigations team. We've had some personnel issues lately and, frankly, I can use all the help I can get.\n\nBut first: why don't you go hop into the arena for a few fights so I can get a good look at your skills?", objectives = "" }
WordHunterWoW_QuestEN[55004] = { title = "Undercover Agent: Ann Dennyson", description = "Lord Winifred Browne is one of our primary suspects in this case. Browne is an infamously aggressive speculator, and has a list of debts a mile long.\n\nHe may be in need of money, which is consistent with the evidence you found earlier.\n\nMy associate Ann has taken point on the case. I'd like you to assist her. I think you'll work well together.", objectives = "" }
WordHunterWoW_QuestEN[55005] = { title = "The Financial Participation Incentive", description = "I see Lord Browne running some sort of game over there. Getting people to guess the fight's winner in exchange for Brawler's Gold.\n\nSee if you can figure out how his game works. If you win enough money from him, he might start talking...", objectives = "" }
WordHunterWoW_QuestEN[55006] = { title = "A Favor for Your Old Chum Winifred", description = "A moment of your time, good sir.\n\nIt's about all that money you won from me. Interestingly enough, that may have been slightly more money than I actually have, and now it would appear that some very powerful people want to break my elbows and my knees.\n\nI cannot pay them! I am quite broke! Ha ha!\n\nAll I need to get back above water is for you to lose your next fight. Flop like a fish, as they say. Please.", objectives = "" }
WordHunterWoW_QuestEN[55007] = { title = "Lord Browne's Debts", description = "I've always said that I'm not too proud to commit a few acts of violence to set a wrong right. And you know what's wrong? I'm out of money!\n\nOnly one person's won more gold from me than you have, and his name's Lord Sylysthrel. Quite the scoundrel, that one. I believe he was cheating.\n\nIt sure would be nice if I could get that gold back...", objectives = "" }
WordHunterWoW_QuestEN[55008] = { title = "Evidence Packet: Lord Winifred Browne", description = "I heard everything. That guy sure does talk loudly about his crimes and debts, doesn't he?\n\nIt sounds like we have enough to bring him in for questioning. I've put together a packet of evidence for Commander Daalo to review.\n\nGood job out there.", objectives = "" }
WordHunterWoW_QuestEN[55009] = { title = "Undercover Agent: Saralara Fizzlesprang", description = "I believe you've met one of my other agents: Saralara Fizzlesprang. She's investigating our second suspect: Shadowmaster O'Flannerty.\n\nYou'll find Saralara near the scene of the crime.", objectives = "" }
WordHunterWoW_QuestEN[55010] = { title = "Soul Splinters", description = "<O'Flannerty mumbles to himself.>\n\nAchh, what a mess... it's getting hungry again. Where am I going to find enough souls to feed it? Ohh... if only I could get my hands on some of those brawler's purses...\n\n<He notices you.>\n\nOh! Ahoy there! Pay no attention to the mindless babbling of an innocent warlock. Nothing suspicious going on here!", objectives = "" }
WordHunterWoW_QuestEN[55011] = { title = "Super Soul Splinters", description = "<O'Flannerty mutters to himself again:>\n\nWill these be big enough, though? It gets SO hungry for souls, and when it doesn't get enough, it gets angry, and we definitely don't want to trigger a void apocalypse in the middle of Stormwind. Oh dear, oh dear...\n\n<He notices you lingering.>\n\nOh! The {race} is still here! Heh heh. Never mind me! Nothing evil going on here!!", objectives = "" }
WordHunterWoW_QuestEN[55012] = { title = "Cause for Concern", description = "Shadowmaster O'Flannerty's behavior was unusual.\n\nHis repeated mutterings about \"shadow magic\" and \"void apocalypses\" and \"ancient creatures hungering for the souls of the living\" certainly warrant further investigation.\n\nYou should report back to Saralara Fizzlesprang.", objectives = "" }
WordHunterWoW_QuestEN[55013] = { title = "The Precious 13-Tooth Gogglegear", description = "We're going to have to invent something. Something capable of seeing into alternate dimensions. Something explosive that you strap directly onto your eyes.\n\nThat's right, I'm talking about goggles.\n\nI already have all the goggle parts except for one: a 13-tooth gear. They're nearly impossible to find, but I KNOW that the G.G. Engineering boys have one, and Card Trader Leila has their challenge card.", objectives = "" }
WordHunterWoW_QuestEN[55014] = { title = "The Fizzlesprang Goggle Experiment", description = "Okay, before we start, I've got a few rules:\n\nFirst, these goggles will only work at close range. We're looking for something INSIDE the arena, so you'll have to be inside the arena to use them.\n\nSecond rule: if you feel something starting to explode, try to blink real hard.\n\nLastly, remember, we're looking for an evil shadow monster. You don't need to kill it, we just need you to see it so we can report it as evidence.\n\nAlright, go get in that arena and try them out!", objectives = "" }
WordHunterWoW_QuestEN[55015] = { title = "Evidence Packet: Shadowmaster O'Flannerty", description = "Sounds like we've found our perp, {name}. This guy's sketchy, desperate, and his shadow magic is consistent with that shadowy scroll you found earlier.\n\nBring this packet to Daalo, and we can bring him in. Good work out there!", objectives = "" }
WordHunterWoW_QuestEN[55016] = { title = "Undercover Agent: Silent Jussho", description = "I've got one more suspect I'm investigating: Grant Lazarby. He's a wealthy worgen death knight socialite who spends most of his time spectating the arena from the VIP area.\n\nI've got my best agent on the case: Silent Jussho. Check in with him to see how his report is coming along.", objectives = "" }
WordHunterWoW_QuestEN[55017] = { title = "Flaunt It If You Got It", description = "Sigh... so dull...\n\nOh, it's you! {name}, was it? I've seen a few of your fights. They're slightly less tedious than the standard humdrum bloodsport this arena has been producing lately.\n\nLet's spice things up a bit. Maybe buy some expensive drinks for ourselves? Buy a round of the cheap stuff for the riffraff below? Maybe even toss a few amberseed buns at the combatants?", objectives = "" }
WordHunterWoW_QuestEN[55018] = { title = "Simply Dying of Boredom", description = "Up until now, I've been dying of boredom up here. I think maybe we need some new blood here in the arena. Bizmo can be so stingy with his invitations, can't he?\n\nI've had one of my servants write up a few slightly-counterfeit invitations to hand out. Maybe you could help me get them distributed? There's always plenty of tough-looking characters hanging out in front of the auction house in the Trade District...", objectives = "" }
WordHunterWoW_QuestEN[55019] = { title = "Evidence Packet: Grant Lazarby", description = "Good work. I never expected Lazarby to be so... self-incriminating.\n\nYou may bring the packet to Commander. I'm going to go buy some expensive snacks at the VIP bar.", objectives = "" }
WordHunterWoW_QuestEN[55020] = { title = "The Brawlpub Trial", description = "I've issued three warrants. Jussho, Saralara, and Anne are apprehending the suspects as we speak.\n\nIt's time to go to court.\n\nYou may be called on to testify. Just answer as honestly as you can, and let the wheels of justice do the rest.", objectives = "" }
WordHunterWoW_QuestEN[55021] = { title = "A Clue from Area 52", description = "We've received a letter from Area 52, the goblin outpost in Netherstorm. The author claims to know details about what they call \"the situation in the Brawlpub\".\n\nThey don't say more than that.\n\nI'm tied to my paperwork here. Go check out this lead and see if anything turns up.", objectives = "" }
WordHunterWoW_QuestEN[55022] = { title = "Solving the Mystery", description = "<Bizmo produces a challenge card from his pocket.>\n\nI grabbed this challenge card from my attackers while we were fighting each other! I'm sure that you can use it to challenge my attacker to some sort of ultimate showdown!", objectives = "" }
WordHunterWoW_QuestEN[55023] = { title = "Bizmo's Brawlpub Awaits!", description = "Tired of standing around in the boring old Trade District? Come on over to Bizmo's Brawlpub, and fight for the amusement of others!\n\nYou might win, or you might get killed, but either way, you're going to have a great time.\n\nGrab an invitation and bring it to Han Heavypaw, near the front door. The Brawlpub awaits!", objectives = "" }
WordHunterWoW_QuestEN[55028] = { title = "It's Scrap Work...", description = "{name}, I'm glad you stopped by.\n\nThe Ub3r-Spanner, capable of crafting powerful constructs, and its schematic have been lost for years. Intel tells us that its schematic is located in a locked cache in The Abandoned Junkheap.\n\nYou'll need to overcharge its electric barrier to gain access. Take my Current Culler and soak up some of the latent current from the sentries there and zap that chest open!\n\n<Layla makes finger guns and explosion sounds>\n\nUp for some treasure huntin'?", objectives = "" }
WordHunterWoW_QuestEN[55030] = { title = "Blueprint: Scrap Trap", description = "<This blueprint details how to build what appears to be some sort of land mine using little more than scrap metal.\n\nYou should be able to upload the blueprint to Pascal-K1N6's database in Rustbolt.>", objectives = "" }
WordHunterWoW_QuestEN[55031] = { title = "It's Scrap Work...", description = "{name}, I'm glad you stopped by.\n\nThe Ub3r-Spanner, capable of crafting powerful constructs, and its schematic have been lost for years. Intel tells us that its schematic is located in a locked cache in The Abandoned Junkheap.\n\nYou'll need to overcharge its electric barrier to gain access. Take my Current Culler and soak up some of the latent current from the sentries there and zap that chest open!\n\n<Shuga makes finger guns and explosion sounds>\n\nUp for some treasure huntin'?", objectives = "" }
WordHunterWoW_QuestEN[55032] = { title = "Unchained Resistance", description = "The naga have enslaved a tribe of makrura and sent them to labor as mindless thralls.\n\nThe naga forces may be more in number, but the makrura have an innate advantage in both size and strength.\n\nIf we break the makrura from their chains, they will surely overwhelm their naga overseers and put a dent in Queen Azshara's plans.", objectives = "" }
WordHunterWoW_QuestEN[55033] = { title = "Ashes to Ashvane", description = "This place is just crawling with Ashvane loyalists, {name}.\n\nHow about we do the Kul Tirans a favor and get rid of some of them.\n\n<Kelsey grins.>\n\nI got a head start on the way here, but there's plenty to go around!", objectives = "" }
WordHunterWoW_QuestEN[55034] = { title = "Under False Colors", description = "If we wish to stay the executioner's axe, we'll need to throw Sylvanas off of our scent. You'll need to have your men take the ship to Chandlery Wharf, where they can disguise it as a pirate's bounty.\n\nYour task will be to ensure that Sylvanas' forces find the ship there.\n\nYou must report to Nathanos that you spotted a stolen Forsaken vessel in that area.  You have no connection to Derek Proudmoore, so it should raise no suspicions.", objectives = "" }
WordHunterWoW_QuestEN[55036] = { title = "A Terrible Place", description = "You may have noticed all the disturbances happening around Azeroth. The Old God is rising, and its bad news for all of us.\n\nOn occasion, one of these Pillars of Endless Truth will appear. Wonderful name don't you think? I have a knack for naming things. \n\nWhere was I? Oh yes, right, these Pillars grant one access to the very mind of the Old God himself. They will show you a hint of what might yet come, what this world will look like should we fail to defeat him.\n\nAre you willing to see for yourself?", objectives = "" }
WordHunterWoW_QuestEN[55037] = { title = "Hard At Work", description = "Mementos can be used to expand your knowledge of the Visions themselves. Take a look.", objectives = "" }
WordHunterWoW_QuestEN[55039] = { title = "The Master Shipwright", description = "Now I am starting to remember...\n\nDorian Atwater was a very secretive builder. Their slips were famously warded against prying eyes until the vessel was complete. It made something of a stir any time one of their works was revealed.\n\nLast I heard, they retired in Stormsong Valley. I am not certain how reliable that information is.\n\nHm. We should head to Brennadam. It is a crossroads of sorts. If anyone knows where to find our shipwright, they will be there.", objectives = "" }
WordHunterWoW_QuestEN[55040] = { title = "Looking Inside", description = "This vault screams of ancient gnomish tech! I believe this could be the key that leads us to King Mechagon!\n\nI can't risk putting myself in danger though, so you will lead the way into the vault. \n\nWell, what are we waiting for? Let's see what's inside!", objectives = "" }
WordHunterWoW_QuestEN[55043] = { title = "Fish Tales and Distant Sails", description = "I have an idea where to start, but it couldn't hurt to ask the locals. \n\nI hope it goes without saying that you shouldn't believe everything you hear, {name}. My people are very fond of embellishing the truth.\n\nI will meet you in The Golden Flagon when you've had a chance to ask around.", objectives = "" }
WordHunterWoW_QuestEN[55044] = { title = "Don't Shoot the Messenger", description = "While he was the gladiator known as Lo'Gosh, King Varian fought beside Valeera Sanguinar. He trusted her and that allowed SI:7 to have a... cordial relationship with her. Valeera's loyalty has carried on to King Anduin.\n\nDuring the fight with the Legion, I came to know her as a capable if... independent operative. She can go where even some of my agents cannot.\n\nWe should listen to whatever message she brings. I imagine the source will be interesting.", objectives = "" }
WordHunterWoW_QuestEN[55045] = { title = "My Brother's Keeper", description = "While I trust Valeera believes she is not leading us into a trap, I do not trust this isn't a Horde manipulation.\n\n{name}, I want you to come with me. I will meet with Baine, but I will not do so alone.", objectives = "" }
WordHunterWoW_QuestEN[55047] = { title = "Securing Warfang Hold", description = "The Dark Lady has important work for you, {name}.\n\nPreparations are beginning for a meeting of the Horde's leadership at Warfang Hold. I trust I don't need to emphasize that security is of the highest import for this gathering.\n\nThe goblin, Gallywix, has sent his underlings to make sure the area is swept of any... unwanted guests. I need you to make sure they succeed in their task.", objectives = "" }
WordHunterWoW_QuestEN[55048] = { title = "Spy Games", description = "The Alliance must've got wind of this meeting and they've sent SI:7 spies to try to listen in.\n\nThe problem is, they're using some kind of gnomish tech to sneak past our detectors. One of our techs was able to put together something that should be able to neutralize whatever they're using, but the range is short. \n\nI'll need you to take it out into the field and look for evidence of SI:7 activity. Just mash the button on that thing when you think they're close, and it should zap 'em back into view.", objectives = "" }
WordHunterWoW_QuestEN[55049] = { title = "Communication Breakdown", description = "It looks like the stealth generators aren't the only tech that SI:7 is bringing into the field. Our scouts have reported what look like listening devices set up at key points around Warfang. \n\nObviously, these things have to go, but the goons haven't been able to get close to them on account of the hidden spies. \n\nWhile you're out there, make sure to trash 'em.", objectives = "" }
WordHunterWoW_QuestEN[55050] = { title = "Tickets, Please?", description = "There's another problem we could use your help with, {class}. \n\nGallywix knew this meeting was going to be a big deal, so naturally he decided to sell tickets.  The thing is, I've done a headcount here, and we've got a lot more people here than tickets sold, so some of these spectators are trying to pull a fast one.\n\nMost of our muscle is out in the Clearcut getting killed by spies, so we could use the help. Care to make an honest wage?", objectives = "" }
WordHunterWoW_QuestEN[55051] = { title = "A Display of Power", description = "It looks like all the big players are here. This thing's gonna be starting any moment now.\n\nYou'll probably want to get a good seat.", objectives = "" }
WordHunterWoW_QuestEN[55052] = { title = "Securing Warfang Hold", description = "{name}, the Dark Lady has need of your services once more.\n\nThe traitor, Baine, is being brought before the leaders of the Horde at Warfang Hold. Preparations are underway as we speak to secure the area.\n\nThe efforts are headed up by Gallywix's minions, who I wouldn't trust to secure a kennel. You will need to go to Warfang Hold and make sure the area is locked down.\n\nWe are counting on you, {name}.", objectives = "" }
WordHunterWoW_QuestEN[55053] = { title = "A Way Home", description = "We can harness the power within this place to open a portal home.\n\nI will require your assistance. Isn't this fun? You get to be my assistant!\n\nAh, yes. Just come with me and all you have to do is wave that Heart of Azeroth of yours around. I'll handle the rest.", objectives = "" }
WordHunterWoW_QuestEN[55054] = { title = "Upheaval", description = "We're surrounded by the dead, dying, and other detritus.\n\nFeels like war, does it not?\n\nOculeth and others have gone ahead to see to the soldiers.\n\nPerhaps you ought to see to them as well?", objectives = "" }
WordHunterWoW_QuestEN[55055] = { title = "Build A Bigger Fish Trap", description = "With those minnows and some spare parts, you should be able to build a Hundred-Fathom Lure.\n\nVisit Pascal-K1N6 in Rustbolt and build one.\n\nThen come back here, and we'll catch a huge fish!", objectives = "" }
WordHunterWoW_QuestEN[55056] = { title = "Blueprint: Mechanocat Laser Pointer", description = "<This blueprint details how to build what appears to be large mechanical cat, capable of bearing tremendous weight.\n\nYou should be able to upload the blueprint to Pascal-K1N6's database in Rustbolt.>", objectives = "" }
WordHunterWoW_QuestEN[55057] = { title = "Blueprint: Canned Minnows", description = "<This blueprint details how to build what appears to be a... small canning machine? How peculiar.\n\nYou should be able to upload the blueprint to Pascal-K1N6's database in Rustbolt.>", objectives = "" }
WordHunterWoW_QuestEN[55058] = { title = "Blueprint: Vaultbot Key", description = "<This blueprint details how to build what appears to be a large golden key with electricity and... explosives in it.\n\nYou should be able to upload the blueprint to Pascal-K1N6's database in Rustbolt.>", objectives = "" }
WordHunterWoW_QuestEN[55059] = { title = "Blueprint: Emergency Repair Kit", description = "<This blueprint details how to build what appears to be a repair kit for mechanical creations.\n\nYou should be able to upload the blueprint to Pascal-K1N6's database in Rustbolt.>", objectives = "" }
WordHunterWoW_QuestEN[55060] = { title = "Blueprint: Emergency Powerpack", description = "<This blueprint details how to build what appears to be a small battery pack to power mechanical creations.\n\nYou should be able to upload the blueprint to Pascal-K1N6's database in Rustbolt.>", objectives = "" }
WordHunterWoW_QuestEN[55061] = { title = "Blueprint: Mechano-Treat", description = "<This blueprint details how to build what appears to be tasty treats that small robots might enjoy.\n\nYou should be able to upload the blueprint to Pascal-K1N6's database in Rustbolt.>", objectives = "" }
WordHunterWoW_QuestEN[55062] = { title = "Blueprint: Ultrasafe Transporter: Mechagon", description = "<This blueprint details how to build what appears to be a personal teleporter of some kind.\n\nYou should be able to upload the blueprint to Pascal-K1N6's database in Rustbolt.>", objectives = "" }
WordHunterWoW_QuestEN[55063] = { title = "Blueprint: G99.99 Landshark", description = "<This blueprint details how to build what appears to be a subterranean robot shark.\n\nYou should be able to upload the blueprint to Pascal-K1N6's database in Rustbolt.>", objectives = "" }
WordHunterWoW_QuestEN[55064] = { title = "Blueprint: Rustbolt Gramophone", description = "<This blueprint details how to build what appears to be a complex device capable of playing a variety of music.\n\nYou should be able to upload the blueprint to Pascal-K1N6's database in Rustbolt.>", objectives = "" }
WordHunterWoW_QuestEN[55065] = { title = "Blueprint: Rustbolt Kegerator", description = "<This blueprint details how to build what appears to be a large, chilled container for beverages.\n\nYou should be able to upload the blueprint to Pascal-K1N6's database in Rustbolt.>", objectives = "" }
WordHunterWoW_QuestEN[55066] = { title = "Blueprint: Beastbot Powerpack", description = "<This blueprint details how to build what appears to be an oversized energy cell pack capable of powering a large Beastbot.\n\nYou should be able to upload the blueprint to Pascal-K1N6's database in Rustbolt.>", objectives = "" }
WordHunterWoW_QuestEN[55067] = { title = "Blueprint: Re-Procedurally Generated Punchcard", description = "<This blueprint details how to build what appears to be a highly adaptive punchcard template.\n\nYou should be able to upload the blueprint to Pascal-K1N6's database in Rustbolt.>", objectives = "" }
WordHunterWoW_QuestEN[55068] = { title = "Blueprint: BAWLD-371", description = "<This blueprint details how to build what appears to be a machine capable of altering the local weather systems.\n\nYou should be able to upload the blueprint to Pascal-K1N6's database in Rustbolt.>", objectives = "" }
WordHunterWoW_QuestEN[55069] = { title = "Blueprint: Protocol Transference Device", description = "<This blueprint details how to build what appears to be a device that remotely hacks and steals protocols from mechanical creations.\n\nYou should be able to upload the blueprint to Pascal-K1N6's database in Rustbolt.>", objectives = "" }
WordHunterWoW_QuestEN[55070] = { title = "Blueprint: Personal Time Displacer", description = "<This blueprint details how to build what appears to be a complex time-manipulation device.\n\nYou should be able to upload the blueprint to Pascal-K1N6's database in Rustbolt.>", objectives = "" }
WordHunterWoW_QuestEN[55071] = { title = "Blueprint: Emergency Rocket Chicken", description = "<This blueprint details how to build what appears to be an aeronautically inclined poultry unit.\n\nYou should be able to upload the blueprint to Pascal-K1N6's database in Rustbolt.>", objectives = "" }
WordHunterWoW_QuestEN[55072] = { title = "Blueprint: Battle Box", description = "<This blueprint details how to build what appears to be a cache of war supplies.\n\nYou should be able to upload the blueprint to Pascal-K1N6's database in Rustbolt.>", objectives = "" }
WordHunterWoW_QuestEN[55073] = { title = "Blueprint: Rustbolt Resistance Insignia", description = "<This blueprint details how to build what appears to be a military insignia of the Rustbolt Resistance.\n\nYou should be able to upload the blueprint to Pascal-K1N6's database in Rustbolt.>", objectives = "" }
WordHunterWoW_QuestEN[55074] = { title = "Blueprint: Rustbolt Requisitions", description = "<This blueprint details how to build what appears to be a military-grade supply cache with the Rustbolt Resistance insignia on it.\n\nYou should be able to upload the blueprint to Pascal-K1N6's database in Rustbolt.>", objectives = "" }
WordHunterWoW_QuestEN[55075] = { title = "Blueprint: Orange Spraybot", description = "<This blueprint details how to build what appears to be a small robot capable of showering an area in colored paint.\n\nYou should be able to upload the blueprint to Pascal-K1N6's database in Rustbolt.>", objectives = "" }
WordHunterWoW_QuestEN[55076] = { title = "Blueprint: Green Spraybot", description = "<This blueprint details how to build what appears to be a small robot capable of showering an area in colored paint.\n\nYou should be able to upload the blueprint to Pascal-K1N6's database in Rustbolt.>", objectives = "" }
WordHunterWoW_QuestEN[55077] = { title = "Blueprint: Blue Spraybot", description = "<This blueprint details how to build what appears to be a small robot capable of showering an area in colored paint.\n\nYou should be able to upload the blueprint to Pascal-K1N6's database in Rustbolt.>", objectives = "" }
WordHunterWoW_QuestEN[55078] = { title = "Blueprint: Utility Mechanoclaw", description = "<This blueprint details how to build what appears to be a feisty robotic hand.\n\nYou should be able to upload the blueprint to Pascal-K1N6's database in Rustbolt.>", objectives = "" }
WordHunterWoW_QuestEN[55079] = { title = "Blueprint: Microbot XD", description = "<This blueprint details how to build what appears to be an adorable miniature robot.\n\nYou should be able to upload the blueprint to Pascal-K1N6's database in Rustbolt.>", objectives = "" }
WordHunterWoW_QuestEN[55080] = { title = "Blueprint: Perfectly Timed Differential", description = "<This blueprint details how to build what appears to be an exceptionally intricate gear train.\n\nYou should be able to upload the blueprint to Pascal-K1N6's database in Rustbolt.>", objectives = "" }
WordHunterWoW_QuestEN[55081] = { title = "Blueprint: Anti-Gravity Pack", description = "<This blueprint details how to build what appears to be a kind of high-tech jetpack.\n\nYou should be able to upload the blueprint to Pascal-K1N6's database in Rustbolt.>", objectives = "" }
WordHunterWoW_QuestEN[55082] = { title = "Blueprint: Rustbolt Pocket Turret", description = "<This blueprint details how to build what appears to be a tiny flame turret.\n\nYou should be able to upload the blueprint to Pascal-K1N6's database in Rustbolt.>", objectives = "" }
WordHunterWoW_QuestEN[55083] = { title = "Blueprint: Annoy-o-Tron Gang", description = "<This blueprint details how to build what appears to be a barrel... stuffed with tiny robots?\n\nYou should be able to upload the blueprint to Pascal-K1N6's database in Rustbolt.>", objectives = "" }
WordHunterWoW_QuestEN[55084] = { title = "Blueprint: Encrypted Black Market Radio", description = "<This blueprint details how to build what appears to be a highly encrypted radio transmitter.\n\nYou should be able to upload the blueprint to Pascal-K1N6's database in Rustbolt.>", objectives = "" }
WordHunterWoW_QuestEN[55087] = { title = "The Gathering Storm", description = "While I deal with the naga incursions, Lady Proudmoore is going to take on handling the Horde in Stormsong Valley and figuring out what happened to our spies there.\n\nYou'll find her near Proudmoore Keep.", objectives = "" }
WordHunterWoW_QuestEN[55088] = { title = "Lost in the Field", description = "When Shaw and I got here we discovered most of our operatives were dead. Most, but not all. \n\nGo into the field and get any of our operatives out of there. They might have more intel on what the Horde are planning here in Warfang Hold.", objectives = "" }
WordHunterWoW_QuestEN[55089] = { title = "Shaw's Shank Redemption", description = "Hmm. Shaw said he'd check in when we got communications back but he hasn't. He's probably run into the same trouble the rest of our spies did.\n\nI'll stay here and guard the listening post. You find Shaw. He was headed for the cliff above Warfang Hold near the top of the waterfall. The peons called that area \"The Screaming Pit\" for some reason. I bet it's a real pleasant place.\n\nStab whatever he's fighting for me, okay?", objectives = "" }
WordHunterWoW_QuestEN[55090] = { title = "A Gathering of Foes", description = "Before I was distracted, I was able to find out more about this Horde gathering. Sylvanas has summoned the leaders of the Horde and its allies. For what purpose, I cannot say.\n\nWe aren't in a position to strike her down--she is too well-protected. But perhaps we can learn something that will prove useful in the ongoing war.\n\nKeep your head low and take a look. I'll keep an eye out for more guards.", objectives = "" }
WordHunterWoW_QuestEN[55092] = { title = "Disruption of Power", description = "The naga tap into the power within nearby ley lines and have found a way to harness it.\n\nDestroy their devices before they can put that power to use against us.", objectives = "" }
WordHunterWoW_QuestEN[55094] = { title = "Stay Low, Stay Fast!", description = "It's a straight shot home. We just need to be careful.\n\nNeri's rule of survival number six: always be prepared!\n\nLet's go!", objectives = "" }
WordHunterWoW_QuestEN[55095] = { title = "Upheaval", description = "So many lives lost... And the attacks from the naga are relentless!\n\nI apologize, {name}. This attitude is unbecoming of a king.\n\nWe have no time to lose musing of our own plight.\n\nLet us meet with Jaina and descend from this perilous place into the unknown.", objectives = "" }
WordHunterWoW_QuestEN[55096] = { title = "Send My Father a Message", description = "My people are once again safe... for now.\n\nKing Mechagon won't stop sending his armies at us as long as he does not fear us.\n\nWe must send him a message.\n\nClimb to the top of the ramparts, and hack one of my father's projectors to proudly shine the banner of the Rustbolt Resistance big enough for the whole island to see.\n\nI'm sure that'll attract the attention of my father, King Mechagon.", objectives = "" }
WordHunterWoW_QuestEN[55099] = { title = "TBD NOT USED", description = "The fabled workbench of Rustbolt - MY workbench - has fallen into disrepair!\n\nThis tragedy was no doubt caused by the same ruffians and miscreants who kidnapped me and Princess Wiggles.\n\nThe VERY same ruffians and miscreants, in fact, who still show their faces in this very town on the regular.\n\nTheir presence here is a veritable slap to our collective faces!\n\nDispatch the snatchers quickly and recover my binder of blueprints. We may then commence crafting what we shall need to repair this.", objectives = "" }
WordHunterWoW_QuestEN[55100] = { title = "TBD NOT USED", description = "Well, this is a fine mess!\n\nMy wondrous workbench won't be of much use until we recover those stolen blueprints.\n\nBut first thing's first, the conveyor belt must be repaired. I'll need a very specific Gizmo-matic to do it.\n\nI could craft a Gizmo-matic in my sleep... if I slept like you do, my very-susceptible-to-disease fleshy friend.\n\nBut I need material to work with.\n\nThe first lesson of junkyard tinkering: everything can be a spare part if you pummel it hard enough. Go forth and pummel!", objectives = "" }
WordHunterWoW_QuestEN[55101] = { title = "Junkyard Tinkering and You", description = "Behold, the fabled Pascal Workshop of Rustbolt -- MY workshop!\n\nCountless inventions have sprung forth into existence on this very spot, including my very finest invention, Pascal-K1N6!\n\nPascal-K1N6 can craft anything... as long as you have the blueprints for it.\n\nAnd since I have you to thank for the K1N6's safe return to Rustbolt, would you like to learn how to access his blueprints database?", objectives = "" }
WordHunterWoW_QuestEN[55103] = { title = "Ideas Can Come from Anywhere", description = "I didn't notice the tinkerer's spark in you when we first met.\n\nBut look at all of the blueprints you've recovered and uploaded to Pascal-K1N6's database.\n\nI was wrong. And happily so, my budding junkyard tinkering apprentice!\n\nBut this is a dangerous moment in your creative development.\n\nYou must avoid complacency!\n\nTake time off to find new ideas. Speak with builders that inspire you, reverse-engineer bots on the island, and be open to new ideas - no matter where they come from!", objectives = "" }
WordHunterWoW_QuestEN[55111] = { title = "Creature Study: Zanj'ir Naga", description = "<Scrawled upon the magical scroll are Maedin's incomplete notes on the Zanj'ir naga.>", objectives = "" }
WordHunterWoW_QuestEN[55116] = { title = "Getting a Clue", description = "I'm betting that one page of jibberish is a coded message. We can send it back to Stormwind to be cracked by our codebreakers or we could break some heads and find the cipher here.\n\nI'm thinking we'll just save some time and do that.\n\nThe guy in charge here probably has what we're looking for. Why don't you take him out and see if you can't find it. Even if you don't, without a leader the loyalists won't be much trouble. It's a win-win!\n\nWell, for us I guess.", objectives = "" }
WordHunterWoW_QuestEN[55117] = { title = "Correspondence Conundrum", description = "I think Ashvane has been in contact with her loyalists, but I don't know what their orders are.\n\nGo into their camp and see if you can't read their mail. We might find something that leads back to where Lady Ashvane is hiding or what their next move is going to be.", objectives = "" }
WordHunterWoW_QuestEN[55118] = { title = "Loose Ends", description = "Our campaign against the Horde is going strong, but there are some loose threads to take care of.\n\nLady Ashvane was broken out of Tol Dagor - by the Horde. We don't know where she's gone or what she is planning. I sent Kelsey out to track down some Ashvane Loyalists to get answers. She found them and has requested backup.\n\nShe's waiting for you in Freehold.", objectives = "" }
WordHunterWoW_QuestEN[55119] = { title = "Reporting In!", description = "Well it looks like Ashvane's been out of contact for some time but this 'Patron' thing could be a problem.\n\nYou did excellent work today, {name}. Those Loyalists aren't going to be thinking about causing trouble for awhile, heh.\n\nI'll make my way back. You take the letter to the High Commander.", objectives = "" }
WordHunterWoW_QuestEN[55121] = { title = "The Laboratory of Mardivas", description = "<Several pages are devoted to notes on an experiment, a hastily written journal entry follows.>\n\nAt last, my research into the base elements has begun to bear fruit!\n\nWith careful application of the right base reagents and some arcane power I've managed to combine the essence of the elements in such a way as to create life!\n\nFurther investigation will be needed to determine what the various mixes of the elements will yield.\n\n<The writing ends here.>", objectives = "" }
WordHunterWoW_QuestEN[55122] = { title = "Murloc Mania", description = "I'm glad you made it out in one piece. \n\nJudging by the nearby shipwrecks, I think it's safe to say the missing expedition ran aground here, too.\n\nWe can't move until we've got the remaining survivors back on their feet. \n\nUnfortunately, our remaining supplies have been stolen by murlocs! \n\nI need you to recover enough first aid supplies for the wounded. \n\nThen we can begin searching for the missing expedition.", objectives = "" }
WordHunterWoW_QuestEN[55124] = { title = "Righting Wrongs", description = "Champion! I come with an urgent request from Baine Bloodhoof. He asks that you meet him at Plunder Harbor to help him with a... sensitive situation.\n\nYou must tell no one of this request, {class}. \n\nAncestors watch over you.", objectives = "" }
WordHunterWoW_QuestEN[55136] = { title = "Her Dog Days Are Over", description = "<The Wicker Beast gently nudges the dog's body with its snout.\n\nThe creature whines plaintively and moves to your side.\n\nIt gives a hopeful twitch of its bony tail.>", objectives = "" }
WordHunterWoW_QuestEN[55137] = { title = "For the Horde", description = "Thank you for meeting me upon my throne, {name}.\n\nWith our recent partnerin' with de Horde, I need worthy champions to represent the might of the Zandalari. \n\nI have chosen you to be among their ranks, {name}. Go and meet with the ambassador in Orgrimmar. \n\nWe have prepared a portal just behind you. When you are ready, step through to a new world.\n\nRemember, you bow only to the throne of Zandalar. Hold your head high, {name}.", objectives = "" }
WordHunterWoW_QuestEN[55138] = { title = "Stranger in a Strange Land", description = "Hi. I'm Ambassador Blackguard.\n\nI am honored to welcome you to Orgrimmar, {race}.\n\n<He smiles unconvincingly.>\n\nAs a lifetime of adventure unfolds before you, be assured that... uh...\n\nYou know what? I've been saying this same greeting all day. Enough's enough.\n\nTalk to Chromie on top of the hourglass, then talk to your emissary. Run along.", objectives = "" }
WordHunterWoW_QuestEN[55142] = { title = "For the Alliance", description = "Thank you for meeting with me, {name}.\n\nI need representatives to go to Stormwind to represent our loyalty and commitment to our newly forged bond with the Alliance. \n\nI've had Yvia and her magi prepare a portal to the city for you in the Sanctum of the Sages. Once there, go to the Stormwind Embassy and meet with Ambassador Moorgard.\n\nYou will face many challenges on the long journey ahead. Remember where you came from and make your people proud!", objectives = "" }
WordHunterWoW_QuestEN[55146] = { title = "Stranger in a Strange Land", description = "Welcome to Stormwind, {race}. I invite you to explore our fair city. Since you hail from Kul Tiras, might I suggest visiting our lovely docks? They are home to our majestic fleet. I would be shocked if you were not impressed!\n\nAh, but that can wait, a bronze dragon has asked to talk to you. She is sitting under the nearby tree, on an hourglass of all things!\n\nAfter that, an emissary of Kul Tiras is waiting to welcome you to the city. Sounds like a busy day for you!\n\nHave a pleasant stay.", objectives = "" }
WordHunterWoW_QuestEN[55153] = { title = "Collaborative Construction", description = "Construction projects can be found all over the island. You'll be able to build some of 'em yourself, but you're gonna need help with the bigger projects.\n\nAsk around and see what others are already working on, or just head out on your own and find a project you're interested in.\n\nConstruction projects move around and even change day-to-day, so keep an eye out for new ones while you're exploring.\n\nIf you're ever curious what construction projects are available on a given day, just ask me!", objectives = "" }
WordHunterWoW_QuestEN[55171] = { title = "Spy Versus Spy", description = "Naga attacks are on the rise, but that isn't all we have to deal with. We've received word of increased Horde activity near Warfang Hold in Stormsong Valley.\n\nSend some of our operatives to investigate what they are doing.", objectives = "" }
WordHunterWoW_QuestEN[55173] = { title = "Northbound", description = "The quilboar kidnapped the rest of the expedition and took them to the north.\n\nI heard mention of needing more sacrifices for some sort of ritual...\n\nPlease, you must rescue them!", objectives = "" }
WordHunterWoW_QuestEN[55174] = { title = "Cooking Meat", description = "Alaria is nearly starved to death. We need to get her something to eat!\n\nSlay some of the nearby wildlife for their meat. Bring whatever you find here to cook.\n\nIf we can help Alaria regain her strength, she might be able to tell us what happened to the others.\n\nI'll stay here and help stabilize her wounds.", objectives = "" }
WordHunterWoW_QuestEN[55175] = { title = "Where the Road Leads", description = "My people know many secrets about this place. If you prove yourselves worthy allies, you will be privy to them.\n\nFirst, we must regroup in Mezzamere. There, we at least have a foothold against the tide.", objectives = "" }
WordHunterWoW_QuestEN[55177] = { title = "Tearing at the Seams", description = "I feel odd... weak. As though something is affecting my very existence.\n\nWould you come with me, {name}? I may need your help. At the very least, you could be a witness to whatever happens should something dire occur.", objectives = "" }
WordHunterWoW_QuestEN[55179] = { title = "Retaliation Coordination", description = "Master Shaw deployed a number of Alliance spies near a base the Horde have made in Stormsong Valley. When our spies stopped checking in, he took Kelsey Steelspark and went to investigate. \n\nNow Master Shaw is the one who hasn't checked in.\n\nI need someone to go in and find our missing people and give them whatever help they clearly need.", objectives = "" }
WordHunterWoW_QuestEN[55182] = { title = "Reassembly Required", description = "Master Shaw wanted me to rebuild the listening posts the Horde destroyed when they started to clear the area in preparation for whatever they are planning.\n\nI managed to salvage most of the parts for one, but I'm missing a few.\n\nFortunately for us, I've been watching the workers and they've been picking up the pieces of the destroyed machines. Go get our tech back and I can take care of the rest.", objectives = "" }
WordHunterWoW_QuestEN[55183] = { title = "Seeking Higher Ground", description = "We've only got one shot at reestablishing our communication network, so we've got to pick the right spot and I found just the right place! \n\nWhile you've been busy down here, I set up some camouflage and hauled the bulk of the machinery up there.\n\nWhat? Did you think I was just sitting here polishing my knives while you were gone?\n\nWell, okay I did that too. Anyway, I'll meet you up the hill!", objectives = "" }
WordHunterWoW_QuestEN[55184] = { title = "Quilboar Shadow Magic", description = "Quilboar are primitive and savage. They rarely practice any magic other than geomancy.\n\nBut these particular quilboar seem to be dabbling in shadow magic. They must be stopped.\n\nSlay the quilboar in the den. They cannot spread this magic in the island!", objectives = "" }
WordHunterWoW_QuestEN[55185] = { title = "Listen Up!", description = "Okay! Once we get this up and running we should be able to send messages! In the valley at least.\n\nIt's gonna be a little bit tricky, but I've read the manual for these things cover to cover.\n\n<Kelsey slaps the top of the listening device.>\n\nI'm gonna put this thing back together. You watch out for the Horde.", objectives = "" }
WordHunterWoW_QuestEN[55186] = { title = "Down with the Quilboar", description = "From what I can gather, the quilboar are performing a shadow ritual on one of the expedition members.\n\nTheir chief is Geolord Grek'og. He is the one who seeks to drain the life from our friend.\n\nSlay Grek'og and save the captive member of the expedition. He may know where the others were taken.", objectives = "" }
WordHunterWoW_QuestEN[55188] = { title = "Tearing at the Seams", description = "I feel odd... weak. As though something is affecting my very existence.\n\nWould you come with me, {name}? I may need your help. At the very least, you could be a witness to whatever happens should something dire occur.", objectives = "" }
WordHunterWoW_QuestEN[55193] = { title = "The Scout-o-Matic 5000", description = "You look like a {race} that needs help finding the scattered members of our alliance expedition!\n\nLuckily, you have happened to rescue the one and only Lindie Springstock, inventor extraordinaire! \n\nI've got my Scout-o-Matic 5000 all set to go. It'll fly up in the air and let you scout the entire area.\n\nI'll give you the honors. Use my Scout-o-Matic 5000 to find the rest of the expedition.", objectives = "" }
WordHunterWoW_QuestEN[55194] = { title = "Stocking Up on Supplies", description = "Quartermaster Richter was able to scavenge supplies from the wreckages on this island.\n\nWhy don't you visit her and see if she has anything that you need?\n\nYou'll want to be well equipped for whatever we encounter next.", objectives = "" }
WordHunterWoW_QuestEN[55195] = { title = "Reverberation", description = "Hati's spirit is bound to yours forevermore, hunter. But it also now carries a link to the Temple of Storms--as well as Silithus, I fear.\n\nThe Thunderspark shares these same bonds. By physically linking it here, you can call upon the different aspects of Hati's spirit and bind them to yourself as well.\n\nDo not worry. Skoll and I will guard the Thunderspark with our very lives! It will be safe.", objectives = "" }
WordHunterWoW_QuestEN[55196] = { title = "The Harpy Problem", description = "We need to find the remaining survivors of my expedition before the ogres sacrifice them for their dark ritual!\n\nI saw one of the survivors being dragged away by some harpies. They have a roost to the north.\n\nKee-La and I will meet you up there with a scouting report.", objectives = "" }
WordHunterWoW_QuestEN[55210] = { title = "Batteries Not Included", description = "You will not be sorry that you rescued my dear sister and me, {name}.\n\nWe are the vanguard of a new technological revolution, creating opportunities for all to enhance their lives with incredible technology!\n\nBut, before we can do that, we need our laboratory to be fully powered. Those ruffians from Mechagon really did a number on our equipment.\n\nFully charged energy cells are exceptionally rare around here, but I can make do with broken ones.\n\nCheck around town, in the wreckage from the last attack.", objectives = "" }
WordHunterWoW_QuestEN[55211] = { title = "Recharging Rustbolt", description = "Our personal generator is worthless until we recharge its empty energy cells.\n\nAs my dear brother says, energy cells are the lifeblood of innovation. Everything in Mechagon needs power, and energy cells deliver that power in a wonderfully universal format.\n\nBut, once they're drained of power, most people toss the empty cells away.\n\nMost people are fools, dear test subject.\n\nWe have perfected the technology to recharge small numbers of energy cells back to full power.\n\nWill you help us test it?", objectives = "" }
WordHunterWoW_QuestEN[55213] = { title = "Energy Cells for Everyone", description = "The wondrous scuttlebutt around town is that the charging station in Bondo's Yard is going to be repaired today!\n\nThat charging station is the best way to recharge all the Empty Energy Cells that've been piling up in your bag. Or in other people's bag. Or inside the mechanical innards of robots you don't own but are legally allowed to destroy.\n\nAfter you've acquired Empty Energy Cells, help build the charging station in Bondo's Yard and charge all of your Empty Energy Cells!", objectives = "" }
WordHunterWoW_QuestEN[55214] = { title = "Seam Stress", description = "I...I need a moment, {name}.\n\n<Delormi seems disoriented and grabs your shoulder for support. She presses her hand against her forehead and stands there for a minute. \n\nFinally shaking off whatever she was feeling, she stands up straight and faces you.>\n\nThere are gaps in my memories. Things important to me, lost now. We must stop her at all costs, {name}.", objectives = "" }
WordHunterWoW_QuestEN[55216] = { title = "The Audition", description = "Xanjo has spoken highly of your skills, but I need to be certain of what you can do. I mean no offense, this is as much for your benefit as it is our own, as if you are not ready the task could kill you.\n\nIf you are willing, I would like to provide you with a test to see how well you can work leather.\n\nBring me three Drums of the Maelstrom that you have crafted yourself. This will prove your skill and consistency.\n\nIf your work is up to par, I will inform you of my plan.", objectives = "" }
WordHunterWoW_QuestEN[55217] = { title = "Repaying the Life Debt", description = "When I heard that the Alliance attacked Dazar'alor, I couldn't help but think of those lost when they attacked Camp Taurajo. No longer can I sit idly while they continue to slaughter us!\n\nI need you to go to Thunder Bluff, find Sheza Wildmane on the Elder Rise, and ask for some of her personal collection.\n\nI won't go into detail, but she owes me a life debt, and seeing her would... bring back too many painful memories... for both of us.\n\nFind her, tell her I sent you, and that this absolves her debt.", objectives = "" }
WordHunterWoW_QuestEN[55218] = { title = "Sheza's Prized Leather", description = "I have a stash of extremely rare leathers, or... rather, I did.\n\nI don't know how, but the Venture Company must have heard how valuable my collection was because they stole it!\n\nAnd THEN they had the audacity to leave a note offering to sell it back to me for 1,000 gold! As the \"former owner\", I'm able to \"best appreciate the value of their new acquisition.\"\n\nThe note states they'll be in the bluffs to the East until someone buys them.\n\nHowever you get the skins, consider them yours.", objectives = "" }
WordHunterWoW_QuestEN[55219] = { title = "Dropping by the Base", description = "When the Legion was attacking, I met with a member of the Highmountain Tauren who had a knack for making and playing drums.\n\nTorv usually keeps to himself, but he is as brilliant as he is insane.\n\nIf there is anyone who would know where we could get the raw materials for something of this magnitude, it would be him.\n\nHead to Thunder Totem, and ask Torv Dubstomp if he can think of a suitable source of scales. Preferably something still living, so its power is still fresh.", objectives = "" }
WordHunterWoW_QuestEN[55220] = { title = "Bass Fishing", description = "Have you heard of people taking small golden carp as pets?\n\nWell, if it is kept in a pond free of predators, over time it can grow enormous, only limited by the food present.\n\nCenturies ago, one of these fish lived in the pond atop a mountain. It ate everything and began to starve, so my people dug a river that connected the pond to the ocean so the fish could be free.\n\nNow, fishermen talk of being attacked by an enormous golden fish in the Rockaway Shelf.\n\nKill it. Take his scales back to Atikka.", objectives = "" }
WordHunterWoW_QuestEN[55221] = { title = "Picking Bones", description = "When I was sailing in, I noticed the remains of an unbelievably large beast on the nearby peninsula.\n\nWhatever it was, it must have been strong, making it the perfect source for the bone elements of the drums.\n\nGo to the peninsula, 'Xibala' I've heard it called, and fill a bag with the bones you find.\n\nIf you come across any of those damned Alliance, show them no mercy. They did this to themselves.", objectives = "" }
WordHunterWoW_QuestEN[55222] = { title = "Make Some Noise", description = "We have everything we need to craft the drum, except the Earth Mother's blessing. \n\nThe drum is but a vessel, like a cup. We need her to imbue the drum with power, filling the cup so that we may drink.\n\nIt will not be easy to convince her to assist us in creating a weapon of war, but I will implore her to protect her children.\n\nWhile I'm doing that, you will need to craft the drum itself.\n\nNot too big, though. The larger the vessel, the more power it can hold, but the harder it becomes to carry.", objectives = "" }
WordHunterWoW_QuestEN[55223] = { title = "Instruments of Destruction", description = "Our work is almost finished.\n\nThese drums, while powerful, are practically useless here in port.\n\nIf you want to get the most benefit from them, you'll need to spread them out. I'd suggest one for each territory here and in Kul Tiras, to help you when you are on a quest and to keep you at your strongest when you're behind enemy lines.\n\nLook for someplace centralized in each territory to place drums.\n\nOnce you return, I'll show you how to make the mallet needed to utilize the drums.", objectives = "" }
WordHunterWoW_QuestEN[55224] = { title = "Rank 2 - Poen test", description = "Gather corrupted ink sacs from the Nazothian Brain squids. \n\nThe naga use them to control us, let's see if it works the other way.", objectives = "" }
WordHunterWoW_QuestEN[55225] = { title = "Special Juices", description = "", objectives = "" }
WordHunterWoW_QuestEN[55226] = { title = "Drive the Enemy", description = "", objectives = "" }
WordHunterWoW_QuestEN[55227] = { title = "The Aeonian Artisan", description = "Good day, friend!\n\nA Night Elf woman stopped by and asked who was the best leatherworker I knew who didn't mind getting their hands dirty.\n\nI gave her your name, and she asked me to ask you to find her in Boralus Harbor.\n\nShe didn't say what she needed my best student for, but the way she acted makes me think that it is for something big.\n\nHead on down to the docks and look for her. She has white hair, purple tattoos, and a pet turtle named \"Gouge\". Show her what I've taught you!", objectives = "" }
WordHunterWoW_QuestEN[55228] = { title = "The Audition", description = "Cassandra has spoken highly of your skills, but I need to be certain of what you can do. I mean no offense, this is as much for your benefit as it is our own, as if you are not ready the task could kill you.\n\nIf you are willing, I would like provide you with a test to see how well you can work leather.\n\nBring me three Drums of the Maelstrom that you have crafted yourself. This will prove your skill and consistency.\n\nIf your work is up to par, I will inform you of my plan.", objectives = "" }
WordHunterWoW_QuestEN[55229] = { title = "Repaying the Debt", description = "I was in Teldrassil when it was set alight. Through the panic and chaos, I knew I could not rest as long as those who did this were unpunished.\n\nI need you to go to Stormwind, find Telonis near the Lion's Rest, and ask for some of his personal collection.\n\nI managed to save him from the fires, so he owes me a great deal. I would go myself, but the loss of Teldrassil is still a fresh wound. I still need to give it time to heal.\n\nFind him, tell him I sent you, and that this will absolve his debt to me.", objectives = "" }
WordHunterWoW_QuestEN[55230] = { title = "Telonis' Prized Leather", description = "I have a stash of extremely rare leathers, or... rather, I did.\n\nA group of thieves must have heard how valuable my collection was because they stole it!\n\nAnd THEN they had the audacity to leave a note offering to sell it back to me! As the \"former owner\", I'm able to \"best appreciate the value of their new acquisition.\"\n\nThe note states they'll be waiting in the foothills behind the castle, to the east, until they find another buyer.\n\nHowever you get the skins, consider them yours.", objectives = "" }
WordHunterWoW_QuestEN[55231] = { title = "The Other Ghostdancer", description = "When the Legion was attacking, my partner went to Val'sharah to fight the demons.\n\nMevris may be cold and headstrong, but he's goal oriented, and willing to sacrifice to achieve them. That's part of why I fell in love with him.\n\nIf there is anyone who would know where we could get the raw materials for something of this magnitude, it would be him.\n\nHead to Val'sharah, and look for him in the Temple of Elune. Tell him of our plan, and that we need his help securing scales.", objectives = "" }
WordHunterWoW_QuestEN[55232] = { title = "Mevris' Menace", description = "There is a hydra that has been something of a nuisance for us as of late. It lives out on the Gloaming Reef, almost directly due west of here.\n\nIt's been attacking ships that pass by, making it difficult to get supplies to and from Bradensbrook.\n\nI sent a team to handle it, but they haven't returned.\n\nGo out there, kill it, and take its scales to Daniss.\n\nAnd when you see her, tell her that I said...\n\n<Mevris pauses as he thinks of his words, and the meaning they carry.>\n\nNothing.", objectives = "" }
WordHunterWoW_QuestEN[55233] = { title = "Picking Bones", description = "When I was sailing in, I heard some of the sailors talking about the Horde presence here in Tiragarde Sound.\n\nApparently they're scrounging around the remains of a massive creature that has washed ashore.\n\nWhatever it was, if the Horde wants it, we need to make sure they don't get it.\n\nFind the Horde, keep them from taking anything, and see if there are any bones from the creature we can use for our drums.\n\nShow them no mercy, {name}.", objectives = "" }
WordHunterWoW_QuestEN[55234] = { title = "Make Some Noise", description = "We have everything we need to craft the drum, except Elune's blessing. \n\nThe drum is but a vessel, like a cup. We need her to imbue the drum with power, filling the cup so that we may drink.\n\nWith Tyrande donning the mantle of the Night Warrior, much of Elune's power is taxed. Asking for another favor is not insignificant, but I must try.\n\nWhile I'm doing that, I need you to craft the drum. Try to keep it small. The larger the vessel, the more power it can hold, but the harder it becomes to move.", objectives = "" }
WordHunterWoW_QuestEN[55235] = { title = "Instruments of Destruction", description = "There is one last thing we need to do.\n\nThese drums, while powerful, are practically useless here in town.\n\nIf you want to get the most benefit from them, you'll need to spread them out. I'd suggest one for each territory here and in Zandalar, to help you when you are on a quest and to keep you at your strongest when you're behind enemy lines.\n\nLook for someplace centralized in each territory to place drums.\n\nOnce you return, I'll show you how to make the mallet needed to utilize the drums.", objectives = "" }
WordHunterWoW_QuestEN[55243] = { title = "A Daughter of Torcali", description = "It has long been remarked upon that a direhorn is de bravest beast in de jungle. That is why they are chosen as mounts for our warriors.\n\nIn this case, that bravery may not be in your favor. De little one has run off and I do not think she is hungry this time.\n\nBest find her before she gets hurt.", objectives = "" }
WordHunterWoW_QuestEN[55244] = { title = "Away From the Herd", description = "<The Child of Torcali stares longingly out of her pen. Her gaze seems to be following the other nearby direhorns.\n\nPerhaps she could use a distraction.>", objectives = "" }
WordHunterWoW_QuestEN[55245] = { title = "Eat Like a Direhorn", description = "<The Child of Torcali investigates your hands for traces of food and makes a small sound of distress.>", objectives = "" }
WordHunterWoW_QuestEN[55246] = { title = "Even Greener Pastures", description = "Ever since Torcali gave her boon to de little one, she has been growing like a weed. Dat makes her very hungry.\n\nShe got out again to look for more things to eat. Before you ask, it is not my role to stop her from doing what she wants. Only to ensure she is safe.\n\nShe is probably fine. Bring her home, and if you have trouble bringing her home, you might try a bribe.", objectives = "" }
WordHunterWoW_QuestEN[55247] = { title = "The Trust You've Earned", description = "I believe my loa will agree with me when I say that you have proven yourself worthy of this one's companionship.\n\nShe is large enough now that she can bear you wherever it is that you wish to go.\n\nI had de Beastlord craft a saddle for you. Go and get it and I will help you put it on your new steed's back.\n\nCongratulations, {name}.", objectives = "" }
WordHunterWoW_QuestEN[55248] = { title = "Greener Pastures", description = "You have done an adequate job keeping de little one fed, but sometimes they just want something else.\n\nI did not see where de hatchling went, but you should start where de grass is real green. You will likely find her eating it.\n\nIf you have trouble bringing her home, you might try a bribe.", objectives = "" }
WordHunterWoW_QuestEN[55249] = { title = "Away From the Herd", description = "<The Child of Torcali stares longingly out of her pen. Her gaze seems to be following the other nearby direhorns.\n\nPerhaps she could use a distraction.>", objectives = "" }
WordHunterWoW_QuestEN[55250] = { title = "A Growing Appetite", description = "<The Child of Torcali investigates your hands for traces of food and makes a small sound of distress.>", objectives = "" }
WordHunterWoW_QuestEN[55251] = { title = "A Daughter of Torcali", description = "It has long been remarked upon that a direhorn is de bravest beast in de jungle. That is why they are chosen as mounts for our warriors.\n\nIn this case, that bravery may not be in your favor. De little one has run off and I do not think she is hungry this time.\n\nBest find her before she gets hurt.", objectives = "" }
WordHunterWoW_QuestEN[55252] = { title = "A Loa Without a Temple", description = "I have given some thought about your situation, {name}.\n\nIt is not your fault dat de goblin deceived us. I followed along with his scheme as well. From today, you have my forgiveness. \n\nBut dat cannot help de little one. I fear we may lose it, if we do not act. We must ask de wanderer's loa, de mountain dat moves, de great bulwark, de greatmother of direhorns, to save her child.\n\nTake dis offering to her shrine and ask for her boon... and her forgiveness.", objectives = "" }
WordHunterWoW_QuestEN[55253] = { title = "A Show of Faith", description = "<Torcali's voice enters your mind.>\n\nI have watched your efforts from afar, small thing. You have made mistakes, and one of my young has suffered for it.\n\nI do not forget, but I can forgive.\n\n<The enormous direhorn touches the offering bundle with her nose.>\n\nAs my people place faith in me, I place my faith in you. Take my blessing to my child and she will wake.", objectives = "" }
WordHunterWoW_QuestEN[55254] = { title = "An Unending Sleep", description = "<The direhorn hatchling continues to sleep soundly, despite any efforts on your part to wake it.\n\nIt's probably been too long. You should speak to Beastlord L'kala.>", objectives = "" }
WordHunterWoW_QuestEN[55258] = { title = "Sleep, Eat, Repeat", description = "<The Child of Torcali pushes the sack of herbs around with her snout.\n\nShe then looks to you and stomps eagerly in place.>", objectives = "" }
WordHunterWoW_QuestEN[55298] = { title = "Fishing For Something Bigger", description = "There's a huge fish lurking these waters, and it's been causing lots of problems! \n\nIt eats other fish, fishermen, and a lot of expensive gear. I saw it swallow a beautiful Zigby 300 Fishing Rod along with its owner just the other day!\n\nI've got a plan, but I've lost a lot of my equipment in the waters around here. Can you help fish up some of these items for me?", objectives = "" }
WordHunterWoW_QuestEN[55299] = { title = "Bottom Feeding Stinkfish", description = "<Danielle Anglers may be interested in this fish.>", objectives = "" }
WordHunterWoW_QuestEN[55305] = { title = "Bolted Steelhead", description = "<Danielle Anglers may be interested in this fish.>", objectives = "" }
WordHunterWoW_QuestEN[55306] = { title = "Pond Hopping Springfish", description = "<Danielle Anglers may be interested in this fish.>", objectives = "" }
WordHunterWoW_QuestEN[55307] = { title = "Shadowy Cave Eel", description = "<Danielle Anglers may be interested in this fish.>", objectives = "" }
WordHunterWoW_QuestEN[55308] = { title = "Mechanical Blowfish", description = "<Danielle Anglers may be interested in this fish.>", objectives = "" }
WordHunterWoW_QuestEN[55309] = { title = "Spitting Clownfish", description = "<Danielle Anglers may be interested in this fish.>", objectives = "" }
WordHunterWoW_QuestEN[55310] = { title = "Sludge-fouled Carp", description = "<Danielle Anglers may be interested in this fish.>", objectives = "" }
WordHunterWoW_QuestEN[55311] = { title = "Energized Lightning Cod", description = "<Danielle Anglers may be interested in this fish.>", objectives = "" }
WordHunterWoW_QuestEN[55312] = { title = "Solarsprocket Barbel", description = "<Danielle Anglers may be interested in this fish.>", objectives = "" }
WordHunterWoW_QuestEN[55313] = { title = "Tasty Steelfin", description = "<Danielle Anglers may be interested in this fish.>", objectives = "" }
WordHunterWoW_QuestEN[55319] = { title = "Tonk the Terrible", description = "<This TK looks like it could be a good racer in the Roadrash Race.\n\nCrash Wheeler at the Roadrash Racetrack has the final say on what's allowed, though.>", objectives = "" }
WordHunterWoW_QuestEN[55320] = { title = "Vehicle: TK02[DNT]", description = "<This TK[DNT] looks like it could be a good racer in the Roadrash Race.\n\nCrash Wheeler at the Roadrash Racetrack has the final say on what's allowed, though.>", objectives = "" }
