WordHunterWoW_QuestEN[55339] = { title = "Tidying Up", description = "Ionized Minnows are a scourge of these waters. They strip the ocean floors of any food, making it difficult for other species to survive.\n\nThese fish have little to offer other than being a food source for larger fish. I want to see these larger fish, so I have a plan to clear the waters of these minnows and lure the bigger fish out from its hiding place.\n\nLet's start by using my Minnow Vac to catch Ionized Minnows for me.", objectives = "" }
WordHunterWoW_QuestEN[55345] = { title = "The Dark Ranger's Pupil", description = "Thank the abyss you're here, champion!\n\nI am Moorgoth, tracker of fearsome foes in dark places. Anyone in the Trueshot Lodge will vouch for my credentials.\n\nDark Ranger Velonara and I are good friends, and I fear she is in peril.\n\nShe's been training an apprentice dark ranger. Newly raised, she said. At any rate, her pupil ran off after receiving a letter from his brother, and now Velonara has gone to Tirisfal Glades to find him.\n\nI have a bad feeling about all this. Could you check on her safety?", objectives = "" }
WordHunterWoW_QuestEN[55346] = { title = "The Dark Ranger's Pupil", description = "I am Moorgoth, hunter of fearsome foes and hero of the Trueshot Lodge.\n\nYou are a renowned champion of the Alliance, but I've been told you save those in peril. Please hear me out.\n\nI am friends with a ranger named Velonara. She serves the Horde, but I assure you she is a noble soul.\n\nShe's been training an apprentice ranger who disappeared after receiving a letter from his brother. Velonara has gone to Tirisfal Glades to find him.\n\nI have a bad feeling about this. Would you check on her safety?", objectives = "" }
WordHunterWoW_QuestEN[55351] = { title = "The Missing Apprentice", description = "I have been training an apprentice, a young dark ranger named Prelus. He has proven an apt pupil and a quick study. But like many of the newly raised, he feels the draw of his old life calling to him.\n\nPrelus received a letter from his brother Auron asking to meet. I advised against it, but Prelus was insistent. He is long overdue to return, and I fear for his safety.\n\nThis is the location of the rendezvous. Could you help me search for evidence of what transpired? This flare gun may reveal the truth.", objectives = "" }
WordHunterWoW_QuestEN[55361] = { title = "The Lost Shaman", description = "Pardon me, {class}. I am in need of your assistance.\n\nOur shaman, Farseer Ori, left the camp some days ago to investigate a nearby disturbance in the elements. He took his apprentice with him, a young initiate named Odari. Neither have returned.\n\nI am leading an expedition to find them and return them here safely. Nazjatar is full of dangers. The skills of an accomplished {class} like yourself could prove most useful.\n\nWill you help me return the lost shaman to safety?", objectives = "" }
WordHunterWoW_QuestEN[55362] = { title = "Elemental Fury", description = "The naga have angered the elements and disrupted the natural order. We must restore the balance before it is too late.\n\nA Farseer maintains a deep connection with the elements. When the naga forces imprisoned my master, the natural balance was disturbed.\n\nTake the Stone of Elements and use it to pacify the enraged water elementals throughout Dragon's Teeth Basin.\n\nUltimately, our only solution is to rescue Farseer Ori and bring him back alive, but the Tidestone could buy us precious time...", objectives = "" }
WordHunterWoW_QuestEN[55363] = { title = "Rescue The Farseer", description = "My master, Farseer Ori, has been imprisoned by the forces of Queen Azshara.\n\nFarseer Ori was captured while performing a sacred ritual to call upon the elements for guidance. I managed to escape, but the ritual has been left unfinished.\n\nIf we do not rescue my master soon, the elements will grow even more restless.\n\nThe elemental balance must be maintained. I fear what may become of my clan and our bond with the elements if Farseer Ori is not returned to us.", objectives = "" }
WordHunterWoW_QuestEN[55373] = { title = "Knock 'Em Out The Box", description = "Steelarm Pillagers have been taking all our parts and selling them to Bondo's gang.\n\nLast night they stole all our Spiderspring Gears. The parts are in a bunch of crates they're guarding.\n\nWe need you to get our gears back, and show those Steelarm Pillagers they should pick on someone else.", objectives = "" }
WordHunterWoW_QuestEN[55374] = { title = "A Disturbance Beneath the Earth", description = "Manifestation of dragon essence detected. Location: Highmountain. \n\nAssuming successful retrieval, calculations indicate 92.7 percent probability of empowering Heart of Azeroth.\n\nTheory: By combining dragon essence with sufficient quantities of Azerite within Heart Forge, previously undiscovered abilities may manifest within Heart.\n\nAs Speaker Magni would say: \"Get to work, champion.\"", objectives = "" }
WordHunterWoW_QuestEN[55378] = { title = "Rustbolt Requisitions: Shimmerscale", description = "I've received an urgent request from Tinkmaster Overspark.\n\nThese supplies are needed!", objectives = "" }
WordHunterWoW_QuestEN[55379] = { title = "Rustbolt Requisitions: Star Moss", description = "I've received an urgent request from Tinkmaster Overspark.\n\nThese supplies are needed!", objectives = "" }
WordHunterWoW_QuestEN[55380] = { title = "Rustbolt Requisitions: Storm Silver Ore", description = "I've received an urgent request from Tinkmaster Overspark.\n\nThese supplies are needed!", objectives = "" }
WordHunterWoW_QuestEN[55381] = { title = "Rustbolt Requisitions: Storm Silver Ore", description = "Gazlowe's orders are in: He wants these supplies ASAP.\n\nYa got the goods?", objectives = "" }
WordHunterWoW_QuestEN[55382] = { title = "Rustbolt Requisitions: Shimmerscale", description = "Gazlowe's orders are in: He wants these supplies ASAP.\n\nYa got the goods?", objectives = "" }
WordHunterWoW_QuestEN[55383] = { title = "Rustbolt Requisitions: Star Moss", description = "Gazlowe's orders are in: He wants these supplies ASAP.\n\nYa got the goods?", objectives = "" }
WordHunterWoW_QuestEN[55384] = { title = "Settling In", description = "Whatever Azshara is up to, this *ahem* great new landscape we have found ourself in is terribly inconvenient. \n\nToo many getting too close to our home. We have moved most of the refugees deeper into the cave.\n\nCould you ask Telur to move our calling conch inside? \n\nGrab some of Slen's Elixir and check in with Vim.\n\nOnce it is set up, test it out! \n\nI'm off to do a progress check!", objectives = "" }
WordHunterWoW_QuestEN[55385] = { title = "Scouting the Pens", description = "Some of our scouts have not returned.\n\nThey have been keeping an eye on the Zanj'ir Slave Pens. \n\nThe naga there take our people. They break their minds. Our scouts watch them, and when there is a window, they rescue them.\n\nSomething is going on. We need to get them home!", objectives = "" }
WordHunterWoW_QuestEN[55390] = { title = "In Darkness, I Dream", description = "The green dragonflight calls for aid. The Emerald Dream, which they have watched over for eons, has been invaded by terrible creatures of the Void.\n\nMerithra of the Dream is attempting to combat the threat, but she cannot do so alone. If you seek to empower the Heart of Azeroth with the strength of the green dragonflight, you must first help Merithra save it.\n\nMeet her at the Temple of Elune in Val'sharah, and assist her however you can.", objectives = "" }
WordHunterWoW_QuestEN[55392] = { title = "Enter the Dreamway", description = "We have little time, so I will be brief.\n\nThe Emerald Dream is under attack. The shadows of the Void are on the rise, and not even the Dream is beyond their reach. Many of my kin have already been slain, and still more are at risk.\n\nWe must enter the Dreamway and save what remains of my dragonflight before it is too late.", objectives = "" }
WordHunterWoW_QuestEN[55393] = { title = "Null the Void", description = "The green dragonflight cannot stop this tide of Void creatures on our own. Not with our reduced strength.\n\nPlease, lend us your might and drive them from the Dreamway before they can enter the waking realm.", objectives = "" }
WordHunterWoW_QuestEN[55394] = { title = "Shards of Emerald", description = "Kalecgos tells me that you seek the power of the dragonflights in its most essential form. There may be something here that can help you.\n\nFragments of our latent power have coalesced here in the Dream.\n\nThey are scattered about the Dreamway, where my kin have fallen. Within the Dream, you should be able to wield those fragments in their raw state.", objectives = "" }
WordHunterWoW_QuestEN[55395] = { title = "Don't Close Your Eyes", description = "The Void assaults us as we sleep! Those who it ensnares may never wake again.\n\nThey can only be roused by powerful magic native to our dragonflight. The shards that have formed near our fallen kin may be exactly what is needed.\n\nIf we succumb to slumber in the Void, we will be lost forever. Please, aid us!", objectives = "" }
WordHunterWoW_QuestEN[55396] = { title = "The Stuff Dreams Are Made Of", description = "All that remains is to throw the emerald fragments you collected into the lake. I will use my power to bind them together.\n\nIf this works, they will be reforged into a powerful dragonscale that you can use to empower the Heart of Azeroth.\n\nI believe that my mother would be pleased that some of our power will go toward saving the world. I hope she would be proud of us.", objectives = "" }
WordHunterWoW_QuestEN[55397] = { title = "Before I Wake", description = "It is as I feared. We cannot fuse the shards together until the Void has been driven from this place.\n\nQuickly, strike down these aberrations. I suspect the source of the corruption will not sit idle in response.", objectives = "" }
WordHunterWoW_QuestEN[55398] = { title = "The Long Awake", description = "There is nothing more you can do for us here, champion. You have the power you sought, and the Emerald Dream is fighting back against the Void.\n\nBring this dragonscale back to Magni and the others. I will meet you in the Chamber of Heart to help infuse it into the Heart of Azeroth.\n\nAs for my flight, our long vigil must continue... or we will be lost to the Void.", objectives = "" }
WordHunterWoW_QuestEN[55400] = { title = "Take My Hand", description = "Beneath us lies the former home of the dragon Neltharion. You may know him as Deathwing. \n\nIf your titan watcher friend detected an essence of dragon magic coalescing nearby, it may be an echo of the power of the dragonflights. Such power will be coveted by others as well.\n\nThis force is likely originating from the most potent area within the lair--the decaying bones of my kin slain in the throes of Deathwing's fury.\n\nWe must go before the essence falls into the wrong hands.", objectives = "" }
WordHunterWoW_QuestEN[55407] = { title = "Calming the Spine", description = "It is plain that the situation here is dire.\n\nThe power of the black dragonflight echoes around us, and the earth is reeling in response. \n\nI have heard tales of ruptures like these on Kul Tiras and Zandalar. The elementals have been driven into a frenzy, and they bar our way from seeking the essence.\n\nIf we are to preserve the tenuous balance of the elements here, the wounds must be mended, {name}.", objectives = "" }
WordHunterWoW_QuestEN[55424] = { title = "Aspirant Elynna", description = "{name}! You've returned to the Maw! Glory be with you!\n\nI have news. It seems that one of the aspirants lost in the attack on Honorveil is being held here, in the Jailor's Armory. Her name is Elynna, and she's on the tenth floor.\n\nThat's all I know for now. We shall speak again when I know more.", objectives = "" }
WordHunterWoW_QuestEN[55425] = { title = "Dominating the Indomitable", description = "With the wounds healed, I can clearly sense the dragon essence. Unfortunately, it seems to emanate from the earthen giant before us.\n\nI will address the creature. Let us hope it listens to reason... but be prepared for anything.\n\nWhen Deathwing shattered the World Pillar in Deepholm, he earned the ire of the Stonemother and her forces. I fear this being may blame me for my father's crimes.", objectives = "" }
WordHunterWoW_QuestEN[55426] = { title = "What Will It Grow?", description = "<The small seed is starting to sprout. Perhaps there's a place nearby that it could be planted.>", objectives = "" }
WordHunterWoW_QuestEN[55451] = { title = "Paint Vial: Fireball Red", description = "<Marvelous Martini could make use of this item.>", objectives = "" }
WordHunterWoW_QuestEN[55452] = { title = "Paint Vial: Fel Mint Green", description = "<Marvelous Martini could make use of this item.>", objectives = "" }
WordHunterWoW_QuestEN[55454] = { title = "Paint Vial: Lemonade Steel", description = "<Marvelous Martini could make use of this item.>", objectives = "" }
WordHunterWoW_QuestEN[55455] = { title = "Paint Vial: Mechagon Gold", description = "<Marvelous Martini could make use of this item.>", objectives = "" }
WordHunterWoW_QuestEN[55456] = { title = "Paint Vial: Copper Trim", description = "<Marvelous Martini could make use of this item.>", objectives = "" }
WordHunterWoW_QuestEN[55457] = { title = "Paint Vial: Overload Orange", description = "<Marvelous Martini could make use of this item.>", objectives = "" }
WordHunterWoW_QuestEN[55462] = { title = "The Wanderer's Call", description = "Greetings, small thing.\n\nDe Great Wanderer asked this one to collect you. She has a task for you and de little beast to complete.\n\nJo'nok's loa is patient, but he would not keep her waiting.", objectives = "" }
WordHunterWoW_QuestEN[55463] = { title = "Aid From Nordrassil", description = "Look at what they've done to this island, {name}.\n\nNature is nearly extinguished, its death cry falling on the deaf ears of mechagnomes.\n\nBut I have heard the teeny tiny animals of Mechagon, and bring aid from afar!\n\nIt won't be easy to restore balance to a land so severely wounded. Nature's scars run deep here.\n\nThankfully, we are not alone. I've brought living sap from Nordrassil, the World Tree of Mount Hyjal. Use it to regrow the forests and speed nature's recovery in this land.", objectives = "" }
WordHunterWoW_QuestEN[55465] = { title = "We Must Go Deeper", description = "These shards can only do so much in their current state. They are broken and scattered... not unlike my kin.\n\nWe must bring them together.\n\nLet us go deeper into the Emerald Dream. I know of a place where we can reforge the shards into a dragonscale. With it, you can empower the Heart of Azeroth with the essence of my dragonflight. We must go to the ancient heart of the Dream, where my mother once rested.\n\nSpeak with me when you are ready to delve deeper.", objectives = "" }
WordHunterWoW_QuestEN[55469] = { title = "To Zin-Azshari", description = "We need something to deal with the guardian of the Tidestone, {name}.\n\nOur new allies here say that there is a naga enclave located in the ruins of Zin-Azshari. If there is anything potent enough to counter Azshara's sorcery, it will be in the ruins of her capital city.\n\nThe First Arcanist will accompany you, champion. She will be best equipped to assist you in matters both historical and magical while you search.\n\nGood luck.", objectives = "" }
WordHunterWoW_QuestEN[55481] = { title = "Scouting the Palace", description = "We cannot hide here forever, {name}. We have to deal with Azshara.\n\nWe will need to assault her palace but we do not know what defenses she has in place. I dispatched a scouting team while you were gone and they have not reported back.\n\nI cannot afford to lose any more people. Speak with Spiritwalker Ussoh. His abilities will let us see where the scouts are.", objectives = "" }
WordHunterWoW_QuestEN[55482] = { title = "Making the Connection", description = "A communication crystal! Have they survived this long?\n\nWe used to use these to communicate. They allowed us to project images of ourselves to other nearby crystals to see and speak with those on the other end.\n\n<Thalyssra examines the crystal for a few moments.>\n\nThe magic has long since depleted from the crystal. We will need a power source, preferably something just as old as this.\n\nCheck our surroundings, but be careful. It is too quiet out here....", objectives = "" }
WordHunterWoW_QuestEN[55483] = { title = "[PH] Stop Rituals", description = "", objectives = "" }
WordHunterWoW_QuestEN[55484] = { title = "[PH] Collect Cleansing Motes", description = "", objectives = "" }
WordHunterWoW_QuestEN[55485] = { title = "Terrors in the Deep", description = "Azshara knows we are here. Still, we must press on.\n\nBe careful, though. There is a... wrongness coming from the water. It is unlike the magic of old, but more ancient and terrible.\n\nTraverse the canals and find the source of corruption. If we are to search Zin-Azshari, we cannot let any relics fall into the hands of even darker powers.", objectives = "" }
WordHunterWoW_QuestEN[55486] = { title = "Secrets of Telemancy", description = "The nightborne are no strangers to this place. It was once our capital too, long ago.\n\nBefore the Sundering and erecting the shield over Suramar we used to travel freely to Zin-Azshari. Oculeth had a workshop in these estates. \n\nPerhaps it might contain some secrets or magic that went undisturbed by the survivors.", objectives = "" }
WordHunterWoW_QuestEN[55487] = { title = "[PH] Warding Scrolls", description = "", objectives = "" }
WordHunterWoW_QuestEN[55488] = { title = "Speak with the Dead", description = "So many souls perished beneath the waves. Too many sacrificed for her ambition.\n\nIt is strange that the spirits here have not departed. I wonder if they even know they are dead?\n\nStill, their knowledge might be useful to us. If you could question the spirits, they might be able to point us in the right direction.", objectives = "" }
WordHunterWoW_QuestEN[55489] = { title = "The Handmaiden's Tale", description = "The Javelins of Suramar!\n\nWielded by Azshara herself, they contain immense magical power. She has always had a fondness for bestowing favors on her favorites, but I never suspected she would give one something so valuable as one of her Javelins. This foe must be formidable indeed.\n\nNevertheless, {name}, we cannot let this opportunity pass us. Defeat the handmaiden and retrieve the relic!", objectives = "" }
WordHunterWoW_QuestEN[55490] = { title = "We'll Poke Their Eye Out", description = "The Javelins were some of Suramar's finest creations before the Sundering. Their magic is ancient and potent. Perhaps strong enough to defeat Azshara's wards.\n\nHurry back to Newhome. We must tell the others of our success here. You have done well.", objectives = "" }
WordHunterWoW_QuestEN[55497] = { title = "A Friendly Face", description = "An essence of black dragonflight magic is not to be trifled with, {name}.\n\nMy flight has been the pawn of dark forces in the past. I owe it to my fallen kin to see that our power is never used for evil again.\n\nI would like to journey with you and meet your allies. Perhaps my knowledge can help you use this essence to defend our world.", objectives = "" }
WordHunterWoW_QuestEN[55498] = { title = "The Shimmering Crystal", description = "Though the crystal appears familiar at first, upon contact with your finger it reveals itself as so much more. A grand, lost civilization appears in front of you. Fixtures of gold shimmer in every direction, bright feathers of purple occasionally falling from overhead. You hear the distant sounds of battle, culminating in a thunderous explosion that overwhelms all of your senses and turns your vision white.\n\nWhen your vision returns, you feel something within you pulling you toward Ashran.", objectives = "" }
WordHunterWoW_QuestEN[55499] = { title = "The Shimmering Crystal", description = "Though the crystal appears familiar at first, upon contact with your finger it reveals itself as so much more. A grand, lost civilization appears in front of you. Fixtures of gold shimmer in every direction, bright feathers of purple occasionally falling from overhead. You hear the distant sounds of battle, culminating in a thunderous explosion that overwhelms all of your senses and turns your vision white.\n\nWhen your vision returns, you feel something within you pulling you toward Ashran.", objectives = "" }
WordHunterWoW_QuestEN[55500] = { title = "Save A Friend", description = "In the cave ahead is where they are holding Mak. \n\nThey torture us. They break us. \n\nDon't let them take her, too.", objectives = "" }
WordHunterWoW_QuestEN[55503] = { title = "The Direhorn and the Saurid", description = "<A gentle voice enters your mind.>\n\nI am pleased with your efforts. He will not soon forget the kindness you have shown him, and so he will not soon forget me.\n\nNow your journey will take you south. I can no longer sense one of my wayshrines. If you can determine what has happened to it and restore it, I would be grateful.", objectives = "" }
WordHunterWoW_QuestEN[55504] = { title = "Wayshrines of Zuldazar", description = "<A calm but thunderous voice enters your mind.>\n\nMy child grows under your care. I am pleased. Now, I would have your aid.\n\nThere was a time long ago when the roads of Zandalar were under my protection. Those who walked them gave praise, and in return I gave them my blessing. Fewer wander now.\n\nMy shrines remain, their purpose forgotten. You will help me to restore them.\n\nBegin in the north. See to the wayshrine there. If you find any lost travelers, see that they know my blessing through you.", objectives = "" }
WordHunterWoW_QuestEN[55505] = { title = "Roo'li's Memory", description = "I was going to be a Dinomancer. Roo'li was going to grow with me as I learned.\n\n<Koo'li shakes her head.>\n\nDat future is gone now. Please, take him. Find a proper place to bury him.\n\nI... can't. De shame is too great.", objectives = "" }
WordHunterWoW_QuestEN[55506] = { title = "One Road Ends", description = "<A warm voice enters your mind.>\n\nThere is one more wayshrine in this region that requires your attention.\n\nFollow this road until you near its end at the Port of Zandalar.\n\nIt is there, at the start and end of so many journeys, that one of my most trafficked shrines was established. Restore it and see that any weary travelers have my blessing.\n\nWe will speak again when you are finished.", objectives = "" }
WordHunterWoW_QuestEN[55507] = { title = "Torcali's Blessing", description = "<Torcali's voice enters your mind.>\n\nYour actions speak to your intentions, {name}.\n\nI can see that my child will have the care she needs to grow strong, and grow she will. \n\nIn the coming days she will recover the strength that would have been hers, if nature had been allowed to take its course. Tend to her, earn her loyalty, and I will allow you to keep her at your side.\n\nThis is my gift to you.\n\nYou may go now. She will bring you to me when it is time.", objectives = "" }
WordHunterWoW_QuestEN[55508] = { title = "Victory in Wintergrasp", description = "Commander Zanneth might be satisfied with a pile of Horde corpses at his feet, but controlling Wintergrasp is of the utmost importance to the Valiance Expedition. Make sure it remains in our control.\n\nHowever, don't think we'll just let you stand around while your allies do your dirty work for you. If you're not at least a second level recruit by the end of the battle, don't come back.", objectives = "" }
WordHunterWoW_QuestEN[55509] = { title = "Victory in Wintergrasp", description = "While Dardosh might be content with slaying our foes, it is of the utmost importance that we control Wintergrasp Fortress. Do whatever it takes to ensure Wintergrasp is ours.\n\nHowever, don't think we'll just let you stand around while your allies do your dirty work for you. If you're not at least a second level recruit by the end of the battle, don't come back.", objectives = "" }
WordHunterWoW_QuestEN[55510] = { title = "No Mercy for the Merciless", description = "Welcome to Wintergrasp, {name}. Your mission is simple. Defeat ten of the Horde's finest. Now, go! Bring victory to the Alliance!", objectives = "" }
WordHunterWoW_QuestEN[55511] = { title = "Slay them all!", description = "Welcome to the Wintergrasp, {name}. Warlord Garrosh demands one thing: Slay them all!\n\nReturn to me when ten of the strongest members of the Alliance are dead.", objectives = "" }
WordHunterWoW_QuestEN[55516] = { title = "Spark of Genius", description = "{name}, I require your assistance.\n\nA recent energy signature tripped several detection relays I installed after that unfortunate incident with Sargeras.\n\nInitial diagnostics suggest that these energies emanate from Hati, a legendary creature of lightning magic. This wolf was linked to the Titanstrike artifact, a weapon that proved instrumental in defeating the Legion!\n\nHati's spirit is still bound to Titanstrike's core, so I'll need your help. Meet me at my library in the Storm Peaks right away!", objectives = "" }
WordHunterWoW_QuestEN[55517] = { title = "Paint Vial: Big-ol Bronze", description = "<Marvelous Martini could make use of this item.>", objectives = "" }
WordHunterWoW_QuestEN[55519] = { title = "A Fresh Trauma", description = "Azeroth is strugglin' tae survive, but new wounds are formin' at a rapid pace.\n\nI can sense her cries o' pain risin' from the north... in a place o' ancient power...\n\n<Magni closes his eyes, as if listening to an unseen voice.>\n\nBy the Forge! Somethin's gone wrong in Mount Hyjal. The World Tree, Nordrassil, is in danger!\n\nMeet me there, {name}. There's no time tae lose!", objectives = "" }
WordHunterWoW_QuestEN[55520] = { title = "Healing Nordrassil", description = "Azerite elementals are runnin' wild, driven mad by Azeroth's pain. They're menacin' the spirits o' nature that protect the World Tree.\n\nThe roots o' Nordrassil run deep, nurtured by these sacred waters. For the sake o' Azeroth's world soul, the tree must be defended.\n\nQuiet the restless elementals and use yer Heart o' Azeroth tae mend the wounds ye find. We cannae let Hyjal become another gapin' scar like Silithus!", objectives = "" }
WordHunterWoW_QuestEN[55521] = { title = "Do It the Azerite Way", description = "Incredible! Ye stopped the wound from spreadin' before it could get out o' control!\n\nNordrassil should be safe again, fer now. This is a good sign that we may just be able tae reverse all the damage done tae Azeroth.\n\nLet's get back tae the Chamber o' Heart, an' see if we can put any o' that azerite ye absorbed tae good use.", objectives = "" }
WordHunterWoW_QuestEN[55522] = { title = "Return to the Heart", description = "Greetings, Champion of Azeroth.\n\nMOTHER's been monitorin' yer progress with the Heart of Azeroth, and is mighty pleased with the work you've done tae make it stronger.\n\nAt least, we think she's pleased. It's difficult tae tell at times.\n\nRegardless, come back tae the Chamber of Heart when ye've got a chance. There's more that needs doin'.", objectives = "" }
WordHunterWoW_QuestEN[55523] = { title = "Bring Him Some...", description = "<Mrrl points at your backpack then draws some pictures in the sand. He pulls out a pretty object from behind a rock then furiously points to himself then back at you then your bag.\n\nYou believe it might want to make a trade.>", objectives = "" }
WordHunterWoW_QuestEN[55524] = { title = "Bring Him Some...", description = "<Mrrl points at your backpack then draws some pictures in the sand. He pulls out a pretty object from behind a rock then furiously points to himself then back at you then your bag.\n\nYou believe it might want to make a trade.>", objectives = "" }
WordHunterWoW_QuestEN[55525] = { title = "Bring Him Some...", description = "<Mrrl points at your backpack then draws some pictures in the sand. He pulls out a pretty object from behind a rock then furiously points to himself then back at you then your bag.\n\nYou believe it might want to make a trade.>", objectives = "" }
WordHunterWoW_QuestEN[55526] = { title = "Bring Him Some...", description = "<Mrrl points at your backpack then draws some pictures in the sand. He pulls out a pretty object from behind a rock then furiously points to himself then back at you then your bag.\n\nYou believe it might want to make a trade.>", objectives = "" }
WordHunterWoW_QuestEN[55527] = { title = "Bring Him Some...", description = "<Mrrl points at your backpack then draws some pictures in the sand. He pulls out a pretty object from behind a rock then furiously points to himself then back at you then your bag.\n\nYou believe it might want to make a trade.>", objectives = "" }
WordHunterWoW_QuestEN[55528] = { title = "Playtime's Over", description = "The troggs have been raiding our supplies since we got here, but now that we got some fire power you're going to put a stop to that!\n\nLet's teach them troggs to stay away from our stuff!", objectives = "" }
WordHunterWoW_QuestEN[55529] = { title = "No Backs", description = "<The murloc seems hungry. Next to it is a series of crude drawings which seems like a shopping list. Perhaps you can help the creature.>", objectives = "" }
WordHunterWoW_QuestEN[55530] = { title = "A Safer Place", description = "<The murloc seems to be in rough shape. Perhaps it would be safer with your allies in Newhome.>", objectives = "" }
WordHunterWoW_QuestEN[55531] = { title = "What Will It Mine?", description = "<Although worn from repeated use, the pickaxe still seems salvageable. Perhaps there's something nearby that can be mined?>", objectives = "" }
WordHunterWoW_QuestEN[55533] = { title = "MOTHER Knows Best", description = "Now that this chamber's not fallin' tae pieces anymore, we can focus on makin' the Heart stronger!\n\nMOTHER says she's finished her fancy calculations. Have a word with her, champion. See if we can further empower the amazin' gift Azeroth gave ye.", objectives = "" }
WordHunterWoW_QuestEN[55534] = { title = "Rustbolt Gramophone", description = "<The large gramophone that you crafted is capable of blasting music across all of Rustbolt.\n\nNow, you just need to find a good place to install it.>", objectives = "" }
WordHunterWoW_QuestEN[55535] = { title = "The Tipsy Tinkerer", description = "The massive kegerator that you built should be able to house all of the Rustbolt Resistance's beverages.\n\nFind a spot to set it up in Rustbolt, and let the town know it's ready for use!", objectives = "" }
WordHunterWoW_QuestEN[55558] = { title = "A Bolt Hole", description = "{name}, we must seek out a powerful weapon to combat the naga who guard the Tidal Conflux. I am certain such an object would be in the hands of one of Azshara's minions.\n\nThanks to our new allies, we've tracked down the location of one of her handmaidens within the ruins of Zin-Azshari. The journey will be quite dangerous. Thankfully our allies have a location nearby that we can use as a staging ground.\n\nI've marked the location on your map, meet with me there as soon as you can.", objectives = "" }
WordHunterWoW_QuestEN[55560] = { title = "Utama's Vengeance", description = "We Ankoan are a small tribe. There are not that many of us remaining.\n\nThis place was once overrun with makrura, before Utama. They tried to hide here, from the naga, but found the makrura. They fell, in battle, to the Kil'karrok.\n\nIf you wish to show your dedication to the Ankoan, become a force of vengeance in Utama's memory. Destroy the makrura.", objectives = "" }
WordHunterWoW_QuestEN[55561] = { title = "What Remains of Zin-Azshari", description = "Zin-Azshari, once the capital of night elf civilization, was lost during the Sundering. Queen Azshara betrayed her people and allowed N'Zoth to corrupt them, turning them into naga.\n\nIt has now fallen into ruin and chaos.\n\nWe must see what it has become. Meet me by the statue of Azshara.", objectives = "" }
WordHunterWoW_QuestEN[55565] = { title = "Shoring Up Mana Reserves", description = "Holding back the tide walls is not an easy task, even using the Tidestone. The ebb and flow of the magical energies in the area are too inconsistent.\n\nWe need to shore up our magical reserves, which requires mana batteries, if you will. The befouled elementals along the canal here are created with exactly the elemental cores we need.\n\nThe goal is two fold. Clearing out the befouled elementals, before their corruption spreads, but also retrieving their cores, so we can keep the water at bay.", objectives = "" }
WordHunterWoW_QuestEN[55569] = { title = "Echoes of Pain", description = "These spirits... they are the Highborne. They were those Azshara held close. Azshara often played favorites, but these people... they were her favorites.\n\nI do not know why their spirits are here. We should investigate further. See if you can communicate with them and find out why their spirits cling to these ruins.\n\nHow could she abandon them?", objectives = "" }
WordHunterWoW_QuestEN[55570] = { title = "Secrets in the Ruins", description = "This was once a place of great power. The highborne who lived here would host lavish parties, living in splendor.\n\nZin-Azshari was once on the shores of the Well of Eternity and drew powerful mages from all over the empire to study here. I suspect, despite the many years at the bottom of the sea, there are still treasures and powerful artifacts hidden away here.\n\nSpeak with the spirits that remain and see what you can find. There must be something to help us overcome the Guardian of the Tidestone.", objectives = "" }
WordHunterWoW_QuestEN[55571] = { title = "Help Them See the Truth", description = "The information you have gleaned concerns me, {name}. These spirits cling to this place because they still, even now, believe in Azshara and her reign. She sold their lives to the void and they still believe in her.\n\nI know we have concerns that outweigh this, but I cannot leave them here like this.\n\nShow them. Confront them and tell them of Azshara's betrayal.", objectives = "" }
WordHunterWoW_QuestEN[55573] = { title = "Purging the Defilers", description = "Azshara always did need everything to be about her. Everything had to have her name on it. Everything was for her glory. She forgot our people's connection to Elune. Or perhaps she believed it did not matter?\n\nAzshara and her minions have too long defiled this place with their heresy.\n\nLet us show them Elune's vengeance.", objectives = "" }
WordHunterWoW_QuestEN[55574] = { title = "The Javelins of Azshara", description = "These spirits keep speaking of the Javelins of Azshara. At first, I believed it to be referring to the handmaidens, who are currently holed up in Elun'alor.\n\nBut -- now I think they are referring to the Javelins of Suramar. They were powerful weapons -- long thought lost. Azshara does like to claim things as her own.\n\nWe need to defeat her handmaiden in Elun'alor regardless. Seizing the Javelins would be an amazing stroke of fortune.", objectives = "" }
WordHunterWoW_QuestEN[55575] = { title = "One Gnome's Trash", description = "The garbage in these trash heaps is full of rare metals: Dalaranium, Suramarite, even Gnomeisium! \n\nI've not seen this much easy gold to be had, since they left the vault door open in Boralus! You help me collect some of the metal, and my friend Gao will sell it on the black market.\n\nI've got a device that can tear the metal right out of the trash!", objectives = "" }
WordHunterWoW_QuestEN[55578] = { title = "Tol Dagor: Jewel of the Tides", description = "<As you peer at the shrine in front of you, you can't help but revel at the construction of it.\n\nSeamlessly constructed with azure jewels placed just so in a radial pattern, collapsing towards a single point.\n\nA single, empty point. An absence you assume to be a mistake. Quickly surveying the area for something that might fit there, you find nothing.\n\nHowever, there appears to be a drunk here shouting at the shrine. Perhaps he might know the whereabouts of the shrine's missing piece.>", objectives = "" }
WordHunterWoW_QuestEN[55579] = { title = "Cracking the Surface", description = "<Upon your investigation you discover that the shrine has a couple locations where jewels appeared to have been located, but no longer exist.\n\nAdditionally, the center jewel appears to have several cracks in it as well.\n\nChecking your notes, the earthen mentions having prospected the jewels from a nearby mountain to the northwest.\n\nPerhaps you can prospect the earth in that area to find more of those jewels.>", objectives = "" }
WordHunterWoW_QuestEN[55580] = { title = "High Prospects", description = "<Inspecting the shrine, you realize that several of the gems embedded on its surface are cracked and need to be replaced.\n\nChecking your notes, you find that the earthen had extracted the gems from some earth elementals to the south.\n\nLooking at your map, you wonder if he was referring to the now ruins of a once ancient settlement that has become littered with constructs and undead.\n\nPerhaps investigating there will yield some clues as to where to find these jewels.>", objectives = "" }
WordHunterWoW_QuestEN[55581] = { title = "Sun-Speckled Dunes", description = "<Surveying the shrine, you believe that the sandy winds in this area have worn down the embedded gems, producing odd shapes and cracks in some.\n\nLooking at your notes, the earthen mentions coming across dunes sprinkled with orange gems. He said it reminded him of the soft sunlight in this area.\n\nChecking your notes, it appears that these dunes were located south of your current location.>", objectives = "" }
WordHunterWoW_QuestEN[55582] = { title = "Atal'Dazar: Not All That Glitters...", description = "<As you observe the shrine, it's quite clear that the central jewel is badly broken and in need of replacement.\n\nYou reference your notes on the shrine and discover that these jewels came from a \"golden sanctuary\".\n\nGiven your location, that can only mean Atal'Dazar. Perhaps you could find a replacement from that ancient city.>", objectives = "" }
WordHunterWoW_QuestEN[55583] = { title = "Out With the Old", description = "<Upon inspection of the shrine, you notice something... familiar. The cut of the gems looks like a primitive or simple version of the way you've learned to cut rubellites.\n\nIt's clear though that time has had its way with these gems, some eroded and chipped in places.\n\nRepairing this shrine may be as simple as replacing the old gems with newer ones of the same type and cut.>", objectives = "" }
WordHunterWoW_QuestEN[55585] = { title = "A Promising Beginning", description = "<The shrine now repaired, you find yourself eager to seek out the next shrine.\n\nPerhaps Samuel has come across more locations.>", objectives = "" }
WordHunterWoW_QuestEN[55586] = { title = "Polished Up", description = "<Samuel will surely want to hear about your progress on this shrine.\n\nYou feel as though you should report back to him as soon as you're able.>", objectives = "" }
WordHunterWoW_QuestEN[55590] = { title = "Setting Things Right", description = "<Samuel will surely be interested to hear about your investigation into this shrine.\n\nMost assuredly the part where you had to fight your way through a prison.>", objectives = "" }
WordHunterWoW_QuestEN[55592] = { title = "A Promising Beginning", description = "<The shrine now repaired, you find yourself eager to seek out the next shrine.\n\nPerhaps Seshuli has come across more locations.>", objectives = "" }
WordHunterWoW_QuestEN[55593] = { title = "Insight into Our Enemies", description = "There's no telling what awaits us within this land. We cannot press forward without first knowing exactly what we're up against. \n\nOur new allies have long been embattled with the naga. They would know best how to navigate these waters. \n\nSpeak with Blademaster Okani and see if they can provide some insight into how our enemies operate.", objectives = "" }
WordHunterWoW_QuestEN[55594] = { title = "Polished Up", description = "<Seshuli will surely want to hear about your progress on this shrine.\n\nYou feel as though you should report back to her as soon as you're able.>", objectives = "" }
WordHunterWoW_QuestEN[55595] = { title = "Deteriorating Knowledge", description = "My clan came to Nazjatar, eager to destroy the naga queen. \n\nWe were not prepared for the darkness that she commands. \n\nOur scouts knew this land best, but their knowledge now deteriorates as their minds are controlled by Azshara's forces. \n\nFind and free our scouts, and you may still have a chance to access their knowledge.", objectives = "" }
WordHunterWoW_QuestEN[55596] = { title = "Setting Things Right", description = "<Seshuli will surely be interested to hear about your investigation into this shrine.\n\nMost assuredly the part where you had to fight your way through Atal'Dazar.>", objectives = "" }
WordHunterWoW_QuestEN[55597] = { title = "Bound by Honor", description = "It is true that my clan has been battling the naga for generations, but it was only in recent times that we took the fight to Nazjatar. \n\nOur leader was slain by the vile queen, and now honor binds my clan to this deep ocean. \n\nWe will avenge their death or die here trying. It is our way. \n\nYour mission aligns with our duty, so we will fight the naga together. \n\nSlay their forces and bring us one step closer to honoring our promise.", objectives = "" }
WordHunterWoW_QuestEN[55598] = { title = "What We Know of the Naga", description = "I owe you a debt. That much is clear. \n\nMy mind still reels from the zoatroid's influence, but I fear the others suffer more visible wounds. \n\nApply this salve to their wounds, and I will do my best to share what I know of the naga.", objectives = "" }
WordHunterWoW_QuestEN[55599] = { title = "Scouting Undercover", description = "Entering the stronghold alone would be a death wish. \n\nThe Zanj'ir slaughter outsiders on sight. \n\nThe only way to get in without being killed is to appear to be under the effects of a zoatroid. \n\nEven then, the mind-shackled are put to work. \n\nYou must obey all commands, or they will know your mind is still your own. \n\nOnce the Zanj'ir believe you are mind-shackled, it should be easier to navigate their domain and uncover their secret.", objectives = "" }
WordHunterWoW_QuestEN[55600] = { title = "Sating Snapdragons", description = "It's time for the snapdragons to feed, but it's a job best left to someone a little more expendable. \n\nThe beasts will eat anything, including your arm if you don't move it away quickly enough. \n\nLuckily for you, they've developed a taste for Chitterspine Roe.", objectives = "" }
WordHunterWoW_QuestEN[55601] = { title = "Coveted Crystals", description = "Locating the weapons cache should not be a problem once we have the proper tools. A little light and a lot of bioluminescent fluid is all that is needed.\n\nIt all seems rather simple, does it not? But the key is in the Deepsea Crystal used to refract the light. \n\nThe Bloodfin tribe covets these crystals, so you should have no trouble obtaining one.", objectives = "" }
WordHunterWoW_QuestEN[55602] = { title = "What Will It Lure?", description = "<Putrid and pungent, this lump of bait is the preferred food of skittering eels. Perhaps you can find infested waters nearby?>", objectives = "" }
WordHunterWoW_QuestEN[55605] = { title = "NOT USED", description = "TBD Collect Spare Parts from anything on the island.", objectives = "" }
WordHunterWoW_QuestEN[55608] = { title = "Shop Project", description = "As a reward for all your help here, I was planning to fix this old mechaspider mount to give to you.\n\nI could use some more of your help though to get this project started!\n\nI'll need parts off a few of the bots nearby, and maybe you could talk to Cork Stuttgard at Bondo's Yard and see if you can get a Mechanobot Ignition system.", objectives = "" }
WordHunterWoW_QuestEN[55609] = { title = "Operation: Mechagon - The Mechoriginator", description = "My father's madness won't be contained to this island.\n\nKing Mechagon is creating a massive device capable of reversing the Curse of Flesh across the entirety of Azeroth!\n\nAny races forged by the Titans will return to their original state. For us gnomes, that means fully mechanical. For dwarves and troggs, stone. Vrykul, iron.\n\nThe list goes on, but most races aren't even ON the list. Anything not forged by the titans will be completely obliterated.\n\nWe must stop King Mechagon before it's too late!", objectives = "" }
WordHunterWoW_QuestEN[55618] = { title = "The Heart Forge", description = "Rise in Heart Forge energy levels indicates presence of black dragon essence.\n\nRecommendation: Initiate Heart Forge activation sequence.", objectives = "" }
WordHunterWoW_QuestEN[55622] = { title = "Drive It Away Today", description = "The mount's all polished up and looking great. We are almost done!\n\nI gave the Powercore Schematics to PASCAL-K1N6. He's ready to build us a new 500S-Cybergenic Powercore, once you get him the parts.\n\nWe install that powercore and you can drive this bot away today!", objectives = "" }
WordHunterWoW_QuestEN[55625] = { title = "Pearls of Unimaginable Power", description = "Thousands of years ago, when the Well of Eternity was destroyed and this land plummeted to the depths of the ocean, a great storm of magical energy was unleashed.\n\nRemnants of this magical energy still exist today.\n\nGather the pearls from the ancient mana-infused clams. These enchanted pearls may be powerful weapons in our fight against the naga!", objectives = "" }
WordHunterWoW_QuestEN[55630] = { title = "Let's Get It Started", description = "Those gnomes think busting up machinery is gonna stop a goblin like me from figuring out what all the tech in this place does?\n\nI ain't never seen a hunk of junk so busted up that ol' Skaggit and I can't get running smoother than the day it was made.\n\nTell ya what. You head around with Skaggit and see what you can piece back together.\n\nMeanwhile, I'll have a chat with our gnome friend here and see what she knows about all this tech.", objectives = "" }
WordHunterWoW_QuestEN[55632] = { title = "You Must be This Height", description = "You and the Greasemonkeys got this machine up and running even faster than I expected.\n\nThe gnome we captured is keeping her mouth shut, but that shouldn't be a problem. I can take it from here.\n\nLet me know when you're ready. I'll crank up this machine to max and we'll finally see what it can do.\n\nI hope it prints gold coins...", objectives = "" }
WordHunterWoW_QuestEN[55633] = { title = "The Sunken Chest", description = "<This waterlogged chest appears to be in salvageable condition, but it is too heavy to move due to the contents within.\n\nThe lock on the device appears to be operational.\n\nPerhaps there is a key nearby...>", objectives = "" }
WordHunterWoW_QuestEN[55635] = { title = "A Voice on the Wind", description = "<A distant, mysterious voice fills your mind.>\n\nMy enchantments are not lost...\n\nFind me...\n\nDrustvar...\n\nFallhaven...", objectives = "" }
WordHunterWoW_QuestEN[55636] = { title = "A Life's Work", description = "<A voice whispers to you from beyond the veil of death.>\n\nI spent more than one-thousand years researching the mysteries of the arcane before the Great Sundering tore our world apart.\n\nI perished amidst the destruction and my work was lost.\n\nSearch the area for my ancient writings and put my spirit to rest...", objectives = "" }
WordHunterWoW_QuestEN[55637] = { title = "Poor, Unfortunate Souls", description = "Countless lives were lost in the Great Sundering when this great city was plunged into the depths of the abyss.\n\nThe fortunate among us died quickly in the explosion, but some survived only to cling onto dear life as the cold, unforgiving ocean waves crashed down upon them.\n\nThose poor, unfortunate souls suffer a fate worse than death to this day. They drown endlessly, forced to relive the torture of their death.\n\nPut them to rest so that they may have peace at last.", objectives = "" }
WordHunterWoW_QuestEN[55638] = { title = "Making Kelpberry Wine", description = "<This is an empty kelpberry juice cask.\n\nThere is someone nearby that may appreciate a refill.>", objectives = "" }
WordHunterWoW_QuestEN[55639] = { title = "Who Lurks in the Pit", description = "The winds whisper of people being trapped in the pit. It seems there may be more members of the expedition within.\n\nI fear it will be up to you to make the descent and save the survivors.\n\nThere should be six in total...  though the winds say that one is farther away from the others...\n\nWith our luck, the last survivor is at the bottom of the pit.\n\nGood luck, {name}. And... make sure no spiders follow you back out.", objectives = "" }
WordHunterWoW_QuestEN[55645] = { title = "Princely Visit", description = "This is it! The fabled Mechagon!\n\nThe greatest discovery of our age, and you're here to witness me accomplish it!\n\n<Tinkmaster Overspark puffs out his chest, brushes off his robes, and smiles confidently.>\n\nI am ready to address the Mechagon people. You may accompany me.", objectives = "" }
WordHunterWoW_QuestEN[55646] = { title = "The Legend of Mechagon", description = "Heya, {name}. I was just tellin' Skaggit that I was hoping I'd run into you up here!\n\nI caught wind of an Alliance operation into some old vault that opened in Tiragarde Sound.\n\nIn typical gnomish fashion, Tinkmaster Overspark is overreacting like crazy, claiming it's some lost connection to the gnome fairytale land of Mechagon.\n\n<Gazlowe scoffs.>\n\nI don't buy that for a second, but I am very interested in getting my hands on whatever tech's in that vault. You in?", objectives = "" }
WordHunterWoW_QuestEN[55647] = { title = "A Quick Ear Hustle", description = "Bad news. We're late.\n\nThe Alliance was already crawling all over the vault when we got here.\n\nLucky for us, some big commotion inside sent some of 'em running for the hills.\n\nMost of 'em are still down in that vault, though, including that crazy braggart Tinkmaster Overspark.\n\nLet's give 'em a few more minutes to clear out, so we don't have to go in guns blazing.", objectives = "" }
WordHunterWoW_QuestEN[55648] = { title = "This is Our Vault Now", description = "Looks like the coast is clear with Overspark gone. Let's get inside that vault and see what's really going on here.\n\nMechagon or not, there'd better be some quality hardware in there to make this trip worth our time.", objectives = "" }
WordHunterWoW_QuestEN[55649] = { title = "Machinations for Mechagon", description = "So Mechagon ain't just a fairy tale? Gotta admit I'm surprised.\n\nBut, if the tech on that king is any indication of what they've got out there for us to swipe, I am very, very happy to be wrong!\n\nWe can't rush into this. A good crew died today. That ain't happening again on my watch.\n\nMeet me and Skaggit back in Zuldazar Harbor, and we'll build this expedition up right.", objectives = "" }
WordHunterWoW_QuestEN[55650] = { title = "Only the Best Will Do", description = "You heard Gazlowe. The boss wants this expedition to go smoothly. No cutting corners, no slush.\n\nI know you've worked with Gallywix in the past. We don't run our operations like that.\n\nWe expect the best from our crews, so we pay 'em what they're worth and treat 'em well. In return, we got the best goblin crews on the planet, and they ain't goin' over to any competition.\n\nHere's a list of who and what we're gonna need to pull this off. Don't worry, Gazlowe'll cover all the costs.", objectives = "" }
WordHunterWoW_QuestEN[55651] = { title = "To Mechagon!", description = "Whatever's waiting for us on the shores of Mechagon, we're going to be ready for it with this crew.\n\nI don't hold any misconceptions about how that crazy king is going to welcome us. Guns blazin', I'm sure.\n\nSo we're going in quietly on this submarine. Low profile'll keep us all safe.\n\nWhen you're ready to go, talk to Captain Krooz.", objectives = "" }
WordHunterWoW_QuestEN[55652] = { title = "Prospectus Bay", description = "Looks like we made it in unnoticed.\n\nSkaggit's crew can set up shop on that beach, but we gotta make sure it's safe for 'em to land first.\n\nLet's do a quick flyover to scout out how we're going to crack this place wide open.\n\nThat town up on the hill looks promising...", objectives = "" }
WordHunterWoW_QuestEN[55657] = { title = "In the Shadow of Crimson Wings", description = "It is unlike Alexstrasza to remain out of contact for so long, particularly when the very essences of the dragonflights' power are being made manifest. \n\nWhile our allies here tend to the injured, we must seek out the Life-Binder at once.\n\nWhen you are ready, we shall ride to the Vermillion Redoubt together.", objectives = "" }
WordHunterWoW_QuestEN[55658] = { title = "Clues Abound", description = "Before King Mechagon claimed this island, someone else lived here.  Buried beneath this filth and garbage is the history of a forgotten people. With your help, we shall learn about these previous inhabitants.\n\nSir Finley has marked a location where he's seen unusual artifacts. Meet him there and see if you can discover any clues.", objectives = "" }
WordHunterWoW_QuestEN[55659] = { title = "Relics of the Sundering", description = "It's not every day that you encounter the remnants of a lost civilization beneath the ocean!\n\nI never would have imagined that I'd have the opportunity to explore the lost city of Nazjatar... and on solid ground at that!\n\nThere are many secrets here to uncover. If you come across any ancient highborne artifacts, please bring them to me. These relics could provide us with valuable clues regarding the mysteries of the Great Sundering.\n\nI feel as though we are barely scratching the surface so far...", objectives = "" }
WordHunterWoW_QuestEN[55660] = { title = "Time Trials", description = "", objectives = "" }
WordHunterWoW_QuestEN[55661] = { title = "Fighting Venomous With Venom", description = "There are many uses for the poison of the snapdragons.\n\nImmediate use would be to create antivenin for healing, or harvesting poison for attacking the naga.\n\nLet's get to the root of the issue, literally.\n\nUse some collected venom against a Terrormaw to weaken it. Kill one and bring me their fangs.\n\nI think we can come up with something handy from there.", objectives = "" }
WordHunterWoW_QuestEN[55662] = { title = "Arcane Cache", description = "<The heavily reinforced chest is of naga construction and appears to be reinforced with a magical lock of some kind.\n\nMagical reinforcement aside, the cache still requires a key to unlock.\n\nThe key is most likely being held by one of the nearby naga soldiers.>", objectives = "" }
WordHunterWoW_QuestEN[55663] = { title = "Broken Controller", description = "It is too late for me, my friends.\n\nThe Controllers work us and work us and we have no rest.\n\nWe have lost so many. \n\nPlease, free the others! Don't let them share my fate!", objectives = "" }
WordHunterWoW_QuestEN[55664] = { title = "A Blow to Morale", description = "This place is the source of all of our corruption. \n\nThe kelfin are taken and broken here. \n\nHit them where it hurts. Break their power, kill every naga you see, wreak havoc!\n\nEvery little crack we make, weakens their foundation.", objectives = "" }
WordHunterWoW_QuestEN[55665] = { title = "The Dark Garden", description = "Look, {name}, I know we have bigger battles ahead, but these gardens are horrific.\n\nInnocent creatures captured and imprisoned for the naga's amusement. \n\nThey bring them out, torture them, change them, break them... you get the idea.\n\nHelp me free those the naga have taken, and punish them for their hubris!", objectives = "" }
WordHunterWoW_QuestEN[55667] = { title = "Short-Supply Reward", description = "", objectives = "" }
WordHunterWoW_QuestEN[55668] = { title = "Short-Supply Reward", description = "", objectives = "" }
WordHunterWoW_QuestEN[55669] = { title = "Encrypted Radio Receiver TBD", description = "NYI - Will add Black Market viewing NPC in town", objectives = "" }
WordHunterWoW_QuestEN[55672] = { title = "A Historical Mess", description = "The text on this parchment appears to be Tortollan. Is it possible that Tortollans once resided on this island?  \n\nWe need to act quickly, before the creatures in this area destroy anymore evidence. Search the area for any signs of Tortollan relics.", objectives = "" }
WordHunterWoW_QuestEN[55681] = { title = "Crab Marks The Spot", description = "<This appears to be the remains of some kind of treasure map. However, the map is in poor condition after so many years of being subjected to the ocean.\n\nAccording to the map, the treasure should be somewhere nearby; but it's impossible to tell what exact location is from the ruined map.>", objectives = "" }
WordHunterWoW_QuestEN[55683] = { title = "Forgotten Memories", description = "Have we met before? I'm sorry... but I don't remember your name.\n\nMy name is... Arylina... I think. My memory has been so foggy since the great explosion happened that sent us underwater.\n\nOh! But look! I can see the sun and the stars again... I wonder what happened?\n\nI used to keep a diary, but I can't find it anywhere. If I just had my diary back, I'm sure I could remember more.\n\nWill you help me find it?", objectives = "" }
WordHunterWoW_QuestEN[55685] = { title = "We Come in Peace... and Profit", description = "King Mechagon won't be happy we're on his island.\n\nBut a cruel king like that is gonna have enemies. You and I know that better than most, yeah?\n\nWhile Skaggit and the crew get our foothold dug in here, you and I are gonna find some potential allies to shield us from King Mechagon's wrath.\n\nThose two guards ran into that junkheap town up the hill. That place don't smell of royalty to me... Let's check there first.", objectives = "" }
WordHunterWoW_QuestEN[55688] = { title = "A Growing Mystery", description = "This runestone could be of Vrykul origins. Is it possible that Vrykul once visited this island? \n\nWhere there's one runestone, there's usually more. The roots of lashers are drawn to the magic of runestones. If there are more buried here, the Lasher roots maybe wrapped around them!\n\nClear these lashers and see if any have runestones tangled in their roots.", objectives = "" }
WordHunterWoW_QuestEN[55693] = { title = "UNusued", description = "Get to it, history is waiting for you!", objectives = "" }
WordHunterWoW_QuestEN[55694] = { title = "There's Something in the Water", description = "The Ankoan must contend with threats from not only the naga, but also the horrors of N'Zoth. We learned early that if we allow his infection even the smallest purchase, he will grow and corrupt everything.\n\nThere is a great evil who is lingering near the waterway that flows through this place. It must be dealt with.", objectives = "" }
WordHunterWoW_QuestEN[55695] = { title = "That New Mount Smell", description = "Once every week, Mechagon expels a lot of excess oils through the outflow. That's why the place is a toxic mess!\n\nToday they expelled a batch of Golden Cogpaste. The stuff is amazing! I make air fresheners out of it. Makes any mount smell like it's brand new!\n\nCheck all the pipes in the outflow, and see if you can collect some of this paste.", objectives = "" }
WordHunterWoW_QuestEN[55696] = { title = "Test Drive", description = "There's still a lot of work to do, but it's running! We need to give the engine, brakes and gyro-balance actuator a good test. \n\nYou want to take it out for a drive and see how well they work?", objectives = "" }
WordHunterWoW_QuestEN[55697] = { title = "A Little Leg Work", description = "The legs and shocks on this mount are shot! We'll need some new ones if we're going to get this mount crawling.\n \nA few weeks ago, Bondo and his gang rode into the Scrapbone Den hoping to scare the Troggs off. The Troggs tore their crawlers apart! The parts for those crawlers are still laying all around Scrapbone Den.\n\nSee if you can get us some of those parts from the Troggs.", objectives = "" }
WordHunterWoW_QuestEN[55701] = { title = "Snapdragon Claws", description = "Snapdragons are savage creatures that hunt in packs. Their presence in Nazjatar requires us to stay vigilant at all times.\n\nThey are crafty beasts, preferring to ambush their prey when it is weak or wounded. We will need to reduce the number of snapdragons in the area.\n\nThe last thing we need after a battle with the naga is to be finished off by a pack of blood-thirsty snapdragons!\n\nHunt down any nearby snapdragons and bring me a claw from each kill so that I may keep track of their numbers.", objectives = "" }
WordHunterWoW_QuestEN[55707] = { title = "First One's Free", description = "The pocket-sized computational device can accept punch cards to upgrade and modify its performance.\n\nI could give you a punch card, but a particularly crafty trogg, Moch'k Eight-Thumbs, stole my satchel full of cards. \n\nKill Moch'k Eight-Thumbs, recover my satchel, and I'll set you up with a punch card for free.", objectives = "" }
WordHunterWoW_QuestEN[55708] = { title = "Upgraded", description = "Well, look at you, {race}...\n\n<Christy's mechanical eyes quickly scan your body.>\n\nNot as impressive as I had hoped.\n\nKing Mechagon's armies are fully mechanized. But, you... you have a severe excess of flesh and matching machinery deficiency.\n\nYes, we simply must make a few changes... Maybe a neural-cranial upgrade!\n\nBring me a few microcogs from the motospiders nearby and I'll fix you up!", objectives = "" }
WordHunterWoW_QuestEN[55714] = { title = "Void Cache", description = "<The heavily reinforced chest is of naga construction and appears to be reinforced with a magical lock of some kind.\n\nMagical reinforcement aside, the cache still requires a key to unlock.\n\nThe key is most likely being held by one of the nearby naga soldiers.>", objectives = "" }
WordHunterWoW_QuestEN[55715] = { title = "Feed Them All", description = "When we're doing our job right, we always have more mouths to feed!\n\nIf you could help with my stock, we could care for even more.\n\nBig, strong friends are what this revolution needs!", objectives = "" }
WordHunterWoW_QuestEN[55717] = { title = "Time for Heroics", description = "That card you found was a gold rare Huolon! \n\nI think that card belonged to Adalin Halfheight, one of our junior explorer league members.  If he dropped it, he and our other junior members maybe in trouble!\n\nWe need to find Leona Mistcaller, Dunkin Crackjaw, and Adalin Halfheight immediately!", objectives = "" }
WordHunterWoW_QuestEN[55718] = { title = "Strange Discovery", description = "<A very old ring of Nightelf origin. Seems out of place on this island, perhaps Elise Starseeker will know what to make of it>", objectives = "" }
WordHunterWoW_QuestEN[55719] = { title = "Requisition: A Few Starfish", description = "Our forward scouts have been using starfish scales as camouflage. The trouble is that the scales deteriorate too quickly. We are going to need more scales if we want to keep tabs on naga movements.\n\nIf you happen upon any Angel Scale Starfish, please deliver them to the quartermaster as soon as possible.", objectives = "" }
WordHunterWoW_QuestEN[55720] = { title = "Requisition: A Few Seaweed", description = "We have so many wounded and we are dangerously low on seaweed bandages. If you find Sticky Seaweed, please give it to the quartermaster.", objectives = "" }
WordHunterWoW_QuestEN[55721] = { title = "Requisition: A Few Kelp Buds", description = "We need rations for our forces. While kelp buds do not have the same delicious taste as other options, it is nutritious and plentiful near any kelp forests. This makes it our first choice for making rations.\n\nIf you happen to find any around Nazjatar, please leave your stores with the quartermaster. The ones freshly fallen from kelp are best.", objectives = "" }
WordHunterWoW_QuestEN[55722] = { title = "Requisition: A Few Pearls", description = "<This letter bears the seal of the quartermaster.>\n\nSupplies needed!\n\nWe are dangerously low on pearls. Anyone carrying Luminous Pearls, please leave your stores with the quartermaster.", objectives = "" }
WordHunterWoW_QuestEN[55723] = { title = "Requisition: A Few Carp", description = "Our local sea life is in danger! If you spot a fish out of water, please return it to the nearest lake, stream, or river. Conservation is everyone's responsibility!", objectives = "" }
WordHunterWoW_QuestEN[55724] = { title = "Requisition: A Few Deepcoral Buds", description = "Many species feed on the deepcoral buds from the tall columns that grow in the east. Fathom rays feed on these buds especially. We use the buds as lures for fathom rays to use as mounts. But with our stores so low, we will not be able to provide the air support we need across Nazjatar.\n\nIf you could gather more Deepcoral Buds and return them to the quartermaster, you will surely be rewarded.", objectives = "" }
WordHunterWoW_QuestEN[55725] = { title = "Requisition: A Few Spiral Leaf", description = "We are dangerously low on our medicine stores. If you find any Spiral Leaf, please leave your stores with the quartermaster.\n\nI should warn you, Spiral Leaf is immensely poisonous. Make sure to handle it with care. Some symptoms of spiral leaf poisoning include bouts of rage, immense bursts of strength, and murderous impulses. If you are exposed, find some naga and use your murderous energy for good.", objectives = "" }
WordHunterWoW_QuestEN[55726] = { title = "Requisition: A Few Cone Shells", description = "If we are going to arm ourselves against the naga, we will need far more supplies and armaments. Cone Shells make most of our armor and weapons. It's light, it's strong, and it's plentiful in this region. However, our supplies are running short and our forces need support.\n\nIf you find yourself carrying Impregnable Cone Shells, please leave your stores with the quartermaster.", objectives = "" }
WordHunterWoW_QuestEN[55727] = { title = "Requisition: A Few Flotsam", description = "I have seen piles of flotsam in the sands to the west. If you could go out and scrounge anything useful from the debris, it could prove useful. Beware, that area is a hydra breeding ground and they have been growing more aggressive since the water receded.\n\nOnce you've gathered some supplies, return to the quartermaster for your reward.", objectives = "" }
WordHunterWoW_QuestEN[55728] = { title = "Reinforced Cache", description = "<The heavily reinforced chest is of naga construction and appears to be reinforced with a heavy-duty lock of some kind.\n\nReinforcement aside, the cache still requires a key to unlock.\n\nThe key is most likely being held by one of the nearby naga soldiers.>", objectives = "" }
WordHunterWoW_QuestEN[55729] = { title = "The Resistance Needs YOU!", description = "Rustbolt isn't usually in this level of malfunction.\n\nKing Mechagon attacked our town last night. His mechanical armies captured many members of the Rustbolt Resistance and destroyed as much as they could before we drove them out.\n\nThe prisoners are being processed at Junkwatt Depot. After that, they'll be transferred down into King Mechagon's underground city... for full mechanization.\n\nWe can't let that happen. Will you help me rescue them?", objectives = "" }
WordHunterWoW_QuestEN[55730] = { title = "Rescuing the Resistance", description = "King Mechagon is ruthlessly efficient. He only expends resources to kidnap those he deems worthy.\n\nThe rest, he... discards.\n\n<Prince Erazmin grimaces.>\n\nWe will deal with my father, King Mechagon, another day.\n\nThis information is more immediately relevant in that my father's predictability means our top scientists, engineers, and tinkerers should all be trapped, alive, somewhere in this depot.\n\nWe will find them, and break them out.", objectives = "" }
WordHunterWoW_QuestEN[55731] = { title = "My Father's Armies", description = "My father was once a good leader. He envisioned a brighter future for his people, and did everything in his power to help us acquire it.\n\nBut when his vision became misaligned with the dreams of his people, he failed to adapt. Instead, he grew rigid, forcing his will on others.\n\nIn secret experiments, he began fully mechanizing the bodies of those who resisted him.\n\nIt was horrible to watch... there was nothing left of the original gnomes who followed him willingly.\n\nOnly robots remained. Slaves.", objectives = "" }
WordHunterWoW_QuestEN[55732] = { title = "An Old Scar", description = "We've got a new problem, champion. Another grievous wound has opened up, this time at the Maelstrom!\n\nThe shaman there are in deep trouble, an' they need our help!\n\nSpeak tae MOTHER. She'll get ye tae the Maelstrom. I'll meet ye there.", objectives = "" }
WordHunterWoW_QuestEN[55734] = { title = "Drill Rig Construction", description = "<Prince Erazmin sifts through the resources you both collected.>\n\nYes... This appears to be sufficient material to repair that drill rig.\n\nI'll do what I can with the parts that I have, but you will need to complete the repairs with yours.\n\nWhen you're ready, return to that broken drill rig we found and open it up.\n\nTogether, we'll have it up and running in no time.", objectives = "" }
WordHunterWoW_QuestEN[55735] = { title = "Defending the Maelstrom", description = "The shaman of the Earthen Ring are powerful, but this is more than even they can handle! And from the sound o' it, some o' their own are still trapped down below.\n\nLike ye did in Nordrassil, use yer Heart of Azeroth tae seal up the wounds inflicted here. An' lay any crazed elementals tae rest before they make even more o' a mess.", objectives = "" }
WordHunterWoW_QuestEN[55736] = { title = "Welcome to the Resistance", description = "Life in the Rustbolt Resistance is not easy, {name}.\n\nBut it is yours. We will not order you around or force you to fight. Mechagon is a land of endless opportunities, and you may chase whichever opportunities you see fit.\n\nOf course, if you'd like suggestions for which improvements you most require, myself or any of the other mechagnomes in town will be happy to advise you of your current weaknesses.\n\nBut, for now, I ask simply that you walk with me to my workshop.", objectives = "" }
WordHunterWoW_QuestEN[55737] = { title = "At the Azerite Time", description = "Ye did it! Ye stopped the damage before it could get any worse!\n\nThe Maelstrom will always be a place o' great history an' pain fer Azeroth, but any little bit we do will make things better. Who knows, maybe we can even heal Silithus one day!\n\nI'll meet ye back in the Chamber o' Heart. MOTHER's sure tae be interested in what happened here.", objectives = "" }
WordHunterWoW_QuestEN[55738] = { title = "TBD NOT USED", description = "TBD", objectives = "" }
WordHunterWoW_QuestEN[55739] = { title = "Back to the Chamber", description = "The Heart o' Azeroth is gettin' stronger every day, and it's makin' a difference.\n\nMake yer way tae the Chamber o' Heart, champion. Yer talents are needed.", objectives = "" }
WordHunterWoW_QuestEN[55740] = { title = "TBD NOT USED", description = "TBD", objectives = "" }
WordHunterWoW_QuestEN[55742] = { title = "Bundle of Corroded Parts", description = "", objectives = "" }
WordHunterWoW_QuestEN[55743] = { title = "More Recycling", description = "<Recycling is fun and profitable. The Recyclerizer DX-82 stands ready to receive more scrap metal.>", objectives = "" }
WordHunterWoW_QuestEN[55750] = { title = "WANTED: Lady Naz'jess", description = "Wanted for attacks against the Alliance!\n\nLady Naz'jess is responsible for leading several raids and ambushes against our soldiers. Extreme caution advised!\n\nUpon completion of the mission, report to Lieutenant Hawkins for commendation.", objectives = "" }
WordHunterWoW_QuestEN[55751] = { title = "The Heart of the Water", description = "You see a lot up here. \n\nEven the water is a slave to the will of the naga.\n\nI believe we can help them reform away from here.\n\nBring back what you can!", objectives = "" }
WordHunterWoW_QuestEN[55752] = { title = "We Stand United", description = "The work ye've done tae empower the Heart o' Azeroth cannae be understated! With this power, we might just stand a chance o' savin' the world.\n\nIt's been a long fight fer certain, an' there is still more tae do. But fer now, we've got a little gift fer ye!\n\nLet me know when yer ready, champion.", objectives = "" }
WordHunterWoW_QuestEN[55753] = { title = "Knock His Bot Off", description = "I need to rebuild the main powercore. It's a 500S Mekronic so I'll need the operational schematics to get the work done. Only person I know who has a copy of that is Bondo Bigblock.\n\nWe're going to need Bondo's help to finish this. Maybe if you ask him, he'll lend us his schematics.", objectives = "" }
WordHunterWoW_QuestEN[55763] = { title = "The Rescue of Meredy Huntswell", description = "Our expedition's mage, Meredy Huntswell, is being held by the harpies!\n\nWe've got to stop their ritual and rescue Meredy.\n\nYou lead the charge. Kee-La and I will back you up if things look dire.", objectives = "" }
WordHunterWoW_QuestEN[55764] = { title = "Harpy Culling", description = "The harpies are preparing for a dreadful assault, {name}. \n\nThey plan to attack our allies back at camp! \n\nHarpies swoop in and snatch their victims before bringing them back to their nests... to feast.\n\nWe have to stop them. Slay the harpies and their worgs to ensure their forces are too weak to stage an assault.", objectives = "" }
WordHunterWoW_QuestEN[55765] = { title = "Bugs, Lots of 'Em!", description = "You got a problem with mechanical bugs, so the Roughriders are here to sort this mess out!\n\nIn my experience, this big of an outbreak must have some sort of queen bug behind it all. We gonna go in, kill a lot of bugs till we find the leader of 'em all.\n\nHorde or Alliance don't matter, you're with the Roughriders today. Let's kill some bugs!", objectives = "" }
WordHunterWoW_QuestEN[55766] = { title = "She Sells These Shells", description = "Suva is so proud of her seashells. \n\nAfter everything she has done for our people, helping her supplies is the least we can do!\n\nHead down the hill and pick up some of the shiniest seashells you can find!\n\nYou will make her day.", objectives = "" }
WordHunterWoW_QuestEN[55767] = { title = "Misdirection", description = "We came in friendship and those pesky murlocs jumped us and stole my treasure.\n\nThey threw it in one of those big clams and ran off into the village.\n\nThey keep moving them around and I have no idea where it is now!\n\nCan you please help?", objectives = "" }
WordHunterWoW_QuestEN[55768] = { title = "Emergent Sea Weeds", description = "There is a special kind of kelp that only grows near the vents.\n\nOur healers use these to help treat our friends in Newhome.\n\nMy kind don't have much of a chance down there, but you do!\n\nGather up some of the vent kelp sprouts in the Dragon's Teeth Basin and bring them to Nevin.", objectives = "" }
WordHunterWoW_QuestEN[55770] = { title = "WANTED: Commander Sarj'eth", description = "Wanted for attacks against the Alliance!\n\nCommander Sarj'eth is responsible for leading several raids and ambushes against our soldiers.\n\nLast seen near the vicinity of this command poster.\n\nExtreme caution advised!\n\nUpon completion of the mission, report to Lieutenant Hawkins for commendation.", objectives = "" }
WordHunterWoW_QuestEN[55771] = { title = "WANTED: Lord Ha'kass", description = "Wanted for attacks against the Alliance!\n\nLord Ha'kass is responsible for leading several raids and ambushes against our soldiers.\n\nLast seen near the vicinity of this command poster.\n\nExtreme caution advised!\n\nUpon completion of the mission, report to Lieutenant Hawkins for commendation.", objectives = "" }
WordHunterWoW_QuestEN[55772] = { title = "WANTED: Lady Narjiss", description = "Wanted for attacks against the Alliance!\n\nLady Narjiss is responsible for leading several raids and ambushes against our soldiers. Extreme caution advised!\n\nUpon completion of the mission, report to Lieutenant Hawkins for commendation.", objectives = "" }
WordHunterWoW_QuestEN[55773] = { title = "WANTED: Gler'thogg", description = "Wanted for attacks against the Alliance!\n\nGler'thogg is responsible for the gruesome deaths of several of our best soldiers. Extreme caution advised!\n\nUpon completion of the mission, report to Lieutenant Hawkins for commendation.", objectives = "" }
WordHunterWoW_QuestEN[55774] = { title = "WANTED: Inquisitor Ithriza", description = "Wanted for attacks against the Alliance!\n\nInquisitor Ithriza is responsible for leading several raids and ambushes against our soldiers.\n\nLast seen near the vicinity of this command poster.\n\nExtreme caution advised!\n\nUpon completion of the mission, report to Lieutenant Hawkins for commendation.", objectives = "" }
WordHunterWoW_QuestEN[55775] = { title = "WANTED: Haggronar", description = "Wanted for attacks against the Alliance!\n\nHaggronar is responsible for the gruesome deaths of several of our finest soldiers. Extreme caution advised!\n\nUpon completion of the mission, report to Lieutenant Hawkins for commendation.", objectives = "" }
WordHunterWoW_QuestEN[55776] = { title = "WANTED: Emorneth", description = "Wanted for attacks against the Alliance!\n\nEmorneth is responsible for the gruesome deaths of several of our best soldiers. Extreme caution advised!\n\nUpon completion of the mission, report to Lieutenant Hawkins for commendation.", objectives = "" }
WordHunterWoW_QuestEN[55777] = { title = "WANTED: Braxicus", description = "Wanted for attacks against the Alliance!\n\nBraxicus is responsible for the gruesome deaths of several of our finest soldiers.\n\nLast seen near the vicinity of this command poster.\n\nExtreme caution advised!\n\nUpon completion of the mission, report to Lieutenant Hawkins for commendation.", objectives = "" }
WordHunterWoW_QuestEN[55778] = { title = "Visions of Danger", description = "{name}, Spiritwalker Ussoh has revealed a disturbing vision to me regarding Baine Bloodhoof.\n\nHe has asked that you speak with him as soon as you can.\n\nReturn to me after. We will have much to discuss.", objectives = "" }
WordHunterWoW_QuestEN[55779] = { title = "Stay of Execution", description = "Come. It is time to save a friend.", objectives = "" }
WordHunterWoW_QuestEN[55780] = { title = "Old Allies", description = "Sylvanas was my Ranger-General. I have respected her for millennia. Making this choice is something I have been wrestling with for some time. Baine's death will tear the Horde apart. The Tauren will not stand for it and if they leave, I know they will not be the last.\n\nWe must save Baine. Not just for his life, but for the Horde. I can only hope once the time pressure is gone we may be able to reason with her but... \n\nI have contacted allies who will help. Meet them in the Cleft of Shadows.", objectives = "" }
WordHunterWoW_QuestEN[55781] = { title = "Old Allies", description = "Sylvanas Windrunner was once my ranger-general. Now she is my warchief. Through peacetime and war, I followed her orders.\n\nUntil now.\n\nBaine is a noble soul. His execution would drive a blade into the very heart of the Horde.\n\nWe must save him, {name}. It is the only way to preserve who we are. What we stand for.  \n\nI have reached out to allies who will help you. But in siding with them, you will put your own life in peril.\n\nIf you feel as I do, then meet them in the Cleft of Shadows. Good luck.", objectives = "" }
WordHunterWoW_QuestEN[55782] = { title = "Stay of Execution", description = "Baine's time is short. We must act now.", objectives = "" }
WordHunterWoW_QuestEN[55783] = { title = "Stay of Execution", description = "When I was younger, Baine Bloodhoof and I began exchanging letters. Through our unlikely friendship, I learned that there was nobility in the Horde.\n\nHe proved that by defying Sylvanas when she planned to strip the free will from Derek Proudmoore. That act of nobility will cost him his life... unless we intervene.\n\nIf there is to be peace in Azeroth, our hope depends upon good people doing the right thing. People like Baine. People like you.\n\nPlease, go with Jaina. Save my friend and see him home.", objectives = "" }
WordHunterWoW_QuestEN[55784] = { title = "Payment in Kind", description = "{name}, King Anduin has requested our presence in Stormwind.\n\nWe've sent him reports on our situation here in Nazjatar, and he understands the severity of the threat we're facing. For him to pull both of us back from the front lines, it must be a matter of grave importance.\n\nI will meet you in Stormwind Keep.", objectives = "" }
WordHunterWoW_QuestEN[55785] = { title = "Requisition: More Starfish", description = "Our forward scouts have been using starfish scales as camouflage. The trouble is that the scales deteriorate too quickly. We are going to need more scales if we want to keep tabs on naga movements.\n\nIf you happen upon any Angel Scale Starfish, please deliver them to the quartermaster as soon as possible.", objectives = "" }
WordHunterWoW_QuestEN[55786] = { title = "Requisition: More Seaweed", description = "We have so many wounded and we are dangerously low on seaweed bandages. If you find Sticky Seaweed, please give it to the quartermaster.", objectives = "" }
WordHunterWoW_QuestEN[55787] = { title = "Requisition: More Kelp Buds", description = "We need rations for our forces. While kelp buds do not have the same delicious taste as other options, it is nutritious and plentiful near any kelp forests. This makes it our first choice for making rations.\n\nIf you happen to find any around Nazjatar, please leave your stores with the quartermaster. The ones freshly fallen from kelp are best.", objectives = "" }
WordHunterWoW_QuestEN[55788] = { title = "Requisition: More Pearls", description = "<This letter bears the seal of the quartermaster.>\n\nSupplies needed!\n\nWe are dangerously low on pearls. Anyone carrying Luminous Pearls, please leave your stores with the quartermaster.", objectives = "" }
WordHunterWoW_QuestEN[55789] = { title = "Requisition: More Carp", description = "Our local sea life is in danger! If you spot a fish out of water, please return it to the nearest lake, stream, or river. Conservation is everyone's responsibility!", objectives = "" }
