WordHunterWoW_QuestEN[55791] = { title = "Requisition: More Spiral Leaf", description = "We are dangerously low on our medicine stores. If you find any Spiral Leaf, please leave your stores with the quartermaster.\n\nI should warn you, Spiral Leaf is immensely poisonous. Make sure to handle it with care. Some symptoms of spiral leaf poisoning include bouts of rage, immense bursts of strength, and murderous impulses. If you are exposed, find some naga and use your murderous energy for good.", objectives = "" }
WordHunterWoW_QuestEN[55792] = { title = "Requisition: More Cone Shells", description = "If we are going to arm ourselves against the naga, we will need far more supplies and armaments. Cone Shells make most of our armor and weapons. It's light, it's strong, and it's plentiful in this region. However, our supplies are running short and our forces need support.\n\nIf you find yourself carrying Impregnable Cone Shells, please leave your stores with the quartermaster.", objectives = "" }
WordHunterWoW_QuestEN[55793] = { title = "Requisition: More Flotsam", description = "I have seen piles of flotsam in the sands to the west. If you could go out and scrounge anything useful from the debris, it could prove useful. Beware, that area is a hydra breeding ground and they have been growing more aggressive since the water receded.\n\nOnce you've gathered some supplies, return to the quartermaster for your reward.", objectives = "" }
WordHunterWoW_QuestEN[55795] = { title = "Mountain On the Move", description = "I have seen such fervor only once before.\n\nIn times of peril, Torcali may call upon her children to defend her and those she looks after.\n\nIt is likely she called your beast away. Go to her and see how you can help.", objectives = "" }
WordHunterWoW_QuestEN[55796] = { title = "Heresy at the Crossroad", description = "<Torcali's voice enters your mind.>\n\nMy followers undertook a pilgrimage to a place called the Antul'Mita Plateau. It is regarded as the crossroads of Zandalar among my faithful and is the site of a Greater Wayshrine.\n\nI sense some great peril has fallen upon them.\n\nI have sent my children and my champion, Jo'nok, to their aid. Your charge is among them. Go to her and ensure that my acolytes reach the shrine safely.\n\nLet nothing stand in your way.", objectives = "" }
WordHunterWoW_QuestEN[55797] = { title = "The Direhorn Mother's Fury", description = "This one protects de faithful who still seek de shrine.\n\nYou will take your companion and show them de fury of a mother direhorn.\n\nTrust in your young friend. She has always known how to fight.\n\nOpen de way. Slay de heretics that defile our loa's shrine.", objectives = "" }
WordHunterWoW_QuestEN[55798] = { title = "Wander Not Alone", description = "She is here. I can feel her eyes upon us.\n\nMy loa is generous. She will reward you for de service you have given her.\n\nGreat Wanderer guide your path, {name}.", objectives = "" }
WordHunterWoW_QuestEN[55799] = { title = "The Tide Turns", description = "The time to strike is now. We must take the Tidestone of Golganneth and the Javelin of Suramar is our best chance of piercing the barrier around it.\n\nEvery minute we wait is another minute when the sea can come crashing down on us. What forces we have will be arrayed below, just outside their encampment.\n\nWe will need your strength in addition to the Javelin, {name}. We do not have enough forces to take it on our own.", objectives = "" }
WordHunterWoW_QuestEN[55801] = { title = "Requisition: We Need It All", description = "We are dangerously low on all of our supplies. Please, you must go out and collect as much as you can.\n\nPlease return with any resources you find to the quartermaster!", objectives = "" }
WordHunterWoW_QuestEN[55802] = { title = "Requisition: Lots of Seaweed", description = "Supplies needed!\n\nWe are dangerously low on seaweed bandages. Anyone carrying Sticky Seaweed, please leave your stores with the quartermaster.", objectives = "" }
WordHunterWoW_QuestEN[55803] = { title = "Requisition: Lots of Kelp Buds", description = "Supplies needed!\n\nWe need rations for our forces. While kelp buds do not have the same delicious taste as other options, it is nutritious and plentiful near any kelp forests. This makes it our first choice for making rations.\n\nIf you happen to find any around Nazjatar, please leave your stores with the quartermaster. The ones freshly fallen from kelp are best.", objectives = "" }
WordHunterWoW_QuestEN[55804] = { title = "Requisition: Lots of Pearls", description = "Supplies needed!\n\nWe are dangerously low on pearls. Anyone carrying Luminous Pearls, please leave your stores with the quartermaster.", objectives = "" }
WordHunterWoW_QuestEN[55805] = { title = "Requisition: Lots of Carp", description = "Alert!\n\nLocal fish species in danger! Anyone who spots a fish out of water, please return it to the nearest lake, stream, or river. Conservation is everyone's responsibility!", objectives = "" }
WordHunterWoW_QuestEN[55806] = { title = "Requisition: Lots of Deepcoral Buds", description = "Supplies needed!\n\nMany species feed on the deepcoral buds from the tall columns that grow in the east. Fathom rays feed on these buds especially. We use the buds as lures for fathom rays to use as mounts. But with our stores so low, we will not be able to provide the air support we need across Nazjatar.\n\nIf you could gather more Deepcoral Buds and return them to the quartermaster, you will surely be rewarded.", objectives = "" }
WordHunterWoW_QuestEN[55807] = { title = "Requisition: Lots of Spiral Leaf", description = "Supplies needed!\n\nWe are dangerously low on our medicine stores. Anyone carrying any Spiral Leaf, please leave your stores with the quartermaster.\n\nWARNING: Spiral Leaf is immensely poisonous. Handle with care! Symptoms of spiral leaf poisoning include bouts of rage, immense bursts of strength, and murderous impulses. If exposed, seek your nearest naga and use your murderous energy for good.", objectives = "" }
WordHunterWoW_QuestEN[55808] = { title = "Requisition: Lots of Cone Shells", description = "Supplies needed!\n\nIf we are going to arm ourselves against the naga, we will need far more supplies and armaments. Cone Shells make most of our armor and weapons. It's light, it's strong, and it's plentiful in this region. However, our supplies are running short and our forces need support.\n\nAnyone carrying Impregnable Cone Shells, please leave your stores with the quartermaster.", objectives = "" }
WordHunterWoW_QuestEN[55809] = { title = "Requisition: Lots of Flotsam", description = "Supplies needed!\n\nI've seen piles of flotsam in the sands to the west. If you could go out and scrounge anything useful from the debris, it could prove useful. Beware, that area is a hydra breeding ground and they have been growing more aggressive since the water receded.\n\nOnce you've gathered some supplies, return to the quartermaster for your reward.", objectives = "" }
WordHunterWoW_QuestEN[55813] = { title = "Aim High", description = "This conspiracy of ravens is preying on citizens of Rustbolt, it's unacceptable! \n\nPrince Erazmin has asked me to reduce their numbers, but I could really use your help. Can you help me kill some of them? \n\nUse my marker gun if you need it. I'll blast the ones you mark, and help bring them down.", objectives = "" }
WordHunterWoW_QuestEN[55815] = { title = "Other Interests", description = "Madam Goya is interested in many unusual items other than just rare metals.\n\nKeep an eye out for these particular items during your travels in Nazjatar.\n\nDeliver them to me and Madam Goya will consider you for special access.", objectives = "" }
WordHunterWoW_QuestEN[55816] = { title = "The Other Place", description = "In my travels of the many possible futures, I discovered another place much like Rustbolt, but different.\n\nIn this other time and place, very little is alive, everything is machines.\n \nYou must travel to this other place. You will scan the memory banks of the Clockwork Giants you find there. Then we will use that data to ensure that our Rustbolt never becomes the other place.", objectives = "" }
WordHunterWoW_QuestEN[55818] = { title = "Bounty: A Few Naga", description = "The naga are our true enemy. All other efforts in Nazjatar are second to disrupting the naga's operations. If you want to be an asset to our cause then destroying the enemy is a quick way to earn your way here.\n\nWhen you have completed your task, report to the quartermaster to claim your reward.", objectives = "" }
WordHunterWoW_QuestEN[55819] = { title = "Bounty: A Few Murlocs", description = "While murlocs are often only a nuisance, certain factions are becoming more of a danger to our people. It is time we work together to preserve our safety while moving about Nazjatar.\n\nPut an end to some of the more aggressive murlocs and the quartermaster will award you.", objectives = "" }
WordHunterWoW_QuestEN[55820] = { title = "Bounty: A Few Hydras", description = "Our forces are desperately outmatched when it comes to the hydras. They are ferocious, tenacious, and deadly. We have retreated almost entirely out of the western region of Nazjatar.\n\nIf we are going to hold the line against the naga, we need to make sure the western region is safe for our forces. Destroy as many hydras as you can manage, then report to the quartermaster.", objectives = "" }
WordHunterWoW_QuestEN[55821] = { title = "Bounty: A Few Coral Ancients", description = "Coral ancients are beginning to awaken from their long slumber. I warn you, these are very dangerous creatures of immense size and power. If more of them begin to awaken, our forces will be in great danger.\n\nOnce you have defeated some of these ancients, report to the quartermaster to claim your reward.", objectives = "" }
WordHunterWoW_QuestEN[55822] = { title = "Bounty: A Few Makrura", description = "The makrura have been a thorn in our side for too long. They are aggressive towards almost all species in Nazjatar and are very dangerous in groups. Less of them in our waters would certainly benefit our cause.\n\nOnce you are done, report to the quartermaster to claim your reward.", objectives = "" }
WordHunterWoW_QuestEN[55823] = { title = "Bounty: A Few Crabs", description = "The crab population is expanding too quickly within Nazjatar, endangering local plant life. Cull their numbers in our conservation effort.\n\nReport to the quartermaster to claim your reward.", objectives = "" }
WordHunterWoW_QuestEN[55824] = { title = "Bounty: A Few Snapdragons", description = "Snapdragons are one of the most dangerous species on Nazjatar. The naga breed them for the viciousness and their ability as trackers.\n\nIf we hope to keep our positions hidden from the naga, we must take out these groups of snapdragons immediately.\n\nAfter you are done, report to the quartermaster to claim your reward.", objectives = "" }
WordHunterWoW_QuestEN[55825] = { title = "Bounty: A Few Fathom Rays", description = "The fathom ray population is eating all of the coral buds to the east. If we do not cull their numbers, we may have an environmental catastrophe on our hands.\n\nOnce you have finished, report to the quartermaster to claim your reward.", objectives = "" }
WordHunterWoW_QuestEN[55826] = { title = "Bounty: A Few Elementals", description = "<This letter bears the seal of the quartermaster.>\n\nThe elemental population is disrupting endeavors within Nazjatar. Kill on sight.\n\nReport to the quartermaster to claim your reward.", objectives = "" }
WordHunterWoW_QuestEN[55827] = { title = "Bounty: More Naga", description = "The naga are our true enemy. All other efforts in Nazjatar are second to disrupting the naga's operations. If you want to be an asset to our cause then destroying the enemy is a quick way to earn your way here.\n\nWhen you have completed your task, report to the quartermaster to claim your reward.", objectives = "" }
