WordHunterWoW_QuestEN[55836] = { title = "Bounty: Elite Naga Forces", description = "Strike at the elite naga forces within Nazjatar. Once we remove some of their leadership, our people will be able to move about more freely.\n\nReport to the quartermaster to claim your reward.", objectives = "" }
